let __MES_BOOT_DATA = null;
const localStorage = (function(){
  // MES LION V39.6: persistência otimizada.
  // - bootstrap único sem dupla codificação do banco;
  // - gravações grandes são assíncronas e consolidadas (debounce);
  // - somente a última alteração pendente é enviada ao disco.
  let mem={};
  let pendingData=null;
  let dataTimer=null;
  let inflight=false;
  let retryTimer=null;
  let authenticated=false;

  function xhrSync(method,url,body){
    const x=new XMLHttpRequest();
    x.open(method,url,false);
    if(body!==undefined) x.setRequestHeader('Content-Type','text/plain; charset=utf-8');
    x.send(body===undefined?null:body);
    if(x.status>=200&&x.status<300) return x.responseText;
    throw new Error('HTTP '+x.status+' em '+url+' - '+(x.responseText||''));
  }
  function xhrAsync(method,url,body,onDone){
    try{
      const x=new XMLHttpRequest();
      x.open(method,url,true);
      if(body!==undefined) x.setRequestHeader('Content-Type','text/plain; charset=utf-8');
      x.onreadystatechange=function(){
        if(x.readyState!==4) return;
        const ok=x.status>=200&&x.status<300;
        if(!ok) console.error('MES LION: falha ao persistir.',x.status,x.responseText);
        if(onDone) onDone(ok);
      };
      x.send(body===undefined?null:body);
    }catch(e){
      console.error('MES LION: falha assíncrona de persistência.',e);
      if(onDone) onDone(false);
    }
  }
  function scheduleDataSave(v){
    pendingData=String(v);
    if(dataTimer) clearTimeout(dataTimer);
    dataTimer=setTimeout(sendPendingData,450);
  }
  function sendPendingData(){
    dataTimer=null;
    if(inflight||pendingData===null) return;
    const body=pendingData;
    pendingData=null;
    inflight=true;
    xhrAsync('PUT','/api/storage/MES_LION_DATA',body,function(ok){
      inflight=false;
      if(!ok && pendingData===null) pendingData=body;
      if(pendingData!==null){
        if(retryTimer) clearTimeout(retryTimer);
        retryTimer=setTimeout(sendPendingData,ok?80:1200);
      }
    });
  }
  try{
    const raw=xhrSync('GET','/api/bootstrap');
    const boot=raw?JSON.parse(raw):{};
    mem=boot.appStorage||{};
    __MES_BOOT_DATA=boot.data||null;
    authenticated=true;
  }catch(e){
    // Antes do login, HTTP 401 é esperado e não representa falha do banco.
    if(String(e.message||e).includes('HTTP 401')){
      mem={};
    }else{
      console.error('MES LION: bootstrap indisponível.',e);
      const msg='Não foi possível acessar o servidor do MES LION. Abra o sistema pelo arquivo INICIAR_MES.bat.\n\n'+e.message;
      setTimeout(()=>alert(msg),100);
      mem={};
    }
  }
  return {
    getItem:function(k){
      if(k==='MES_LION_DATA'){
        if(pendingData!==null) return pendingData;
        return __MES_BOOT_DATA ? JSON.stringify(__MES_BOOT_DATA) : null;
      }
      return Object.prototype.hasOwnProperty.call(mem,k)?String(mem[k]):null;
    },
    setItem:function(k,v){
      if(k==='MES_LION_DATA'){
        if(!authenticated) return;
        scheduleDataSave(v);
        return;
      }
      mem[k]=String(v);
      xhrAsync('PUT','/api/storage/'+encodeURIComponent(k),String(v));
    },
    removeItem:function(k){
      if(k==='MES_LION_DATA'){
        __MES_BOOT_DATA=null; pendingData=null;
      }else delete mem[k];
      xhrAsync('DELETE','/api/storage/'+encodeURIComponent(k));
    },
    clear:function(){mem={};__MES_BOOT_DATA=null;pendingData=null;xhrAsync('DELETE','/api/storage');},
    flush:function(){
      if(dataTimer){clearTimeout(dataTimer);dataTimer=null;}
      const body=pendingData!==null ? pendingData : (typeof data!=='undefined'?JSON.stringify(data):null);
      pendingData=null;
      if(body!==null) xhrSync('PUT','/api/storage/MES_LION_DATA',body);
      return true;
    },
    pending:function(){return pendingData!==null||inflight;},
    setAuthenticated:function(v){authenticated=!!v;}
  };
})();
const initialData = window.MES_DATA || {};
const APP_VERSION = 'v1.0.1';
let data;
if(__MES_BOOT_DATA){
  data=__MES_BOOT_DATA;
}else{
  data=JSON.parse(JSON.stringify(initialData));
  localStorage.setItem('MES_LION_DATA',JSON.stringify(data));
}
