const modules = [['dashboard','Dashboard'],['materiais','Materiais'],['empresas','Empresas'],['entradas','Entrada de Materiais'],['estrutura','Estrutura do Produto'],['regras_produto','Regras Produto x Material'],['recursos','Recursos / Custos'],['cad_recursos','Cadastro de Recursos'],['processos','Processos'],['formulacoes','Formulações'],['roteiro','Roteiro'],['op','Ordens de Produção'],['op_etapas','OP - Etapas'],['op_materiais','OP - Materiais'],['regras_op','Regras de OP'],['producao','Apontamento Produção'],['perdas','Perdas'],['projetos','Projetos'],['simulacoes','Simulações'],['custos','Custos Industriais'],['sustentabilidade','Sustentabilidade / ACV'],['bp','Battery Passport']];
