function calcCustoSelecionado(){let cod=$('c_op').value;if(!cod){alert('Selecione uma OP.');return;}let r=calcCustoOP(cod,true);$('c_result').innerHTML=`<div class="cards"><div class="card"><b>Custo total</b><div class="metric">${money(r.CustoTotal)}</div></div><div class="card"><b>Materiais</b><div class="metric">${money(r.CustoMateriais)}</div></div><div class="card"><b>Energia</b><div class="metric">${money(r.CustoEnergia)}</div></div><div class="card"><b>Mão de obra</b><div class="metric">${money(r.CustoMOD)}</div></div><div class="card"><b>Perdas</b><div class="metric">${money(r.CustoPerdas)}</div></div></div><div class="report">${kv(r)}</div>`;}
function sustentabilidadeModule(){
  $('title').textContent='Sustentabilidade / ICV / ACV'; $('subtitle').textContent='Inventário e indicadores ambientais por OP, com fatores editáveis e integração ao Battery Passport.';
  $('content').innerHTML=`<div class="toolbar"><select id="s_op">${opOptionsHtml()}</select><button onclick="calcSustSelecionado()">Calcular sustentabilidade da OP</button><button onclick="genericModule('sust_fatores','Fatores ambientais')">Fatores ambientais</button><button onclick="genericModule('sust_mapeamento','Mapeamento Material x Fator')">Mapeamento</button></div><div id="s_result"></div><h3>Histórico de cálculos ambientais</h3><div>${table('sust_op')}</div>`;
}
function calcSustSelecionado(){let cod=$('s_op').value;if(!cod){alert('Selecione uma OP.');return;}let r=calcSustOP(cod,true);$('s_result').innerHTML=`<div class="cards"><div class="card"><b>CO₂eq total</b><div class="metric">${fmt(num(r.CO2eqTotal),4)}</div><span>kg CO₂eq</span></div><div class="card"><b>Energia</b><div class="metric">${fmt(num(r.EnergiaKWh),4)}</div><span>kWh</span></div><div class="card"><b>Massa produto</b><div class="metric">${fmt(num(r.MassaProduto),4)}</div></div><div class="card"><b>Perdas</b><div class="metric">${fmt(num(r.MassaPerdas),4)}</div></div></div><div class="report"><h3>Indicadores ACV/ICV</h3>${kv(r)}<p class="muted">Categorias como água, recursos minerais, acidificação, eutrofização, material particulado, ozônio fotoquímico, toxicidade humana e ecotoxicidade ficam disponíveis para preenchimento por fatores específicos.</p></div>`;}

function bpModule(){ $('title').textContent='Battery Passport'; $('subtitle').textContent='Módulo focado em rastreabilidade, OP, materiais, custos, emissões, imagens de qualificação, PDF, Excel e dashboard com QR para cliente.'; $('content').innerHTML=`<div class="toolbar"><button onclick="openBPForm(-1)">+ Novo Battery Passport</button><select id="bp_sel" onchange="showBP()"></select><button onclick="reportBP()">PDF BP selecionado</button><button class="secondary" onclick="reportBPData()">Relatório geral BP</button><button class="secondary" onclick="openBPDashboard()">Dashboard cliente</button><button class="secondary" onclick="exportBPDashboardHTML()">Exportar dashboard HTML</button><button class="secondary" onclick="copyBPLink()">Copiar link/QR</button><button class="secondary" onclick="exportSelectedExcel('bp','Battery Passport')">Exportar Excel selecionados</button><input id="q" placeholder="Pesquisar..." oninput="filterGeneric('bp')"></div><div id="crudBox"></div><div id="bpDet"></div><h3>Banco BP importado</h3><div id="tbl">${table('bp')}</div>`; fillSelect('bp_sel',data.bp,'BatteryPassportID','CodProduto'); showBP()}
function showBP(){let id=$('bp_sel')?.value||val(data.bp[0]||{},['BatteryPassportID']);if($('bp_sel'))$('bp_sel').value=id;let bp=(data.bp||[]).find(b=>b.BatteryPassportID==id)||{};let op=opPorCodigo(bp.CodOrdemProducao);let prod=produtoPorCodigo(bp.CodProduto)||produtoPorCodigo(op.CodigoProduto);let filhos=(data.estrutura||[]).filter(p=>p['Código Pai']==bp.CodProduto);let custo=bpCustoMateriais(bp);let emiss=bpEmissionValue(bp);let url=bpUrl(bp);$('bpDet').innerHTML=`<div class="report"><div class="report-head"><img src="${new URL('assets/logo-mes.jpg', location.href).href}"><div><h2>Battery Passport ${htmlEscape(id)}</h2><p><span class="${bpStatusClass(bp.StatusPassaporte)}">${htmlEscape(bp.StatusPassaporte||'')}</span> ${htmlEscape(bp.CodProduto||'')} • ${htmlEscape(prod['Descrição']||op.Produto||'')}</p></div></div><div class="kpi-row"><div class="kpi"><b>Produto</b><span>${htmlEscape(bp.CodProduto||'')}</span></div><div class="kpi"><b>OP rastreada</b><span>${htmlEscape(bp.CodOrdemProducao||'-')}</span></div><div class="kpi"><b>Custo mat.</b><span>${money(custo)}</span></div><div class="kpi"><b>CO₂eq</b><span>${emiss?emiss.toLocaleString('pt-BR'):'-'}</span></div></div><div class="two"><div>${kvHTML({...bp,DashboardCliente:url},['BatteryPassportID','BatteryPassportGUID','CodOrdemProducao','CodProduto','IDLote','ClienteNomeSnapshot','StatusPassaporte','DashboardCliente','DataMatrixHash'])}</div>${qrCardHTML(bp)}</div><h3 class="section-title">Imagens de qualificação</h3><div class="bp-img-grid">${imageBlock('Imagem da bateria',bp.ImagemBateria)}${imageBlock('Teste de ciclos',bp.ImagemTesteCiclos)}${imageBlock('Impedância',bp.ImagemImpedancia||bp.Tec_ResistenciaInterna_ImagemPath)}${imageBlock('Aging',bp.ImagemAging)}</div><h3 class="section-title">Dados técnicos do produto</h3>${kv(prod)}<h3 class="section-title">PIs/estrutura vinculada</h3>${miniTable(filhos)}</div>`}
function bpDashboardBody(bp){let prod=produtoPorCodigo(bp.CodProduto);let op=opPorCodigo(bp.CodOrdemProducao);let mats=bpMaterialRows(bp);let custo=bpCustoMateriais(bp);let emiss=bpEmissionValue(bp);let url=bpUrl(bp);let filhos=(data.estrutura||[]).filter(p=>p['Código Pai']==bp.CodProduto);return `<div class="dash-public"><div class="kpis"><div class="kpi"><b>Passaporte</b><span>${htmlEscape(bp.BatteryPassportID||'')}</span></div><div class="kpi"><b>Status</b><span>${htmlEscape(bp.StatusPassaporte||'')}</span></div><div class="kpi"><b>Custo rastreado</b><span>${money(custo)}</span></div><div class="kpi"><b>CO₂eq informado</b><span>${emiss?emiss.toLocaleString('pt-BR'):'-'}</span></div></div><div class="two"><div><h2>Identificação da bateria</h2>${kvHTML({...bp,DescricaoProduto:prod['Descrição']||op.Produto||''},['BatteryPassportID','BatteryPassportGUID','CodOrdemProducao','CodProduto','DescricaoProduto','IDLote','ClienteNomeSnapshot','FornecedorNomeSnapshot','StatusPassaporte','VersaoPassaporte'])}</div>${qrCardHTML(bp,'Compartilhamento')}</div><h2>Qualificação da bateria</h2><div class="bp-img-grid">${imageBlock('Imagem da bateria',bp.ImagemBateria)}${imageBlock('Teste de ciclos',bp.ImagemTesteCiclos)}${imageBlock('Impedância',bp.ImagemImpedancia||bp.Tec_ResistenciaInterna_ImagemPath)}${imageBlock('Aging',bp.ImagemAging)}</div><h2>Dados técnicos e performance</h2>${kvHTML({...prod,...bp},['Célula','Composição','Modelo','Capacidade Final (Ah)','Tensão Nominal (V)','Energia (Wh)','Tec_VidaUtil_Texto','Tec_ResistenciaInterna_Texto','Tec_RoundTripEfficiency_Texto','Tec_FaixaTemperatura_Texto'])}<h2>Rastreabilidade de materiais e custos</h2>${tableHTML(mats,['CodigoMaterial','MaterialEntrada','QtdPlanejada','UM','CustoUnitario','CustoEstimado'])}<h2>Estrutura PA → PI</h2>${tableHTML(filhos,['Código','Descrição','Tipo PI','Código Pai','Composição','Modelo'])}<h2>Sustentabilidade e conformidade</h2>${kvHTML(bp,['Sust_CarbonFootprint_Texto','Sust_DueDiligence_Texto','Sust_ConteudoReciclado_Texto','Sust_ConteudoRenovavel_Texto','Comp_DeclaracaoUE_Texto','Eng_Seguranca_Texto'])}</div>`}
