function criarOPFromRoteiroFiltradoV29(r,qtd,codOP,tipoOP,opBase,codigoPIFiltro){
  let produto=data.estrutura.find(x=>x['Código']==(codigoPIFiltro||r.CodigoProduto)) || {};
  let o={CodOP:codOP,CodRoteiro:r.CodRoteiro,CodigoProduto:r.CodigoProduto||produto['Código Pai']||produto['Código'],CodigoPI:codigoPIFiltro||'',Produto:produto['Código']||r.CodigoProduto,Versao:r.Versao,IdCelula:r.IdCelula||produto['Célula']||'',QtdPlanejada:qtd,QtdProduzida:'',Status:'Planejada',DataCriacao:new Date().toLocaleString('pt-BR'),Usuario:'admin',OP_Pai:tipoOP==='PI'?opBase:'',OP_Base:opBase,Observacoes:'Gerada automaticamente a partir de roteiro PA validado.',UM:'un',DataOP:new Date().toLocaleDateString('pt-BR'),TipoOP:tipoOP,OrigemGeracao:'WEB',DescricaoProduto:produto['Descrição']||r.DescricaoRoteiro||'',RoteiroValidado:'Sim',DataValidacaoRoteiro:r.DataValidacao||''};
  data.op.unshift(o);
  const etapaRows=(data.roteiro_etapas||[]).filter(e=>e.CodRoteiro==r.CodRoteiro && (!codigoPIFiltro || e.CodigoPI===codigoPIFiltro));
  const materialRows=(data.roteiro_materiais||[]).filter(m=>m.CodRoteiro==r.CodRoteiro && (!codigoPIFiltro || m.CodigoPI===codigoPIFiltro || !m.CodigoPI));
  etapaRows.forEach(e=>data.op_etapas.push({CodOP:codOP,Ordem:e.Ordem,Processo:e.Processo,CodEquipamento:e.CodEquipamento,TempoPlanejado:e.TempoOperacaoMin||e['TempoOperação (min)'],PessoasPlanejado:e.NPessoas,TempoReal:'',Inicio:'',Fim:'',Status:'PENDENTE',Obs:e.Obs||'',CodRoteiro:r.CodRoteiro,IdProcesso:e.IdProcesso,TempoOperacaoMin:e.TempoOperacaoMin,NPessoas:e.NPessoas,CodigoPI:e.CodigoPI||''}));
  materialRows.forEach(m=>data.op_materiais.push(prepararOPMaterialV26(m,codOP,qtd)));
  return o;
}
function gerarTodasOPsDoRoteiroValidadoV29(r,qtd){
  const base=baseOPCode();
  const criadas=[];
  criadas.push(criarOPFromRoteiroFiltradoV29(r,qtd,base+'-PA','PA',base,''));
  const pis=piListV25(r.CodigoProduto||'');
  let seq=1;
  pis.forEach(pi=>{
    const temEtapa=(data.roteiro_etapas||[]).some(e=>e.CodRoteiro===r.CodRoteiro && e.CodigoPI===pi['Código']);
    const temMat=(data.roteiro_materiais||[]).some(m=>m.CodRoteiro===r.CodRoteiro && m.CodigoPI===pi['Código']);
    if(temEtapa || temMat) criadas.push(criarOPFromRoteiroFiltradoV29(r,qtd,base+'-'+pad(seq++,2),'PI',base,pi['Código']));
  });
  return criadas;
}
