/* =========================================================
   PATCH V38.6 — validação por equipamento, UM do PA/PI e cópia
   ========================================================= */
function atualizarUMProdutoV386(){
  const cod=$('v382_prod')?.value||'';
  const box=$('v382_umprod');
  if(box) box.textContent=prodUMV382(cod)||'UM não definida';
}

function roteiroValidationV29(r){
  const cod=r&&r.CodRoteiro||'';
  const etapas=(data.roteiro_etapas||[]).filter(e=>e.CodRoteiro===cod);
  const recursos=(data.roteiro_recursos||[]).filter(x=>x.CodRoteiro===cod);
  const mats=(data.roteiro_materiais||[]).filter(m=>m.CodRoteiro===cod);
  const erros=[], avisos=[];
  if(!r||!r.CodRoteiro) erros.push('Nenhum roteiro selecionado.');
  if(!r?.CodigoProduto) erros.push('Roteiro sem PA/produto vinculado.');
  if(!etapas.length) erros.push('Inclua pelo menos uma operação de processo.');
  etapas.forEach(e=>{
    const ordem=String(e.Ordem||'');
    const recs=recursos.filter(x=>String(x.OrdemEtapa||x.Ordem)===ordem);
    if(!e.Processo) erros.push(`Operação ${ordem||'?'} sem processo.`);
    if(!e.ProdutoGerado&&!e.CodigoProduto&&!e.CodigoPI) erros.push(`Operação ${ordem||'?'} sem PA/PI gerado.`);
    if(num(e.QtdPlanejadaProduto)<=0) erros.push(`Operação ${ordem||'?'} com quantidade planejada do produto zerada.`);
    if(!e.UMProduto) avisos.push(`Operação ${ordem||'?'} sem unidade de medida definida para o PA/PI.`);
    if(!recs.length) erros.push(`Operação ${ordem||'?'} sem equipamento adicionado.`);
    recs.forEach(rec=>{
      const nome=rec.Equipamento||rec.CodEquipamento||'?';
      if(!rec.CodEquipamento&&!rec.Equipamento) erros.push(`Operação ${ordem||'?'} possui equipamento sem identificação.`);
      if(num(rec.TempoOperacaoMin)<=0) erros.push(`Equipamento ${nome} da operação ${ordem||'?'} sem tempo maior que zero.`);
      if(num(rec.NPessoas)<=0) erros.push(`Equipamento ${nome} da operação ${ordem||'?'} sem número de pessoas maior que zero.`);
      const rm=mats.filter(m=>m.IdRecursoRoteiro===rec.IdRecursoRoteiro);
      if(!rm.length) erros.push(`Equipamento ${nome} da operação ${ordem||'?'} sem matéria-prima vinculada.`);
    });
  });
  mats.forEach(m=>{
    const nome=m.CodigoMaterial||m.DescricaoMaterial||'?';
    if(!m.IdRecursoRoteiro) erros.push(`Material ${nome} não está vinculado a um equipamento.`);
    if(!recursos.some(x=>x.IdRecursoRoteiro===m.IdRecursoRoteiro)) erros.push(`Material ${nome} está vinculado a um equipamento inexistente.`);
    if(!m.CodigoMaterial) erros.push('Existe material sem código informado.');
    if(num(m.QtdBase||m.QtdPlanejada)<=0) erros.push(`Material ${nome} está com quantidade planejada zerada.`);
    if(!m.UM&&!m.UMConsumo) erros.push(`Material ${nome} está sem unidade de medida.`);
    m.UMConsumo=m.UMConsumo||m.UM||'';
    const c=recalcularMaterialRoteiroV26(m);
    if(!c.ok) erros.push(`Material ${nome}: ${c.msg||'unidade/custo incompatível'}.`);
  });
  const validado=String(r?.StatusRoteiro||'').toUpperCase()==='VALIDADO';
  const assinaturaOK=String(r?.AssinaturaValidacao||'')===assinaturaRoteiroV29(r);
  return {ok:erros.length===0,erros,avisos,validado,assinaturaOK,pronto:erros.length===0&&validado&&assinaturaOK};
}

function assinaturaRoteiroV29(r){
  const cod=r&&r.CodRoteiro||'';
  const etapas=(data.roteiro_etapas||[]).filter(e=>e.CodRoteiro===cod).map(e=>[e.Ordem,e.ProdutoGerado||e.CodigoProduto||e.CodigoPI,e.UMProduto,e.QtdPlanejadaProduto,e.Processo,e.IdProcesso]).sort();
  const recursos=(data.roteiro_recursos||[]).filter(x=>x.CodRoteiro===cod).map(x=>[x.IdRecursoRoteiro,x.OrdemEtapa,x.CodEquipamento,x.Equipamento,x.TempoOperacaoMin,x.NPessoas]).sort();
  const mats=(data.roteiro_materiais||[]).filter(m=>m.CodRoteiro===cod).map(m=>[m.IdRecursoRoteiro,m.OrdemEtapa||m.Ordem,m.CodigoMaterial,m.Entrada||'',m.Lote||'',m.QtdBase||m.QtdPlanejada,m.UMConsumo||m.UM||'']).sort();
  return JSON.stringify({cod,prod:r?.CodigoProduto||'',versao:r?.Versao||'',escala:r?.EscalaProducao||r?.Escala||'',etapas,recursos,mats});
}

function reabrirRoteiroV2311(){
  const r=roteiroAtualV25(); if(!r||!r.CodRoteiro) return alert('Selecione um roteiro.');
  if(String(r.StatusRoteiro||'').toUpperCase()!=='VALIDADO') return alert('Este roteiro já está em edição/pendente.');
  r.StatusRoteiro='PENDENTE'; r.AssinaturaValidacao=''; r.ObservacaoValidacao='Reaberto para edição em '+nowBR();
  saveLocal(); alert('Roteiro reaberto para edição. Após qualquer ajuste, valide novamente antes de utilizá-lo no MRP ou gerar OP.'); renderDetalheRoteiroV25();
}
function validarSalvarRoteiroV29(){
  const r=roteiroAtualV382();
  if(!r.CodRoteiro) return alert('Selecione um roteiro.');
  salvarRoteiroV383(false);
  const v=roteiroValidationV29(r);
  if(!v.ok) return alert('O roteiro ainda possui pendências obrigatórias:\n\n- '+v.erros.join('\n- '));
  r.StatusRoteiro='VALIDADO';
  r.DataValidacao=typeof nowBR==='function'?nowBR():new Date().toLocaleString('pt-BR');
  r.UsuarioValidacao='admin';
  r.AssinaturaValidacao=assinaturaRoteiroV29(r);
  r.ObservacaoValidacao=(v.avisos||[]).join(' | ');
  saveLocal();
  alert('Roteiro validado e salvo. A geração de OP foi habilitada.');
  renderRoteiroArvoreV382();
}

function copiarRoteiroV386(){
  const origem=roteiroAtualV382();
  if(!origem?.CodRoteiro) return alert('Selecione o roteiro que será usado como base.');
  const sugerido=(origem.CodRoteiro||'ROT')+'_COPIA';
  const novoCod=String(prompt('Código do novo roteiro:',sugerido)||'').trim();
  if(!novoCod) return;
  if((data.roteiro||[]).some(x=>String(x.CodRoteiro).toLowerCase()===novoCod.toLowerCase())) return alert('Já existe um roteiro com esse código.');
  const novaVersao=String(prompt('Versão do novo roteiro:',origem.Versao||'1')||origem.Versao||'1').trim();
  const novaDescricao=String(prompt('Descrição do novo roteiro:',`Cópia de ${origem.CodRoteiro} — ${origem.DescricaoRoteiro||''}`)||'').trim();
  const novo={...JSON.parse(JSON.stringify(origem)),CodRoteiro:novoCod,Versao:novaVersao,DescricaoRoteiro:novaDescricao,StatusRoteiro:'Em edição',AssinaturaValidacao:'',HashValidacao:'',DataValidacao:'',UsuarioValidacao:'',ObservacaoValidacao:`Criado a partir do roteiro ${origem.CodRoteiro}`,RoteiroOrigem:origem.CodRoteiro,DataCriacao:new Date().toLocaleString('pt-BR'),DataUltimaAlteracao:new Date().toLocaleString('pt-BR')};
  data.roteiro=data.roteiro||[]; data.roteiro.push(novo);
  const idMap={};
  const etapas=(data.roteiro_etapas||[]).filter(e=>e.CodRoteiro===origem.CodRoteiro).map(e=>({...JSON.parse(JSON.stringify(e)),CodRoteiro:novoCod,Status:'PENDENTE'}));
  data.roteiro_etapas.push(...etapas);
  data.roteiro_recursos=data.roteiro_recursos||[];
  const recs=data.roteiro_recursos.filter(x=>x.CodRoteiro===origem.CodRoteiro).map(x=>{const old=x.IdRecursoRoteiro;const nid=idRecursoRoteiroV385();idMap[old]=nid;return {...JSON.parse(JSON.stringify(x)),CodRoteiro:novoCod,IdRecursoRoteiro:nid};});
  data.roteiro_recursos.push(...recs);
  data.roteiro_materiais=data.roteiro_materiais||[];
  const ms=data.roteiro_materiais.filter(m=>m.CodRoteiro===origem.CodRoteiro).map(m=>({...JSON.parse(JSON.stringify(m)),CodRoteiro:novoCod,IdRecursoRoteiro:idMap[m.IdRecursoRoteiro]||''}));
  data.roteiro_materiais.push(...ms);
  saveLocal();
  roteiro();
  if($('v382_rot')) $('v382_rot').value=novoCod;
  renderRoteiroArvoreV382();
  alert(`Novo roteiro ${novoCod} criado a partir de ${origem.CodRoteiro}. Todas as informações podem ser editadas sem alterar o histórico original.`);
}

/* =========================================================
   MES LION V38.7 — ROTEIRO SEM REGRA DE VALIDAÇÃO
   - O roteiro apenas é salvo.
   - Qualquer roteiro salvo pode gerar OP.
   - Não há assinatura, validação ou bloqueio por pendências.
   ========================================================= */
const APP_PATCH_V387 = 'v38.7-roteiro-somente-salvar';
try{ localStorage.setItem('MES_LION_VERSION_PATCH', APP_PATCH_V387); }catch(e){}

function roteiroEstaSalvoV387(r){
  if(!r || !r.CodRoteiro) return false;
  const status=String(r.StatusRoteiro||'').trim().toUpperCase();
  if(['SALVO','VALIDADO','APROVADO'].includes(status)) return true;
  // Compatibilidade com roteiros históricos que não possuíam campo de status.
  return !status && !!(r.DataUltimaAlteracao||r.DataCriacao);
}

function salvarRoteiroV383(mostrarMensagem=true){
  const r=roteiroAtualV382();
  if(!r.CodRoteiro) return alert('Selecione um roteiro.');
  if($('v382_escala')) r.EscalaProducao=$('v382_escala').value||r.EscalaProducao||'';
  if($('v382_versao')) r.Versao=$('v382_versao').value||r.Versao||'';
  if($('v382_desc')) r.DescricaoRoteiro=$('v382_desc').value||r.DescricaoRoteiro||'';
  r.StatusRoteiro='SALVO';
  r.DataUltimaAlteracao=new Date().toLocaleString('pt-BR');
  r.AssinaturaValidacao='';
  r.HashValidacao='';
  r.DataValidacao='';
  r.UsuarioValidacao='';
  r.ObservacaoValidacao='';
  saveLocal();
  if(mostrarMensagem) alert('Roteiro salvo com sucesso. Ele já pode ser utilizado para gerar OP.');
  renderRoteiroArvoreV382();
}

