function tiposCelulaRoteiroV388(){
  return ['Prismática','Cilíndrica'];
}
function produtosEstruturaV388(){
  return (data.estrutura||[])
    .filter(p=>String(p['Código']||'').trim())
    .sort((a,b)=>String(a['Código']).localeCompare(String(b['Código']),'pt-BR'));
}
function novoRoteiroV388(idx=-1){
  const editing=idx>=0;
  const old=editing?(data.roteiro[idx]||{}):autoDefaults('roteiro');
  const produtos=produtosEstruturaV388();
  const codigoAtual=old.CodigoProduto||'';
  const prod=produtos.find(p=>p['Código']===codigoAtual)||{};
  const tipoAtual=old.Tipo||prod.Modelo||prod['Tipo de Célula']||'';
  const composicao=old.Composicao||old['Composição']||prod['Composição']||'';
  const produtoOpts='<option value="">Selecione um produto cadastrado na Estrutura...</option>'+produtos.map(p=>`<option value="${safeTextV382(p['Código'])}" ${p['Código']===codigoAtual?'selected':''}>${safeTextV382(p['Código'])} — ${safeTextV382(p['Descrição']||'')}</option>`).join('');
  const tipoOpts='<option value="">Selecione...</option>'+tiposCelulaRoteiroV388().map(t=>`<option value="${t}" ${String(tipoAtual).toLowerCase()===t.toLowerCase()?'selected':''}>${t}</option>`).join('');
  $('crudBox').innerHTML=`<div class="form edit-form roteiro-cadastro-v388">
    <h3>${editing?'Editar':'Novo'} roteiro de produção</h3>
    <div class="form-grid">
      <label><span>Código do roteiro</span><input id="rt388_cod" value="${safeTextV382(old.CodRoteiro||'')}" readonly></label>
      <label><span>Código do produto</span><select id="rt388_prod" onchange="roteiroProdutoChangeV388()">${produtoOpts}</select></label>
      <label><span>Tipo</span><select id="rt388_tipo">${tipoOpts}</select></label>
      <label><span>Composição</span><input id="rt388_comp" value="${safeTextV382(composicao)}"></label>
      <label><span>Versão</span><input id="rt388_versao" value="${safeTextV382(old.Versao||'')}"></label>
      <label><span>Escala de produção</span><select id="rt388_escala"><option ${old.EscalaProducao==='Planta Piloto'?'selected':''}>Planta Piloto</option><option ${old.EscalaProducao==='Semi-industrial'?'selected':''}>Semi-industrial</option><option ${old.EscalaProducao==='Industrial'?'selected':''}>Industrial</option></select></label>
      <label class="wide"><span>Descrição do roteiro</span><input id="rt388_desc" value="${safeTextV382(old.DescricaoRoteiro||prod['Descrição']||'')}"></label>
      <label><span>Ativo</span><select id="rt388_ativo"><option value="TRUE" ${String(old.Ativo||'TRUE').toUpperCase()!=='FALSE'?'selected':''}>Sim</option><option value="FALSE" ${String(old.Ativo).toUpperCase()==='FALSE'?'selected':''}>Não</option></select></label>
      <label><span>Data de criação</span><input id="rt388_data" value="${safeTextV382(old.DataCriacao||new Date().toLocaleDateString('pt-BR'))}" readonly></label>
      <label class="wide"><span>Observações</span><textarea id="rt388_obs">${safeTextV382(old.Obs||old.Observacoes||'')}</textarea></label>
    </div>
    <div class="form-actions"><button onclick="salvarRoteiroCadastroV388(${idx})">Salvar roteiro</button>${editing?`<button class="danger" onclick="deleteRecord('roteiro',${idx})">Excluir</button>`:''}<button class="secondary" onclick="$('crudBox').innerHTML=''">Cancelar</button></div>
    <p class="muted">O código do produto é carregado exclusivamente dos produtos cadastrados na tela Estrutura do Produto.</p>
  </div>`;
  roteiroProdutoChangeV388(true);
  $('crudBox').scrollIntoView({behavior:'smooth',block:'start'});
}
function roteiroProdutoChangeV388(preservar=false){
  const p=produtosEstruturaV388().find(x=>x['Código']===$('rt388_prod')?.value)||{};
  if(!p['Código']) return;
  if(!preservar || !$('rt388_desc').value) $('rt388_desc').value=p['Descrição']||'';
  if(!preservar || !$('rt388_comp').value) $('rt388_comp').value=p['Composição']||'';
  const modelo=String(p.Modelo||p['Tipo de Célula']||'').toLowerCase();
  if(modelo.includes('prism')) $('rt388_tipo').value='Prismática';
  else if(modelo.includes('cil')) $('rt388_tipo').value='Cilíndrica';
}
function salvarRoteiroCadastroV388(idx){
  const codProd=$('rt388_prod')?.value||'';
  if(!codProd) return alert('Selecione um código de produto cadastrado na Estrutura do Produto.');
  const old=idx>=0?(data.roteiro[idx]||{}):{};
  const obj={...old,
    CodRoteiro:$('rt388_cod').value,
    CodigoProduto:codProd,
    Tipo:$('rt388_tipo').value,
    Composicao:$('rt388_comp').value,
    Versao:$('rt388_versao').value,
    EscalaProducao:$('rt388_escala').value,
    DescricaoRoteiro:$('rt388_desc').value,
    Ativo:$('rt388_ativo').value,
    DataCriacao:$('rt388_data').value,
    Obs:$('rt388_obs').value,
    CodigoPI:''
  };
  if(idx>=0) data.roteiro[idx]=obj; else {data.roteiro=data.roteiro||[];data.roteiro.unshift(obj);}
  saveLocal();render('roteiro');
}

const newRecordBaseV388=newRecord;
newRecord=function(k){ if(k==='roteiro') return novoRoteiroV388(-1); return newRecordBaseV388(k); };
const editRecordBaseV388=editRecord;
editRecord=function(k,idx){ if(k==='roteiro') return novoRoteiroV388(idx); return editRecordBaseV388(k,idx); };

function opProductionPage(op, first=false){
  const cod=op.CodOP||'';
  const materiais=(data.op_materiais||[]).filter(x=>x.CodOP==cod);
  const etapas=(data.op_etapas||[]).filter(x=>x.CodOP==cod).sort((a,b)=>num(a.Ordem)-num(b.Ordem));
  const info=opProductInfo(op);
  const dataOP=op.DataOP||op.DataCriacao||new Date().toLocaleDateString('pt-BR');
  const roteiro=(data.roteiro||[]).find(r=>r.CodRoteiro===op.CodRoteiro)||{};
  const header=`<div class="op-card op-industrial-v388 ${first?'':'break'}">
    <div class="op-industrial-title"><div><small>MES LION • DOCUMENTO DE PRODUÇÃO</small><h2>ORDEM DE PRODUÇÃO</h2></div><div class="op-number-v388"><span>OP</span><b>${htmlEscape(cod)}</b></div></div>
    <table class="op-head"><tr><th>Produto</th><td colspan="3"><b>${htmlEscape(info.cod)}</b> — ${htmlEscape(info.desc)}</td></tr><tr><th>Roteiro</th><td>${htmlEscape(op.CodRoteiro||'')}</td><th>Versão</th><td>${htmlEscape(op.Versao||roteiro.Versao||'')}</td></tr><tr><th>Tipo</th><td>${htmlEscape(roteiro.Tipo||'')}</td><th>Composição</th><td>${htmlEscape(roteiro.Composicao||roteiro['Composição']||'')}</td></tr><tr><th>Quantidade planejada</th><td>${htmlEscape(op.QtdPlanejada||'')} ${htmlEscape(op.UM||'')}</td><th>Data</th><td>${htmlEscape(dataOP)}</td></tr></table>`;
  const usados=new Set();
  const blocos=etapas.map((e,i)=>{
    const mats=opMateriaisDaEtapaV38(materiais,e);mats.forEach(m=>usados.add(m));
    const recurso=e.Recurso||recursoNomeV32(e.CodEquipamento,e.Processo)||e.Equipamento||e.CodEquipamento||'';
    const rows=mats.map(materialRowOPV38).join('')||'<tr><td colspan="8">Nenhum material alocado nesta etapa.</td></tr>';
    return `<section class="industrial-step-v388"><div class="industrial-step-head"><span>${String(i+1).padStart(2,'0')}</span><div><small>ETAPA ${htmlEscape(e.Ordem||'')}</small><h3>${htmlEscape(e.Processo||'Processo não informado')}</h3></div></div><table class="resource-table-v388"><tr><th>Recurso / equipamento</th><td>${htmlEscape(recurso)}</td><th>Código</th><td>${htmlEscape(e.CodEquipamento||'')}</td></tr><tr><th>Tempo planejado</th><td>${htmlEscape(e.TempoPlanejado||e.TempoOperacaoMin||'')} min</td><th>Pessoas</th><td>${htmlEscape(e.PessoasPlanejado||e.NPessoas||'')}</td></tr></table><h4>Materiais alocados nesta etapa</h4><table><thead><tr><th>Código</th><th>Material / PI</th><th>Qtd. planejada</th><th>UM</th><th>Lote</th><th>Consumo real</th><th>Perda</th><th>Observações</th></tr></thead><tbody>${rows}</tbody></table><div class="annotation-grid small-annotations">${blankBox('Início')}${blankBox('Fim')}${blankBox('Operador')}${blankBox('Quantidade produzida')}${blankBox('Quantidade rejeitada')}${blankBox('Conferência')}</div></section>`;
  }).join('')||'<section class="industrial-step-v388"><p>Não existem etapas ou recursos vinculados a esta OP.</p></section>';
  const soltos=materiais.filter(m=>!usados.has(m));
  const extras=soltos.length?`<section class="industrial-step-v388"><h3>Materiais sem etapa definida</h3><table><thead><tr><th>Código</th><th>Material / PI</th><th>Qtd. planejada</th><th>UM</th><th>Lote</th><th>Consumo real</th><th>Perda</th><th>Observações</th></tr></thead><tbody>${soltos.map(materialRowOPV38).join('')}</tbody></table></section>`:'';
  return `${header}${blocos}${extras}<div class="op-footer-v388"><div class="obs-big"><b>Observações gerais da produção:</b></div><div class="sign"><div class="line">Produção</div><div class="line">Qualidade</div><div class="line">PCP / Engenharia</div></div></div></div>`;
}


