const MES_LION_LOGO_DATA_URI = 'data:image/jpeg;base64,';

function bpPublicMaterialRows(bp){
  return bpMaterialRows(bp).map(m=>({
    CodigoMaterial:m.CodigoMaterial||'',
    Material:m.MaterialEntrada||m.DescricaoMaterial||'',
    Quantidade:m.QtdConsumida||m.QtdPlanejada||m.Qtd||'',
    UM:m.UM||'',
    Lote:m.Lote||m.CodigoLote||m.LoteConsumido||''
  }));
}
function bpPublicUrl(bp){
  return String(bp?.URLPassaporteWeb||'').trim();
}
function bpShareStatus(bp){
  const u=bpPublicUrl(bp);
  return u ? 'Link público cadastrado para consulta do relatório' : 'Cadastre o link público do PDF ou relatório publicado';
}
function qrCardHTML(bp,title='Acesso digital ao passaporte'){
  const url=bpPublicUrl(bp);
  if(!url) return `<div class="qr-card warn"><b>${htmlEscape(title)}</b><div class="img-empty">QR Code pendente</div><small>Publique o PDF ou relatório no OneDrive/SharePoint com permissão de visualização e cole o link público no cadastro do passaporte.</small></div>`;
  return `<div class="qr-card passport-qr"><b>${htmlEscape(title)}</b><img src="${qrUrlFor(url)}" alt="QR Code do passaporte"><small>Escaneie para consultar o relatório digital</small><small class="qr-url">${htmlEscape(url)}</small></div>`;
}

function openBPForm(idx=-1){
  if(!$('crudBox')) return;
  openBPFormBase(Number.isInteger(idx)?idx:-1);
  const url=$('bp_url');
  if(url){
    const label=url.closest('label');
    const span=label?.querySelector('span');
    if(span) span.textContent='Link público do relatório (PDF/OneDrive/SharePoint)';
    label?.classList.add('wide');
    if(label && !label.querySelector('.public-link-help')){
      label.insertAdjacentHTML('beforeend',`<small class="muted public-link-help">Cole aqui o link de visualização pública do arquivo. O QR Code será criado automaticamente após salvar. Use permissão somente para leitura.</small>`);
    }
  }
}

