function openBPDashboard(){
  if($('crudBox')&&$('bp_id')) return alert('Salve o passaporte antes de abrir o dashboard do cliente.');
  const id=$('bp_sel')?.value||val(data.bp[0]||{},['BatteryPassportID']);
  const bp=(data.bp||[]).find(b=>b.BatteryPassportID==id);
  if(!bp) return alert('Selecione um passaporte.');
  const w=window.open('','_blank');
  if(!w) return alert('Permita pop-ups para abrir o dashboard do cliente.');
  w.document.write(standaloneDashboardHTML(bp)); w.document.close();
}

function copyBPLink(){
  const id=$('bp_sel')?.value||val(data.bp[0]||{},['BatteryPassportID']);
  const bp=(data.bp||[]).find(b=>b.BatteryPassportID==id);
  if(!bp) return alert('Selecione um passaporte.');
  const u=bpPublicUrl(bp);
  if(!u) return alert('Este passaporte ainda não possui link público. Publique o PDF/relatório no OneDrive ou SharePoint, copie o link de visualização e cadastre-o no campo “Link público do relatório”.');
  if(navigator.clipboard?.writeText) navigator.clipboard.writeText(u).then(()=>alert('Link público copiado.')).catch(()=>prompt('Copie o link:',u));
  else prompt('Copie o link:',u);
}

/* ============================================================
   MES LION V38.19 — Auditoria Excel, exclusão em massa e dados de teste
   ============================================================ */
function downloadAuditExcelV3819(filename,title,sections){
  const sectionHtml=(sections||[]).map(s=>{
    const rows=s.rows||[]; const cols=s.cols||Object.keys(rows[0]||{});
    return `<h2>${excelEscape(s.title||'Planilha')}</h2>${s.note?`<p>${excelEscape(s.note)}</p>`:''}<table border="1" cellspacing="0" cellpadding="4"><thead><tr>${cols.map(c=>`<th>${excelEscape(c)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${cols.map(c=>`<td>${excelEscape(r[c]??'')}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${Math.max(cols.length,1)}">Sem registros</td></tr>`}</tbody></table><br>`;
  }).join('');
  const html=`<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:Arial;font-size:11px}h1{color:#004b87}h2{color:#004b87;background:#eaf2f7;padding:6px}th{background:#d9e8f2;font-weight:bold}td,th{vertical-align:top}.formula{mso-number-format:"\\@"}</style></head><body><h1>${excelEscape(title)}</h1><p>Arquivo de auditoria gerado em ${excelEscape(new Date().toLocaleString('pt-BR'))}. Os campos “Regra/Fórmula” documentam exatamente a lógica executada pelo MES.</p>${sectionHtml}</body></html>`;
  const blob=new Blob(['\ufeff',html],{type:'application/vnd.ms-excel;charset=utf-8'}); const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename.replace(/[^a-z0-9_.-]+/gi,'_');document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500);
}
function auditCostFamilyV3819(codMae){
  const fam=typeof opFamilyV33==='function'?opFamilyV33(codMae):[(opPorCodigo(codMae)||{})].filter(Boolean);
  const energiaFactor=$('c_energy_factor')?.value||''; const modFactor=$('c_mod_factor')?.value||'';
  const fEnergia=typeof selectedCustoFactorV33==='function'?selectedCustoFactorV33(energiaFactor,'Energia'):null;
  const fMOD=typeof selectedCustoFactorV33==='function'?selectedCustoFactorV33(modFactor,'Mão de obra'):null;
  const taxaEnergia=fEnergia?num(fEnergia.CustoUnitario):(num(((data.custos_fatores||[]).find(f=>f.Tipo==='Energia')||{}).CustoUnitario)||0.82);
  const materiais=[],etapas=[],perdas=[]; let matTotal=0,energiaTotal=0,modTotal=0,perdasTotal=0;
  fam.forEach(op=>{
    (data.op_materiais||[]).filter(m=>m.CodOP===op.CodOP).forEach(m=>{
      const qtd=num(m.QtdConsumida)||num(m.QtdReal)||num(m.Qtd)||num(m.QtdPlanejada)||num(m.QtdBase);
      const unit=num(m.CustoUnitarioProjetado)||materialUnitCost(m.CodigoMaterial);
      const total=num(m.CustoTotal)||qtd*unit; matTotal+=total;
      materiais.push({OP:op.CodOP,CodigoMaterial:m.CodigoMaterial||'',Material:m.DescricaoMaterial||materialPorCodigo(m.CodigoMaterial).DescricaoMateriais||'',Quantidade:qtd,UM:m.UM||'',CustoUnitario:unit,'Regra/Fórmula':'Custo material = quantidade considerada × custo unitário projetado/médio','Resultado':total,'Origem quantidade':num(m.QtdConsumida)?'QtdConsumida':num(m.QtdReal)?'QtdReal':num(m.Qtd)?'Qtd':num(m.QtdPlanejada)?'QtdPlanejada':'QtdBase','Origem custo':num(m.CustoTotal)?'CustoTotal congelado':num(m.CustoUnitarioProjetado)?'CustoUnitarioProjetado':'Média das entradas'});
    });
    (data.op_etapas||[]).filter(e=>e.CodOP===op.CodOP).forEach(e=>{
      const r=(data.recursos||[]).find(x=>String(x.CodEquipamento)===String(e.CodEquipamento))||{};
      const min=num(e.TempoReal)||num(e.TempoOperacaoMin)||num(e.TempoPlanejado)||num(r['TempoOperação (min)']);
      const pessoas=num(e.NPessoas)||num(e.PessoasPlanejado)||num(r.NPessoas)||1;
      const potW=num(e.PotenciaW)||num(r['PotenciaEquipamento (W)']);
      const kwh=(potW/1000)*(min/60); const cEnergia=kwh*taxaEnergia;
      const taxaMOD=fMOD?num(fMOD.CustoUnitario):(num(r['TaxaMOD (R$/h)'])||num(((data.custos_fatores||[]).find(f=>f.Tipo==='Mão de obra')||{}).CustoUnitario));
      const cMOD=(min/60)*pessoas*taxaMOD; energiaTotal+=cEnergia;modTotal+=cMOD;
      etapas.push({OP:op.CodOP,Ordem:e.Ordem||'',Processo:e.Processo||'',Equipamento:e.CodEquipamento||e.Equipamento||'',TempoMin:min,Pessoas:pessoas,PotenciaW:potW,EnergiaKWh:kwh,TaxaEnergia_R_kWh:taxaEnergia,CustoEnergia:cEnergia,TaxaMOD_R_h:taxaMOD,CustoMOD:cMOD,'Fórmula energia':'(Potência W ÷ 1000) × (tempo min ÷ 60) × taxa R$/kWh','Fórmula MOD':'(tempo min ÷ 60) × nº pessoas × taxa R$/h'});
    });
    (data.perdas||[]).filter(p=>p.CodOP===op.CodOP).forEach(p=>{
      const qtd=num(p.QuantidadePerdida); const unit=materialUnitCost(p.CodigoMaterial||p.ItemPerdaCodigo); const total=qtd*unit; perdasTotal+=total;
      perdas.push({OP:op.CodOP,Tipo:p.PerdaAlvoTipo||'',Item:p.CodigoMaterial||p.ItemPerdaCodigo||'',QuantidadePerdida:qtd,CustoUnitario:unit,'Regra/Fórmula':'Custo da perda = quantidade perdida × custo unitário médio do material',Resultado:total});
    });
  });
  const total=matTotal+energiaTotal+modTotal+perdasTotal;
  const resumo=[{OPMae:codMae,OPsIncluidas:fam.map(o=>o.CodOP).join('; '),CustoMateriais:matTotal,CustoEnergia:energiaTotal,CustoMOD:modTotal,CustoPerdas:perdasTotal,CustoTotal:total,'Regra total':'Materiais + Energia + MOD + Perdas','Taxa energia aplicada':taxaEnergia,'Fonte taxa energia':fEnergia?(fEnergia.Item||'Fator selecionado'):'Fator padrão/cadastrado','Fonte taxa MOD':fMOD?(fMOD.Item||'Fator selecionado'):'Taxa do recurso ou padrão'}];
  const regras=[
    {'Ordem':1,'Campo calculado':'Quantidade de material','Regra/Fórmula':'Prioridade: QtdConsumida → QtdReal → Qtd → QtdPlanejada → QtdBase'},
    {'Ordem':2,'Campo calculado':'Custo unitário do material','Regra/Fórmula':'Prioridade: CustoUnitarioProjetado → média ponderada das entradas do material'},
    {'Ordem':3,'Campo calculado':'Custo de material','Regra/Fórmula':'Quantidade considerada × custo unitário; se CustoTotal estiver congelado, ele prevalece'},
    {'Ordem':4,'Campo calculado':'Energia (kWh)','Regra/Fórmula':'(Potência W ÷ 1000) × (tempo min ÷ 60)'},
    {'Ordem':5,'Campo calculado':'Custo de energia','Regra/Fórmula':'Energia kWh × taxa de energia R$/kWh'},
    {'Ordem':6,'Campo calculado':'Custo de mão de obra','Regra/Fórmula':'(tempo min ÷ 60) × pessoas × taxa MOD R$/h'},
    {'Ordem':7,'Campo calculado':'Custo de perdas','Regra/Fórmula':'Quantidade perdida × custo unitário médio do material'},
    {'Ordem':8,'Campo calculado':'Custo total','Regra/Fórmula':'Materiais + Energia + Mão de obra + Perdas'}
  ];
  return {resumo,materiais,etapas,perdas,regras};
}
function exportCustosAuditaveisV3819(){
  const cod=$('c_op')?.value||''; if(!cod)return alert('Selecione uma OP mãe / PA para exportar.');
  const a=auditCostFamilyV3819(cod);
  downloadAuditExcelV3819(`auditoria_custos_${cod}.xls`,`Auditoria de custos — ${cod}`,[{title:'Resumo do cálculo',rows:a.resumo},{title:'Materiais e memória de cálculo',rows:a.materiais},{title:'Energia e mão de obra por etapa',rows:a.etapas},{title:'Perdas',rows:a.perdas},{title:'Regras de cálculo executadas',rows:a.regras}]);
}
function exportSimulacaoAuditavelV3819(){
  let sim=null;
  if($('sim_op')?.value){
    const op=opPorCodigo($('sim_op').value); if(!op)return alert('Selecione uma OP válida.');
    const base=custoBaseOPV3817(op); const qtd=num($('sim_qtd')?.value); const baseQtd=num(op.QtdPlanejada||op.QuantidadePlanejada)||1; const fator=qtd/baseQtd;
    sim={IdSimulacao:$('sim_id')?.value||'NÃO SALVA',CodOP:op.CodOP,QtdBaseOP:baseQtd,QtdSimulada:qtd,FatorEscala:fator,CustoMateriaisBase:base.materiais,CustoEnergiaBase:base.energia,CustoMODBase:base.mod,CustoOutrosBase:base.outros,CustoMateriaisSimulado:base.materiais*fator,CustoEnergiaSimulado:base.energia*fator,CustoMODSimulado:base.mod*fator,CustoOutrosSimulado:base.outros*fator,CustoTotalSimulado:(base.materiais+base.energia+base.mod+base.outros)*fator,CustoUnitario:qtd?((base.materiais+base.energia+base.mod+base.outros)*fator/qtd):0,TempoBaseMin:base.tempMin,TempoSimuladoMin:base.tempMin*fator};
  }else{
    const rows=rowsForReport('simulacoes'); if(!rows.length)return alert('Não há simulação selecionada ou cadastrada.'); sim=rows[0];
  }
  const regras=[
    {'Campo':'Fator de escala','Regra/Fórmula':'Quantidade simulada ÷ quantidade planejada da OP','Valor':num(sim.QtdSimulada||sim.QtdCelulas)/Math.max(num(sim.QtdBaseOP),1)},
    {'Campo':'Cada componente de custo','Regra/Fórmula':'Custo-base da OP × fator de escala','Valor':'Aplicado separadamente a materiais, energia, MOD e outros/perdas'},
    {'Campo':'Custo total simulado','Regra/Fórmula':'Materiais simulados + energia simulada + MOD simulada + outros simulados','Valor':sim.CustoTotalSimulado||sim.CustoTotal||''},
    {'Campo':'Custo unitário','Regra/Fórmula':'Custo total simulado ÷ quantidade simulada','Valor':sim.CustoUnitario||''},
    {'Campo':'Tempo simulado','Regra/Fórmula':'Tempo-base da OP × fator de escala','Valor':sim.TempoSimuladoMin||sim['temp min']||''}
  ];
  const op=opPorCodigo(sim.CodOP||sim.OPBase); const audit=op?auditCostFamilyV3819(op.OP_Base||op.OP_Pai||op.CodOP):null;
  const sections=[{title:'Parâmetros e resultados da simulação',rows:[sim]},{title:'Regras de simulação executadas',rows:regras}];
  if(audit){sections.push({title:'Base de materiais da OP',rows:audit.materiais},{title:'Base de energia e MOD da OP',rows:audit.etapas},{title:'Regras da base de custos',rows:audit.regras});}
  downloadAuditExcelV3819(`auditoria_simulacao_${sim.IdSimulacao||sim.CodOP||'OP'}.xls`,`Auditoria da simulação por OP`,sections);
}
