function excluirRoteirosSelecionadosV3819(){
  const checks=[...document.querySelectorAll('.row-roteiro:checked')]; if(!checks.length)return alert('Selecione pelo menos um roteiro na tabela inicial.');
  const cods=checks.map(c=>(data.roteiro||[])[Number(c.dataset.index)]?.CodRoteiro).filter(Boolean);
  if(!cods.length)return alert('Não foi possível identificar os roteiros selecionados.');
  const ops=(data.op||[]).filter(o=>cods.includes(o.CodRoteiro));
  const msg=`Excluir ${cods.length} roteiro(s)?\n\n${cods.join(', ')}\n\nSerão excluídas também etapas, equipamentos e materiais dos roteiros. ${ops.length?'Atenção: existem '+ops.length+' OP(s) históricas vinculadas; as OPs serão preservadas com seus snapshots.':''}`;
  if(!confirm(msg))return;
  data.roteiro=(data.roteiro||[]).filter(r=>!cods.includes(r.CodRoteiro));
  data.roteiro_etapas=(data.roteiro_etapas||[]).filter(r=>!cods.includes(r.CodRoteiro));
  data.roteiro_recursos=(data.roteiro_recursos||[]).filter(r=>!cods.includes(r.CodRoteiro));
  data.roteiro_materiais=(data.roteiro_materiais||[]).filter(r=>!cods.includes(r.CodRoteiro));
  saveLocal();alert(`${cods.length} roteiro(s) excluído(s). As OPs históricas foram preservadas.`);render('roteiro');
}
