  const mats=[['OP-TESTE-BP-001','MP0003',1.25],['OP-TESTE-BP-001','MP0007',0.0694],['OP-TESTE-BP-001','MP0009',0.0694],['OP-TESTE-BP-001','MP0006',0.98],['OP-TESTE-BP-002','MP0003',0.65],['OP-TESTE-BP-002','MP0007',0.0283],['OP-TESTE-BP-002','MP0009',0.0283],['OP-TESTE-BP-002','MP0005',0.49]];
  mats.forEach(([CodOP,CodigoMaterial,QtdPlanejada])=>{if(!data.op_materiais.some(m=>m.CodOP===CodOP&&m.CodigoMaterial===CodigoMaterial)){const m=materialPorCodigo(CodigoMaterial)||{};const unit=materialUnitCost(CodigoMaterial)||100;data.op_materiais.push({CodOP,CodigoMaterial,DescricaoMaterial:m.DescricaoMateriais||'',QtdPlanejada:String(QtdPlanejada),QtdConsumida:String(QtdPlanejada),UM:m.UM||'kg',CustoUnitarioProjetado:String(unit),CustoTotal:String(QtdPlanejada*unit),Lote:CodOP.endsWith('001')?'LOTE-TESTE-A':'LOTE-TESTE-B',Origem:'DADOS DE TESTE'})}});
  const stages=[['OP-TESTE-BP-001','10','Mistura','MISTURADOR-TESTE',120,2,2500],['OP-TESTE-BP-001','20','Montagem','MONTAGEM-TESTE',180,3,1800],['OP-TESTE-BP-001','30','Formação','FORMADOR-TESTE',480,1,3000],['OP-TESTE-BP-002','10','Mistura','MISTURADOR-TESTE',90,2,2500],['OP-TESTE-BP-002','20','Montagem','MONTAGEM-TESTE',120,2,1800],['OP-TESTE-BP-002','30','Formação','FORMADOR-TESTE',300,1,3000]];
  stages.forEach(([CodOP,Ordem,Processo,CodEquipamento,TempoPlanejado,NPessoas,PotenciaW])=>{if(!data.op_etapas.some(e=>e.CodOP===CodOP&&String(e.Ordem)===String(Ordem)))data.op_etapas.push({CodOP,Ordem,Processo,CodEquipamento,TempoPlanejado:String(TempoPlanejado),TempoReal:String(TempoPlanejado),NPessoas:String(NPessoas),PotenciaW:String(PotenciaW),Status:'CONCLUÍDA',Origem:'DADOS DE TESTE'})});
