function auditCostFamilyV3822(codMae){
  const fam=typeof opFamilyV33==='function'?opFamilyV33(codMae):[(opPorCodigo(codMae)||{})].filter(Boolean);
  const fEnergia=typeof selectedCustoFactorV33==='function'?selectedCustoFactorV33($('c_energy_factor')?.value||'','Energia'):null;
  const fMOD=typeof selectedCustoFactorV33==='function'?selectedCustoFactorV33($('c_mod_factor')?.value||'','Mão de obra'):null;
  const taxaEnergia=fEnergia?num(fEnergia.CustoUnitario):(num(((data.custos_fatores||[]).find(f=>f.Tipo==='Energia')||{}).CustoUnitario)||0.82);
  const taxaMODPadrao=fMOD?num(fMOD.CustoUnitario):(num(((data.custos_fatores||[]).find(f=>f.Tipo==='Mão de obra')||{}).CustoUnitario)||5);
  const materiais=[],etapas=[],perdas=[];let matTotal=0,energiaTotal=0,modTotal=0,perdasTotal=0;
  fam.forEach(op=>{
    const seen=new Set();
    (data.op_materiais||[]).filter(m=>m.CodOP===op.CodOP&&!String(m.TipoConsumo||'').toLowerCase().includes('pi intermedi')).forEach(m=>{
      const key=String(m.CodigoMaterial)+'|'+String(m.Ordem||'');if(seen.has(key))return;seen.add(key);
      const qtd=num(m.QtdConsumida)||num(m.QtdReal)||num(m.Qtd)||num(m.QtdPlanejada)||num(m.QtdBase);
      const media=custoMedioPonderadoMaterialV3822(m.CodigoMaterial),unit=media.valor,total=qtd*unit;matTotal+=total;
      materiais.push({OP:op.CodOP,Etapa:m.Ordem||'',CodigoMaterial:m.CodigoMaterial||'',Material:m.DescricaoMaterial||materialPorCodigo(m.CodigoMaterial).DescricaoMateriais||'',Quantidade:qtd,UM:m.UM||materialPorCodigo(m.CodigoMaterial).UM||'',FatorKg:fatorKgMaterialV3822(m.CodigoMaterial),CustoUnitario:unit,'Cálculo aberto':`${qtd} × ${unit} = ${total}`,Resultado:total,'Origem custo':media.origem,'Entradas consideradas':media.numeroEntradas});
    });
    const oes=(data.op_etapas||[]).filter(e=>e.CodOP===op.CodOP);
    oes.forEach(e=>{
      const recs=recursosEtapaOPV3822(op,e);(recs.length?recs:[{}]).forEach(rr=>{
        const cad=(data.recursos||[]).find(x=>String(x.CodEquipamento)===String(rr.CodEquipamento)&&(!rr.Processo||String(x.Processo)===String(rr.Processo)))||(data.recursos||[]).find(x=>String(x.CodEquipamento)===String(rr.CodEquipamento))||{};
        const min=num(e.TempoReal)||num(rr.TempoOperacaoMin)||num(e.TempoPlanejado)||num(e.TempoOperacaoMin)||num(cad['TempoOperação (min)']);
        const pessoas=num(rr.NPessoas)||num(e.NPessoas)||num(e.PessoasPlanejado)||num(cad.NPessoas)||1;
        const potW=num(rr.PotenciaEquipamento)||num(rr.PotenciaW)||num(e.PotenciaW)||num(cad['PotenciaEquipamento (W)']);
        const kwh=(potW/1000)*(min/60),ce=kwh*taxaEnergia,tm=num(cad['TaxaMOD (R$/h)'])||taxaMODPadrao,cm=(min/60)*pessoas*tm;energiaTotal+=ce;modTotal+=cm;
        etapas.push({OP:op.CodOP,Ordem:e.Ordem||'',Processo:e.Processo||'',Equipamento:rr.Equipamento||cad.Equipamento||'',TempoMin:min,Pessoas:pessoas,PotenciaW:potW,EnergiaKWh:kwh,TaxaEnergia_R_kWh:taxaEnergia,CustoEnergia:ce,TaxaMOD_R_h:tm,CustoMOD:cm,'Cálculo energia':`${potW}/1000 × ${min}/60 × ${taxaEnergia} = ${ce}`,'Cálculo MOD':`${min}/60 × ${pessoas} × ${tm} = ${cm}`});
      });
    });
    (data.perdas||[]).filter(p=>p.CodOP===op.CodOP).forEach(p=>{const q=num(p.QuantidadePerdida),cod=p.CodigoMaterial||p.ItemPerdaCodigo,unit=materialUnitCostV3822(cod),tot=q*unit;perdasTotal+=tot;perdas.push({OP:op.CodOP,Tipo:p.PerdaAlvoTipo||'',Item:cod||'',QuantidadePerdida:q,UM:p.Unidade||'',CustoUnitario:unit,'Cálculo aberto':`${q} × ${unit} = ${tot}`,Resultado:tot});});
  });
  const total=matTotal+energiaTotal+modTotal+perdasTotal;
  return {resumo:[{OPMae:codMae,OPsIncluidas:fam.map(o=>o.CodOP).join('; '),CustoMateriais:matTotal,CustoEnergia:energiaTotal,CustoMOD:modTotal,CustoPerdas:perdasTotal,CustoTotal:total,'Regra total':'Materiais + Energia + MOD + Perdas'}],materiais,etapas,perdas,regras:[{'Ordem':1,'Campo calculado':'Custo unitário','Regra/Fórmula':'Somatório do custo total das entradas ÷ somatório das quantidades convertidas para a UM cadastrada do material'},{'Ordem':2,'Campo calculado':'Material','Regra/Fórmula':'Quantidade da OP × custo unitário normalizado'},{'Ordem':3,'Campo calculado':'Energia','Regra/Fórmula':'(Potência W ÷ 1000) × (tempo min ÷ 60) × tarifa R$/kWh'},{'Ordem':4,'Campo calculado':'Mão de obra','Regra/Fórmula':'(tempo min ÷ 60) × pessoas × taxa R$/h'},{'Ordem':5,'Campo calculado':'Total','Regra/Fórmula':'Materiais + Energia + MOD + Perdas'}]};
}
