/* =========================================================
   MES LION V38.23 — SIMULAÇÃO DA FAMÍLIA DA OP + AUDITORIA DO ROTEIRO
   ========================================================= */
const APP_PATCH_V3823='v38.23-simulacao-familia-formula-auditoria-roteiro';

function familiaOPV3823(op){
  if(!op||!op.CodOP)return [];
  const base=String(op.OP_Base||op.OPBase||op.CodOP).replace(/-PA$/,'');
  const pa=(data.op||[]).find(o=>String(o.CodOP||'')===base+'-PA')||op;
  const codPA=pa.CodOP;
  const set=new Map();
  (data.op||[]).forEach(o=>{
    const c=String(o.CodOP||'');
    if(c===codPA||String(o.OP_Pai||o.OPPai||'')===codPA||String(o.OP_Base||o.OPBase||'')===base||c.startsWith(base+'-'))set.set(c,o);
  });
  set.set(pa.CodOP,pa);
  return [...set.values()].sort((a,b)=>String(a.CodOP).localeCompare(String(b.CodOP),'pt-BR'));
}
function opEhPAV3823(op){return String(op?.TipoOP||'').toUpperCase()==='PA'||/-PA$/.test(String(op?.CodOP||''));}
function opConcluidaV3823(op){return /CONCLU|ENCERR/.test(String(op?.Status||'').toUpperCase());}
