/* =========================================================
   MES LION V38.25 — FORMULAÇÃO SOBRE A MASSA APONTADA DA ETAPA
   Regra: os percentuais da formulação incidem somente sobre a
   massa total apontada da etapa produtora do grupo (slurry
   cátodo, slurry ânodo ou preparação do eletrólito), nunca sobre
   quantidades de etapas posteriores em m ou unidades.
   ========================================================= */
const APP_PATCH_V3825='v38.25-formulacao-massa-apontada-etapa';

function textoOPV3825(op){
  return [op?.DescricaoProduto,op?.Produto,op?.CodigoProduto,op?.CodigoPI,
          ...(data.op_etapas||[]).filter(e=>e.CodOP===op?.CodOP).map(e=>e.Processo)]
    .filter(Boolean).join(' ').toUpperCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'');
}
function opFonteGrupoV3825(familia,grupo){
  const g=String(grupo||'').toUpperCase();
  if(g==='CATODO')return familia.find(o=>{const t=textoOPV3825(o);return (t.includes('SLURRY')||t.includes('MISTURA'))&&t.includes('CATODO');});
  if(g==='ANODO')return familia.find(o=>{const t=textoOPV3825(o);return (t.includes('SLURRY')||t.includes('MISTURA'))&&t.includes('ANODO');});
  if(g==='ELETROLITO')return familia.find(o=>{const t=textoOPV3825(o);return t.includes('ELETROLITO')||t.includes('INJETORA');})||familia.find(op=>
    (data.op_materiais||[]).some(m=>m.CodOP===op.CodOP&&['MP0016','MP0017'].includes(m.CodigoMaterial))
  );
  return null;
}
function massaApontadaOPV3825(op,grupo,itensGrupo){
  if(!op)return 0;
  const apont=(data.producao||[]).filter(p=>p.CodOP===op.CodOP)
    .reduce((s,p)=>s+num(p.QuantidadeProduzida||p['Quantidade produzida']||p.QtdProduzida),0);
  if(apont>0)return apont;
  const qop=num(op.QtdProduzida||op.QuantidadeProduzida);
  if(qop>0)return qop;
  // Para eletrólito sem PI próprio, a massa-base é o total efetivamente consumido
  // dos componentes da formulação na etapa de montagem.
  if(String(grupo).toUpperCase()==='ELETROLITO'){
    const cods=new Set((itensGrupo||[]).map(i=>i.CodigoMaterial));
    const cons=(data.consumos_materiais||[]).filter(c=>c.CodOP===op.CodOP&&cods.has(c.CodigoMaterial));
    const soma=cons.reduce((s,c)=>s+num(c.ConsumoLiquido||c.QtdConsumida),0);
    if(soma>0)return soma;
    const plan=(data.op_materiais||[]).filter(m=>m.CodOP===op.CodOP&&cods.has(m.CodigoMaterial));
    const sp=plan.reduce((s,m)=>s+num(m.QtdPlanejada||m.QtdBase),0);
    if(sp>0)return sp;
  }
  return num(op.QtdPlanejada||op.QuantidadePlanejada);
}

linhasMateriaisFamiliaV3823=function(familia,codFormula,fator){
  const f=codFormula?formulaByCodeV3813(codFormula):null;
  const itensF=f?(data.formulacao_itens||[]).filter(i=>i.CodFormula===f.CodFormula):[];
  const linhas=[];
  const fontes={};
  ['CATODO','ANODO','ELETROLITO'].forEach(g=>fontes[g]=opFonteGrupoV3825(familia,g));

  familia.forEach(op=>{
    const consumos=(data.consumos_materiais||[]).filter(c=>c.CodOP===op.CodOP);
    const planejados=(data.op_materiais||[]).filter(m=>m.CodOP===op.CodOP);
    let grupoFonte='';
    Object.keys(fontes).forEach(g=>{if(fontes[g]?.CodOP===op.CodOP)grupoFonte=g;});
    const itensGrupo=f&&grupoFonte?itensF.filter(i=>String(i.Grupo).toUpperCase()===grupoFonte):[];

    if(f&&grupoFonte&&itensGrupo.length){
      const massaEtapa=massaApontadaOPV3825(op,grupoFonte,itensGrupo);
      itensGrupo.forEach(i=>{
        const pct=num(i.Percentual),q=massaEtapa*pct/100*fator,u=custoUnitMaterialV3823(i.CodigoMaterial);
        linhas.push({op:op.CodOP,tipo:op.TipoOP||'',grupo:grupoFonte,material:i.CodigoMaterial,
          descricao:i.DescricaoMaterial||'',
          origem:`Formulação ${f.CodFormula} v${f.Versao||'1'} — ${pct}% × massa total apontada da etapa ${massaEtapa}`,
          qtd:q,um:i.UM||'kg',unit:u,total:q*u,
          massaBaseEtapa:massaEtapa,percentual:pct,regra:'massa apontada da etapa × percentual ÷ 100'});
      });
      // Materiais estruturais ou auxiliares não pertencentes à formulação permanecem auditáveis.
      const cods=new Set(itensGrupo.map(i=>i.CodigoMaterial));
      const base=consumos.length?consumos:planejados;
      base.filter(m=>!cods.has(m.CodigoMaterial)).forEach(m=>{
        const q=num(m.ConsumoLiquido||m.QtdConsumida||m.QtdPlanejada||m.QtdBase)*fator;
        const u=num(m.CustoUnitarioLote)||custoUnitMaterialV3823(m.CodigoMaterial);
        linhas.push({op:op.CodOP,tipo:op.TipoOP||'',grupo:'NÃO FORMULADO',material:m.CodigoMaterial,
          descricao:m.DescricaoMaterial||'',origem:consumos.length?'Apontamento/lote efetivo':'Planejado na OP',qtd:q,um:m.UM||'',unit:u,total:q*u});
      });
    }else{
      // Etapas posteriores (coating, corte, montagem etc.) nunca recebem novamente
      // os percentuais de slurry. Usam somente os materiais efetivamente apontados.
      const base=consumos.length?consumos:planejados;
      base.forEach(m=>{
        const q=num(m.ConsumoLiquido||m.QtdConsumida||m.QtdPlanejada||m.QtdBase)*fator;
        const u=num(m.CustoUnitarioLote)||custoUnitMaterialV3823(m.CodigoMaterial);
        linhas.push({op:op.CodOP,tipo:op.TipoOP||'',grupo:'APONTAMENTO DA ETAPA',material:m.CodigoMaterial,
          descricao:m.DescricaoMaterial||'',origem:consumos.length?'Apontamento/lote efetivo':'Planejado na OP',qtd:q,um:m.UM||'',unit:u,total:q*u});
      });
    }
  });
  return linhas;
};

