const _simulacoesModuleV3825=simulacoesModule;
simulacoesModule=function(){
  _simulacoesModuleV3825();
  const sub=$('subtitle');
  if(sub)sub.textContent='Simule a família completa da OP. A formulação incide somente sobre a massa apontada da respectiva etapa produtora; coating, corte e montagem usam seus próprios apontamentos.';
};
try{localStorage.setItem('MES_LION_VERSION_PATCH',APP_PATCH_V3825);}catch(e){console.warn('Persistência patch V38.25',e);}

/* =========================================================
   MES LION V38.26 — PARIDADE CUSTOS × SIMULAÇÕES
   A simulação com a mesma OP, mesma formulação, mesma quantidade
   e fator 1 parte obrigatoriamente da mesma memória consolidada
   do módulo Custos Industriais. Formulação alternativa substitui
   somente os materiais dos grupos formulados, sem duplicá-los.
   ========================================================= */
const APP_PATCH_V3826='v38.26-paridade-custos-simulacoes';

function formulaCongeladaFamiliaV3826(familia){
  const cod=(familia||[]).map(o=>o.CodFormula).find(Boolean)||'';
  return cod;
}
function linhaBaseMaterialV3826(op,m,fator){
  const q=num(m.QtdConsumida)||num(m.QtdReal)||num(m.Qtd)||num(m.QtdPlanejada)||num(m.QtdBase);
  const u=num(m.CustoUnitarioLote)||num(m.ValorUnitario)||custoUnitMaterialV3823(m.CodigoMaterial);
  const totalBase=num(m.CustoTotal)||q*u;
  return {op:op.CodOP,tipo:op.TipoOP||'',grupo:'BASE CONSOLIDADA DA OP',material:m.CodigoMaterial||'',
    descricao:m.DescricaoMaterial||materialPorCodigo(m.CodigoMaterial)?.DescricaoMateriais||'',
    origem:'Mesma origem utilizada no módulo Custos Industriais',qtd:q*fator,um:m.UM||'',unit:u,total:totalBase*fator,
    regra:'quantidade da OP × valor unitário utilizado no custo consolidado'};
}
function linhasBaseFamiliaV3826(familia,fator){
  const linhas=[];
  (familia||[]).forEach(op=>{
    (typeof opMaterials==='function'?opMaterials(op.CodOP):(data.op_materiais||[]).filter(m=>m.CodOP===op.CodOP))
      .forEach(m=>linhas.push(linhaBaseMaterialV3826(op,m,fator)));
  });
  return linhas;
}
function grupoCodigosFormulaV3826(codFormula,grupo){
  return new Set((data.formulacao_itens||[]).filter(i=>i.CodFormula===codFormula&&String(i.Grupo||'').toUpperCase()===grupo).map(i=>i.CodigoMaterial));
}
function linhasMateriaisCenarioV3826(familia,codFormula,fator){
  const frozen=formulaCongeladaFamiliaV3826(familia);
  const mesma=!codFormula||!frozen||codFormula===frozen;
  const baseLines=linhasBaseFamiliaV3826(familia,fator);
  if(mesma)return {linhas:baseLines,modo:'BASE_OP',formula:frozen||codFormula||''};

  const f=formulaByCodeV3813(codFormula);
  if(!f)return {linhas:baseLines,modo:'BASE_OP',formula:frozen||''};
  const itens=(data.formulacao_itens||[]).filter(i=>i.CodFormula===codFormula);
  const fontes={CATODO:opFonteGrupoV3825(familia,'CATODO'),ANODO:opFonteGrupoV3825(familia,'ANODO'),ELETROLITO:opFonteGrupoV3825(familia,'ELETROLITO')};
  const removerPorOP=new Map();
  Object.entries(fontes).forEach(([g,op])=>{
    if(!op)return;
    const cods=new Set([...grupoCodigosFormulaV3826(codFormula,g),...grupoCodigosFormulaV3826(frozen,g)]);
    removerPorOP.set(op.CodOP,cods);
  });
  const linhas=baseLines.filter(l=>!removerPorOP.get(l.op)?.has(l.material));
  Object.entries(fontes).forEach(([grupo,op])=>{
    if(!op)return;
    const itensGrupo=itens.filter(i=>String(i.Grupo||'').toUpperCase()===grupo);
    if(!itensGrupo.length)return;
    const massa=massaApontadaOPV3825(op,grupo,itensGrupo);
    itensGrupo.forEach(i=>{
      const pct=num(i.Percentual),q=massa*pct/100*fator,u=custoUnitMaterialV3823(i.CodigoMaterial);
      linhas.push({op:op.CodOP,tipo:op.TipoOP||'',grupo,material:i.CodigoMaterial,descricao:i.DescricaoMaterial||'',
        origem:`SUBSTITUIÇÃO DE CENÁRIO — ${codFormula} v${f.Versao||'1'} — ${pct}% × massa apontada da etapa ${massa}`,
        qtd:q,um:i.UM||'kg',unit:u,total:q*u,massaBaseEtapa:massa,percentual:pct,
        regra:'massa apontada da etapa × percentual da formulação alternativa ÷ 100'});
    });
  });
  return {linhas,modo:'FORMULA_ALTERNATIVA',formula:codFormula};
}

calcularSimulacao=function(show=true){
  const op=opPorCodigo($('sim_op')?.value),qtd=num($('sim_qtd')?.value);
  const familia=familiaOPV3823(op);
  const baseQtd=op?(num(op.QtdPlanejada||op.QuantidadePlanejada)||1):1;
  const fator=op&&qtd>0?qtd/baseQtd:0;
  const frozen=formulaCongeladaFamiliaV3826(familia)||op?.CodFormula||'';
  const codFormula=$('sim_formula')?.value||frozen;
  const cenario=linhasMateriaisCenarioV3826(familia,codFormula,fator);
  const baseCusto=op&&typeof calcCustoFamiliaOPV33==='function'?calcCustoFamiliaOPV33(op.CodOP,false,{}):{};
  let custoMat=cenario.linhas.reduce((s,x)=>s+num(x.total),0);
  // Controle obrigatório de paridade: no cenário-base, usa exatamente o total do módulo de custos.
  if(cenario.modo==='BASE_OP'&&baseCusto.CustoMateriais!==undefined)custoMat=num(baseCusto.CustoMateriais)*fator;
  const proc=custosProcessoFamiliaV3823(familia,fator);
  let custoEnergia=num(baseCusto.CustoEnergia)*fator;
  let custoMOD=num(baseCusto.CustoMOD)*fator;
  let outros=num(baseCusto.CustoPerdas)*fator;
  if(!Number.isFinite(custoEnergia))custoEnergia=proc.energia;
  if(!Number.isFinite(custoMOD))custoMOD=proc.mod;
  const total=custoMat+custoEnergia+custoMOD+outros,unit=qtd>0?total/qtd:0;
  const vals={sim_fator:fator.toFixed(4),sim_ops_count:String(familia.length),sim_mat:custoMat.toFixed(2),sim_energia:custoEnergia.toFixed(2),sim_mod:custoMOD.toFixed(2),sim_outros:outros.toFixed(2),sim_total:total.toFixed(2),sim_unit:unit.toFixed(4),sim_temp_hora:(proc.tempMin/60).toFixed(2)};
  Object.entries(vals).forEach(([id,v])=>{if($(id))$(id).value=v;});
  window.__simAuditV3823={op,familia,codFormula,frozenFormula:frozen,fator,qtd,mats:cenario.linhas,proc,outros,total,unit,custoMat,custoEnergia,custoMOD,modo:cenario.modo,baseCusto};
  if(show&&$('sim_result')){
    const diffMat=custoMat-num(baseCusto.CustoMateriais)*fator;
    $('sim_result').innerHTML=`<div class="form"><h3>Memória de cálculo — família da OP</h3>
    <p><b>OP PA:</b> ${htmlEscape(op?.CodOP||'')} • <b>OPs consideradas:</b> ${familia.length} • <b>Formulação congelada:</b> ${htmlEscape(frozen||'não informada')} • <b>Formulação do cenário:</b> ${htmlEscape(codFormula||frozen||'')}</p>
    <div class="card ${cenario.modo==='BASE_OP'?'':'warn'}"><b>Regra aplicada:</b> ${cenario.modo==='BASE_OP'?'Cenário-base copiado da mesma memória consolidada do módulo Custos Industriais.':'Formulação alternativa: substituição apenas dos grupos formulados; materiais estruturais permanecem da OP.'}<br>
    <b>Controle de paridade dos materiais:</b> custo-base ${money(num(baseCusto.CustoMateriais)*fator)} • simulação ${money(custoMat)} • diferença ${money(diffMat)}</div>
    <div class="table-wrap"><table><thead><tr><th>OP</th><th>Tipo</th><th>Grupo</th><th>Material</th><th>Origem/regra</th><th>Quantidade</th><th>UM</th><th>Valor unitário</th><th>Cálculo</th><th>Total</th></tr></thead><tbody>${cenario.linhas.map(x=>`<tr><td>${htmlEscape(x.op)}</td><td>${htmlEscape(x.tipo)}</td><td>${htmlEscape(x.grupo)}</td><td>${htmlEscape(x.material+' — '+x.descricao)}</td><td>${htmlEscape(x.origem)}</td><td>${fmt(x.qtd,6)}</td><td>${htmlEscape(x.um)}</td><td>${money(x.unit)}</td><td>${fmt(x.qtd,6)} × ${money(x.unit)}</td><td>${money(x.total)}</td></tr>`).join('')}</tbody></table></div>
    <h4>Resumo compatível com Custos Industriais</h4><table><tbody><tr><th>Materiais</th><td>${money(custoMat)}</td></tr><tr><th>Energia</th><td>${money(custoEnergia)}</td></tr><tr><th>Mão de obra</th><td>${money(custoMOD)}</td></tr><tr><th>Perdas</th><td>${money(outros)}</td></tr><tr><th>Total</th><td><b>${money(total)}</b></td></tr></tbody></table></div>`;
    const tableRows=(proc?.linhas||[]).map(x=>`<tr><td>${htmlEscape(x.op)}</td><td>${htmlEscape(x.equipamento||'')}</td><td>${fmt(x.potencia||0,2)}</td><td>${fmt(x.tempo||0,2)}</td><td>${fmt(x.pessoas||0,2)}</td><td>${fmt(x.taxaEnergia||0,4)}</td><td>${htmlEscape(x.calculoEnergia||'')}</td><td>${money(x.energia)}</td><td>${fmt(x.taxaMOD||0,4)}</td><td>${htmlEscape(x.calculoMOD||'')}</td><td>${money(x.mod)}</td></tr>`).join('');
    $('sim_result').insertAdjacentHTML('beforeend',`<div class="form"><h3>Auditoria aberta de energia e mão de obra</h3><p>Os totais apresentados acima usam a mesma consolidação do módulo Custos Industriais. A tabela abaixo evidencia as etapas e recursos que sustentam esses valores.</p><div class="table-wrap"><table><thead><tr><th>OP</th><th>Equipamento</th><th>Potência W</th><th>Tempo min</th><th>Pessoas</th><th>Tarifa energia</th><th>Cálculo energia</th><th>Custo energia</th><th>Taxa MOD</th><th>Cálculo MOD</th><th>Custo MOD</th></tr></thead><tbody>${tableRows}</tbody></table></div></div>`);
  }
  return {op,familia,fator,custoMat,custoEnergia,custoMOD,custoOutros:outros,total,unit,proc,mats:cenario.linhas};
};

