      const ja=mats.find(m=>String(m.CodigoMaterial)===String(i.CodigoMaterial));
      if(!ja){pend.push(`${op.CodOP} / ${grupo}: ${i.CodigoMaterial} — ${i.DescricaoMaterial||''} não está alocado em nenhuma etapa/equipamento do roteiro`);return;}
      const quantidade=massaBase*num(i.Percentual)/100,unit=materialUnitCost(i.CodigoMaterial)||num(ja.CustoUnitario)||0;
