/* ============================================================
   MES LION V39.5 — DASHBOARD INDUSTRIAL, HELP DESK, AUDITORIA,
   OP LIMPA, PASSAPORTE COMPLETO E RECÁLCULO DE OP REABERTA
   ============================================================ */
const APP_PATCH_V395='v39.5-dashboard-helpdesk-op-passaporte-auditoria';

function fmtMax4V395(v){
  if(v===null||v===undefined||v==='')return '';
  if(typeof v==='number'&&Number.isFinite(v))return v.toLocaleString('pt-BR',{minimumFractionDigits:0,maximumFractionDigits:4});
  const s=String(v).trim();
  if(/^[-+]?\d+(?:[.,]\d+)?$/.test(s)){
    const n=num(s);if(Number.isFinite(n))return n.toLocaleString('pt-BR',{minimumFractionDigits:0,maximumFractionDigits:4});
  }
  return s;
}
function money2V395(v){return Number(num(v)||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL',minimumFractionDigits:2,maximumFractionDigits:2});}
function num4V395(v){return Number(num(v)||0).toLocaleString('pt-BR',{minimumFractionDigits:0,maximumFractionDigits:4});}

