function kanbanBucketV395(status){const s=String(status||'').toLowerCase();if(s.includes('reab'))return 'Reabertas';if(s.includes('concl')||s.includes('encerr')||s.includes('final'))return 'Concluídas';if(s.includes('produ')||s.includes('exec'))return 'Em produção';return 'Planejadas';}
function updateDashboardV395(){
  let rows=dashboardRowsV395();const opf=$('df_op_v395')?.value||'',pf=$('df_proj_v395')?.value||'',cf=$('df_chem_v395')?.value||'',q=String($('df_q_v395')?.value||'').toLowerCase();
  rows=rows.filter(r=>(!opf||r.op.CodOP===opf)&&(!pf||r.project===pf)&&(!cf||r.chem===cf)&&(!q||[r.op.CodOP,opProductInfo(r.op).desc,r.op.Status,r.project,r.chem].join(' ').toLowerCase().includes(q)));
  const sum=k=>rows.reduce((a,r)=>a+num(r[k]),0), buckets=['Planejadas','Em produção','Reabertas','Concluídas'];
  const kanban=buckets.map(b=>`<div class="kanban-col-v395"><h3>${b}<span>${rows.filter(r=>kanbanBucketV395(r.op.Status)===b).length}</span></h3>${rows.filter(r=>kanbanBucketV395(r.op.Status)===b).map(r=>`<button class="kanban-card-v395" onclick="render('op');setTimeout(()=>{if($('selOp')){$('selOp').value='${htmlEscape(r.op.CodOP)}';showOP();}},60)"><b>${htmlEscape(r.op.CodOP)}</b><span>${htmlEscape(opProductInfo(r.op).desc||r.op.Produto||'')}</span><small>${htmlEscape(r.chem)} · ${htmlEscape(r.project||'Sem projeto')} · ${money2V395(r.total)}</small></button>`).join('')||'<span class="muted">Sem OPs.</span>'}</div>`).join('');
  const costRows=rows.map(r=>`<tr><td>${htmlEscape(r.op.CodOP)}</td><td>${htmlEscape(r.chem)}</td><td>${htmlEscape(r.project||'-')}</td><td class="num">${money2V395(r.mat)}</td><td class="num">${money2V395(r.energy)}</td><td class="num">${money2V395(r.mod)}</td><td class="num">${money2V395(r.total)}</td><td class="num">${num4V395(r.co2)}</td></tr>`).join('');
  $('dashV395').innerHTML=`<div class="dash-metrics-v395"><div class="metric-v395"><span>OPs no filtro</span><strong>${rows.length}</strong></div><div class="metric-v395"><span>Materiais</span><strong>${money2V395(sum('mat'))}</strong></div><div class="metric-v395"><span>Energia</span><strong>${money2V395(sum('energy'))}</strong></div><div class="metric-v395"><span>MOD</span><strong>${money2V395(sum('mod'))}</strong></div><div class="metric-v395"><span>Custo total</span><strong>${money2V395(sum('total'))}</strong></div><div class="metric-v395"><span>CO₂eq</span><strong>${num4V395(sum('co2'))}</strong><small>kg CO₂eq</small></div></div><div class="industrial-panel-v395"><h3>Kanban de acompanhamento da produção</h3><div class="kanban-v395">${kanban}</div></div><div class="industrial-panel-v395"><h3>Custos e emissões por OP</h3><div class="table-wrap"><table class="cost-table-v395"><thead><tr><th>OP</th><th>Química</th><th>Projeto</th><th>Materiais</th><th>Energia</th><th>MOD</th><th>Total</th><th>kg CO₂eq</th></tr></thead><tbody>${costRows||'<tr><td colspan="8">Sem dados para o filtro.</td></tr>'}</tbody></table></div></div>`;
}

function excelValueV395(v){return excelEscape(fmtMax4V395(v));}
downloadAuditExcelV3819=function(filename,title,sections){
  const sectionHtml=(sections||[]).map(s=>{const rows=s.rows||[],cols=s.cols||Object.keys(rows[0]||{});return `<h2>${excelEscape(s.title||'Tabela')}</h2>${s.note?`<p>${excelEscape(s.note)}</p>`:''}<table><thead><tr>${cols.map(c=>`<th>${excelEscape(c)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${cols.map(c=>`<td>${excelValueV395(r[c]??'')}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${Math.max(cols.length,1)}">Sem registros</td></tr>`}</tbody></table><br>`;}).join('');
  const html=`<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:Arial;font-size:10pt;color:#1f3447}h1{color:#074a7d;border-bottom:3px solid #5ba83d;padding-bottom:8px}h2{color:#074a7d;background:#edf4fa;padding:6px;border-left:4px solid #5ba83d}table{border-collapse:collapse;width:100%}th,td{border:1px solid #cdd9e3;padding:4px 6px;vertical-align:top}th{background:#dbe8f2;color:#073f70;font-weight:bold}td{mso-number-format:"General"}.note{color:#617687}</style></head><body><h1>${excelEscape(title)}</h1><p class="note">Auditoria MES LION · ${excelEscape(new Date().toLocaleString('pt-BR'))}. Valores numéricos exibidos com no máximo 4 casas decimais; regras/fórmulas permanecem abertas para auditoria.</p>${sectionHtml}</body></html>`;
  const blob=new Blob(['\ufeff',html],{type:'application/vnd.ms-excel;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename.replace(/[^a-z0-9_.-]+/gi,'_');document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500);
};
function exportACVAuditV395(){const cod=$('s_op')?.value;if(!cod)return alert('Selecione uma OP mãe / PA.');const a=auditoriaACVFamiliaV391(cod,{energyFactor:$('s_energy_factor')?.value});const r=calcSustFamiliaOPV33(cod,false,{energyFactor:$('s_energy_factor')?.value});downloadAuditExcelV3819(`auditoria_acv_${cod}.xls`,`Auditoria ACV / CO₂eq — ${cod}`,[{title:'Resumo',rows:[r]},{title:'Memória de cálculo linha a linha',rows:a.linhas},{title:'OPs da família',rows:a.familia}]);}
