function bpDashboardBodyV395(bp){const prod=produtoPorCodigo(bp.CodProduto)||{},op=opPorCodigo(bp.CodOrdemProducao)||{},mats=bpPublicMaterialRows(bp),emiss=bpEmissionValue(bp),filhos=(data.estrutura||[]).filter(p=>p['Código Pai']==bp.CodProduto),descricao=prod['Descrição']||op.DescricaoProduto||op.Produto||'';return `<div class="dash-public passport-public"><section class="passport-hero"><div><span class="eyebrow">DIGITAL BATTERY PASSPORT</span><h1>${htmlEscape(descricao||bp.CodProduto||'Bateria')}</h1><p>${htmlEscape(bp.CodProduto||'')} · ${htmlEscape(bp.IDLote||'Lote não informado')}</p></div><div class="passport-status"><span>${htmlEscape(bp.StatusPassaporte||'RASCUNHO')}</span><b>${htmlEscape(bp.BatteryPassportID||'')}</b></div></section><div class="kpis passport-kpis"><div class="kpi"><b>Produto</b><span>${htmlEscape(bp.CodProduto||'-')}</span></div><div class="kpi"><b>OP de origem</b><span>${htmlEscape(bp.CodOrdemProducao||'-')}</span></div><div class="kpi"><b>Cliente</b><span>${htmlEscape(bp.ClienteNomeSnapshot||'-')}</span></div><div class="kpi"><b>CO₂eq total</b><span>${num4V395(emiss)} kg</span></div></div><section class="passport-section"><h2>Custos industriais da bateria</h2>${bpCostHTMLV395(bp)}</section><details open class="passport-section"><summary><b>Identificação e rastreabilidade</b></summary>${kvHTML({...bp,DescricaoProduto:descricao},['BatteryPassportID','BatteryPassportGUID','CodOrdemProducao','CodProduto','DescricaoProduto','IDLote','ClienteNomeSnapshot','StatusPassaporte','VersaoPassaporte'])}<h2>Materiais, lotes e fornecedores</h2>${tableHTML(mats,['CodigoMaterial','Material','Quantidade','UM','Lote','Fornecedor','NotaFiscal'])}</details><details class="passport-section"><summary><b>Dados técnicos e desempenho</b></summary>${kvHTML({...prod,...bp},['Célula','Composição','Modelo','Capacidade Final (Ah)','Tensão Nominal (V)','Energia (Wh)','Tec_VidaUtil_Texto','Tec_ResistenciaInterna_Texto','Tec_RoundTripEfficiency_Texto','Tec_FaixaTemperatura_Texto'])}</details><details class="passport-section"><summary><b>Qualificação da bateria</b></summary><div class="bp-img-grid">${imageBlock('Imagem da bateria',bp.ImagemBateria)}${imageBlock('Teste de ciclos',bp.ImagemTesteCiclos)}${imageBlock('Teste de impedância',bp.ImagemImpedancia||bp.Tec_ResistenciaInterna_ImagemPath)}${imageBlock('Teste de aging',bp.ImagemAging)}</div></details><details class="passport-section"><summary><b>Sustentabilidade e conformidade</b></summary>${kvHTML(bp,['Sust_CarbonFootprint_Texto','Sust_DueDiligence_Texto','Sust_ConteudoReciclado_Texto','Sust_ConteudoRenovavel_Texto','Comp_DeclaracaoUE_Texto','Eng_Seguranca_Texto'])}</details><section class="passport-section two"><div><h2>Estrutura PA → PI</h2>${tableHTML(filhos,['Código','Descrição','Tipo Produto','Código Pai','Composição','Modelo'])}</div>${qrCardHTML(bp,'Consultar relatório digital')}</section></div>`;}
