function familyMaterialsV395(op){const fam=op.TypeOP==='PA'?opFamilyV33(op.CodOP):opFamilyV33(rootOPV395(op));const codes=fam.length?fam.map(x=>x.CodOP):[op.CodOP];return (data.op_materiais||[]).filter(m=>codes.includes(m.CodOP)&&!String(m.TipoConsumo||'').toLowerCase().includes('pi intermedi'));}
function massProjectionV395(op){const mats=familyMaterialsV395(op);let total=0,missing=[];mats.forEach(m=>{const q=num(m.QtdConsumida)||num(m.QtdReal)||num(m.QtdPlanejada)||num(m.QtdBase),cv=converterParaKgV394(q,m.UM,m.CodigoMaterial);if(cv.ok)total+=cv.kg;else missing.push(m.CodigoMaterial);});const fam=opFamilyV33(rootOPV395(op));const codes=fam.length?fam.map(x=>x.CodOP):[op.CodOP];let lost=0;(data.perdas||[]).filter(p=>codes.includes(p.CodOP)&&String(p.PerdaAlvoTipo||'').toUpperCase()==='MATERIAL').forEach(p=>{const cv=converterParaKgV394(num(p.QuantidadePerdida),p.Unidade||p.UM,p.CodigoMaterial||p.ItemPerdaCodigo);if(cv.ok)lost+=cv.kg;});return {total,lost,missing};}
