const APP_PATCH_V397='v39.7-dashboard-industrial';
let v397DashCache={sig:'',rows:[]};
function v397RootOps(){return (data.op||[]).filter(o=>String(o.TipoOP||'').toUpperCase()==='PA'||(!o.OP_Pai&&!o.CodigoPI));}
function v397ProjectOfOP(o){return o.CodProjeto||o.CodigoProjeto||o.Projeto||o.NomeProjeto||'';}
function v397ChemOfOP(o){return o.QuimicaFormula||o.Composicao||o.Composição||'';}
function v397FamilyCodes(op){const root=rootOPV395(op);const fam=opFamilyV33(root);return fam.length?fam.map(x=>x.CodOP):[op.CodOP];}
function v397LossMassKg(codes){let total=0,missing=0;(data.perdas||[]).filter(p=>codes.includes(p.CodOP)&&String(p.PerdaAlvoTipo||'').toUpperCase()==='MATERIAL').forEach(p=>{const cv=converterParaKgV394(num(p.QuantidadePerdida||p.QtdPerdida||p.Quantidade),p.Unidade||p.UM,p.CodigoMaterial||p.ItemPerdaCodigo);if(cv.ok)total+=cv.kg;else missing++;});return {total,missing};}
function v397FamilyMetrics(op){
  const root=rootOPV395(op), codes=v397FamilyCodes(op);
  let c=(data.custos_op||[]).find(x=>x.CodOP===root);
  if(!c){try{c=calcCustoFamiliaOPV33(root,false,{})||{};}catch(e){c={};}}
  let s=(data.sust_op||[]).find(x=>x.CodOP===root);
  if(!s){try{s=calcSustFamiliaOPV33(root,false,{})||{};}catch(e){s={};}}
  const stages=(data.op_etapas||[]).filter(e=>codes.includes(e.CodOP));
  const done=stages.filter(e=>isConcluido(e.Status)).length;
  const pct=stages.length?Math.round(done/stages.length*100):(isConcluido(op.Status)?100:0);
  const mats=(data.op_materiais||[]).filter(m=>codes.includes(m.CodOP));
  const traceable=mats.filter(m=>String(m.Lote||m.LotesConsumidos||'').trim()).length;
  const resourceReady=stages.filter(e=>String(e.CodEquipamento||e.Recurso||e.Equipamento||'').trim()).length;
  const loss=v397LossMassKg(codes);
  return {op,root,codes,c,s,stages,mats,pct,tracePct:mats.length?Math.round(traceable/mats.length*100):0,resourcePct:stages.length?Math.round(resourceReady/stages.length*100):0,lossKg:loss.total,lossMissing:loss.missing};
}
function v397DashboardRows(){
  const roots=v397RootOps();
  const sig=[roots.length,(data.op_etapas||[]).length,(data.op_materiais||[]).length,(data.custos_op||[]).length,(data.sust_op||[]).length,(data.perdas||[]).length].join('|');
  if(v397DashCache.sig===sig&&v397DashCache.rows.length===roots.length)return v397DashCache.rows;
  v397DashCache={sig,rows:roots.map(v397FamilyMetrics)};return v397DashCache.rows;
}
function v397Unique(arr){return [...new Set(arr.filter(x=>String(x||'').trim()))].sort((a,b)=>String(a).localeCompare(String(b),'pt-BR'));}
function v397FilterOptions(values,label){return `<option value="">${label}</option>`+v397Unique(values).map(v=>`<option value="${htmlEscape(v)}">${htmlEscape(v)}</option>`).join('');}
function v397FilteredRows(){
  const opf=$('dash397_op')?.value||'', pf=$('dash397_proj')?.value||'', qf=$('dash397_quim')?.value||'';
  return v397DashboardRows().filter(r=>(!opf||r.root===opf)&&(!pf||v397ProjectOfOP(r.op)===pf)&&(!qf||v397ChemOfOP(r.op)===qf));
}
function v397Money(v){return Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL',minimumFractionDigits:2,maximumFractionDigits:2});}
function v397N(v,d=2){return Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});}
function v397Metric(title,value,unit,sub,cls=''){return `<div class="ind-metric ${cls}"><span>${htmlEscape(title)}</span><strong>${value}</strong><em>${htmlEscape(unit||'')}</em><small>${htmlEscape(sub||'')}</small></div>`;}
function v397StatusBucket(s){s=String(s||'').toLowerCase();if(isConcluido(s)||s.includes('encerr'))return 'done';if(s.includes('exec')||s.includes('reab')||s.includes('andamento')||s.includes('produ'))return 'run';if(s.includes('bloq')||s.includes('cancel')||s.includes('susp'))return 'hold';return 'plan';}
function v397Kanban(rows){
  const defs=[['plan','Planejadas'],['run','Em execução'],['hold','Bloqueadas / atenção'],['done','Concluídas']];
  return `<div class="ind-kanban">${defs.map(([key,title])=>{const rr=rows.filter(r=>v397StatusBucket(r.op.Status)===key);return `<section class="kan-col ${key}"><header><b>${title}</b><span>${rr.length}</span></header><div class="kan-list">${rr.length?rr.map(r=>`<button onclick="render('op')"><b>${htmlEscape(r.root)}</b><span>${htmlEscape(r.op.DescricaoProduto||r.op.CodigoProduto||'')}</span><div class="kan-progress"><i style="width:${r.pct}%"></i></div><small>${r.pct}% etapas · ${htmlEscape(v397ChemOfOP(r.op)||'Química n/d')}</small></button>`).join(''):'<p>Sem OPs</p>'}</div></section>`}).join('')}</div>`;
}
function v397CostMix(rows){
  const mat=rows.reduce((s,r)=>s+num(r.c.CustoMateriais),0), en=rows.reduce((s,r)=>s+num(r.c.CustoEnergia),0), mod=rows.reduce((s,r)=>s+num(r.c.CustoMOD),0), per=rows.reduce((s,r)=>s+num(r.c.CustoPerdas),0), total=mat+en+mod+per;
  const parts=[['Materiais',mat],['Energia',en],['Mão de obra',mod],['Perdas',per]];
  return `<div class="ind-cost-total"><span>Custo industrial consolidado</span><strong>${v397Money(total)}</strong></div><div class="ind-cost-bars">${parts.map(([n,v])=>`<div><label><span>${n}</span><b>${v397Money(v)}</b></label><div><i style="width:${total?Math.max(1,v/total*100):0}%"></i></div><small>${total?v397N(v/total*100,1):'0,0'}%</small></div>`).join('')}</div>`;
}
function v397ProcessHealth(rows){
  const stages=rows.flatMap(r=>r.stages);const names=['Mistura','Coating','Calandragem','Corte','Montagem','Eletrólito','Formação','Aging','Qualificação'];
  return `<div class="ind-process-grid">${names.map(n=>{const rs=stages.filter(e=>String(e.Processo||'').toLowerCase().includes(n.toLowerCase().replace('eletrólito','eletrol'))||String(e.Processo||'').toLowerCase().includes(n.toLowerCase()));const done=rs.filter(e=>isConcluido(e.Status)).length,p=rs.length?Math.round(done/rs.length*100):0;return `<div><span>${stageIcon(n)}</span><b>${n}</b><strong>${rs.length}</strong><small>${p}% concluído</small><div><i style="width:${p}%"></i></div></div>`}).join('')}</div>`;
}
function v397OpsTable(rows){
  const rr=[...rows].sort((a,b)=>dateScore(b.op.DataCriacao||b.op.DataOP)-dateScore(a.op.DataCriacao||a.op.DataOP)).slice(0,8);
  if(!rr.length)return '<p class="muted">Sem famílias de OP para os filtros selecionados.</p>';
  return `<div class="table-wrap"><table class="ind-table"><thead><tr><th>OP PA</th><th>Produto</th><th>Química</th><th>Status</th><th>Avanço</th><th>Materiais</th><th>Energia</th><th>MOD</th><th>Total</th><th>CO₂eq</th></tr></thead><tbody>${rr.map(r=>`<tr><td><b>${htmlEscape(r.root)}</b></td><td>${htmlEscape(r.op.CodigoProduto||'')}</td><td>${htmlEscape(v397ChemOfOP(r.op)||'-')}</td><td>${htmlEscape(r.op.Status||'-')}</td><td>${r.pct}%</td><td>${v397Money(r.c.CustoMateriais)}</td><td>${v397Money(r.c.CustoEnergia)}</td><td>${v397Money(r.c.CustoMOD)}</td><td><b>${v397Money(r.c.CustoTotal)}</b></td><td>${v397N(r.s.CO2eqTotal,4)}</td></tr>`).join('')}</tbody></table></div>`;
}
function v397Alerts(rows){
  const allStages=rows.flatMap(r=>r.stages), allMats=rows.flatMap(r=>r.mats);
  const semRec=allStages.filter(e=>!String(e.CodEquipamento||e.Recurso||e.Equipamento||'').trim()).length;
  const semLote=allMats.filter(m=>!String(m.Lote||m.LotesConsumidos||'').trim()).length;
  const semFator=(data.materiais||[]).filter(m=>String(m.UM||'').toLowerCase()!=='kg'&&!num(m['Fator conversão para kg']||m.FatorConversaoKg)).length;
  const perdas=rows.reduce((s,r)=>s+r.lossKg,0), conv=rows.reduce((s,r)=>s+r.lossMissing,0);
  const arr=[['Recursos não vinculados a etapas',semRec,'roteiro'],['Linhas de materiais sem lote apontado',semLote,'producao'],['Materiais sem fator de conversão para kg',semFator,'materiais'],['Conversões de perdas pendentes',conv,'sustentabilidade']].filter(x=>x[1]>0);
  return `<div class="ind-alerts">${arr.length?arr.map(([t,n,m])=>`<button onclick="render('${m}')"><b>${n}</b><span>${htmlEscape(t)}</span><em>ver</em></button>`).join(''):'<div class="ok-panel">✓ Sem pendências críticas nos registros filtrados.</div>'}<div class="ind-loss"><span>Massa perdida apontada</span><b>${v397N(perdas,4)} kg</b></div></div>`;
}
function dashboard(){
  $('title').textContent='Dashboard Industrial MES LION';$('subtitle').textContent='Cockpit integrado de produção, custos, rastreabilidade e sustentabilidade.';
  const rows=v397DashboardRows(), roots=rows.map(r=>r.op);
  $('content').innerHTML=`<div class="industrial-dashboard-v397">
    <section class="ind-hero"><div><span class="eyebrow">MES LION · COCKPIT INDUSTRIAL</span><h2>Visão integrada da manufatura de células</h2><p>Produção · Engenharia · Custos · Qualidade de dados · ACV · Rastreabilidade</p></div><div class="ind-hero-actions"><button onclick="render('op')">Ordens de Produção</button><button onclick="render('custos')">Custos</button><button onclick="render('sustentabilidade')">ACV / CO₂eq</button></div></section>
    <section class="ind-filterbar"><label>OP PA<select id="dash397_op" onchange="updateMainDashboard()">${v397FilterOptions(rows.map(r=>r.root),'Todas as OPs')}</select></label><label>Projeto<select id="dash397_proj" onchange="updateMainDashboard()">${v397FilterOptions(roots.map(v397ProjectOfOP),'Todos os projetos / vínculos')}</select></label><label>Química<select id="dash397_quim" onchange="updateMainDashboard()">${v397FilterOptions(roots.map(v397ChemOfOP),'Todas as químicas')}</select></label><button onclick="document.getElementById('dash397_op').value='';document.getElementById('dash397_proj').value='';document.getElementById('dash397_quim').value='';updateMainDashboard()">Limpar filtros</button></section>
    <section id="dash397_metrics" class="ind-metrics"></section>
    <section class="ind-grid top"><article class="ind-panel span2"><header><b>Kanban de produção</b><span>Famílias de OP por situação</span></header><div id="dash397_kanban"></div></article><article class="ind-panel"><header><b>Composição de custos</b><span>PA + OPs filhas</span></header><div id="dash397_cost"></div></article></section>
    <section class="ind-grid"><article class="ind-panel span2"><header><b>Saúde do fluxo industrial</b><span>Etapas cadastradas e avanço</span></header><div id="dash397_process"></div></article><article class="ind-panel"><header><b>Rastreabilidade e dados</b><span>Pendências que afetam auditoria</span></header><div id="dash397_alerts"></div></article></section>
    <section class="ind-panel"><header><b>Indicadores por OP</b><span>Custos e emissões consolidados da família</span></header><div id="dash397_table"></div></section>
  </div>`;
  updateMainDashboard();
}
function updateMainDashboard(){
  const rows=v397FilteredRows();
  const open=rows.filter(r=>!isStatusFinal(r.op.Status)).length,done=rows.filter(r=>isConcluido(r.op.Status)).length;
  const stages=rows.flatMap(r=>r.stages), avgProg=rows.length?rows.reduce((s,r)=>s+r.pct,0)/rows.length:0;
  const totalCost=rows.reduce((s,r)=>s+num(r.c.CustoTotal),0), energy=rows.reduce((s,r)=>s+num(r.s.EnergiaKWh||r.s.EnergiaTotal),0), co2=rows.reduce((s,r)=>s+num(r.s.CO2eqTotal),0), loss=rows.reduce((s,r)=>s+r.lossKg,0);
  const trace=rows.reduce((s,r)=>s+r.mats.length,0)?rows.reduce((s,r)=>s+r.tracePct*r.mats.length,0)/rows.reduce((s,r)=>s+r.mats.length,0):0;
  $('dash397_metrics').innerHTML=[v397Metric('Famílias em produção',String(open),'OPs','PA com família ativa','blue'),v397Metric('Avanço médio',v397N(avgProg,1),'%','etapas concluídas','green'),v397Metric('Custo consolidado',v397Money(totalCost),'','materiais + energia + MOD + perdas','money'),v397Metric('Energia de processo',v397N(energy,2),'kWh','famílias filtradas','energy'),v397Metric('Emissões consolidadas',v397N(co2,4),'kg CO₂eq','inclui materiais, perdas e energia','co2'),v397Metric('Rastreabilidade por lote',v397N(trace,1),'%','linhas de materiais com lote','trace'),v397Metric('Massa perdida',v397N(loss,4),'kg','perdas apontadas','loss'),v397Metric('Famílias concluídas',String(done),'OPs','produto final encerrado','done')].join('');
  $('dash397_kanban').innerHTML=v397Kanban(rows);$('dash397_cost').innerHTML=v397CostMix(rows);$('dash397_process').innerHTML=v397ProcessHealth(rows);$('dash397_alerts').innerHTML=v397Alerts(rows);$('dash397_table').innerHTML=v397OpsTable(rows);
}
