/* =========================================================
   MES LION V40.1 — LIGHT DASH + PASSAPORTE CLIENTE SEM CUSTOS
   - preserva o banco do usuário
   - rastreia lotes/fornecedores pela família completa PA + PIs
   - versão cliente web/PDF nunca exibe custos
   ========================================================= */
const APP_PATCH_V401='v40.1-light-dashboard-passaporte-lotes-sem-custos-cliente';

function bpFamilyCodesV401(bp){
  const op=opPorCodigo(bp?.CodOrdemProducao||'')||{};
  const root=rootOPV395(op)||bp?.CodOrdemProducao||'';
  const fam=opFamilyV33(root)||[];
  return fam.length?fam.map(x=>x.CodOP):[root].filter(Boolean);
}
function splitLotesV401(v){
  return [...new Set(String(v||'').split(/[;,|]+/).map(x=>x.trim()).filter(Boolean))];
}
function entradaMaterialLoteV401(cod,lote,entradaId){
  const ents=(data.entradas||[]).filter(e=>String(e['CódigoMaterial']||e.CodigoMaterial||'')===String(cod||''));
  if(entradaId){const hit=ents.find(e=>String(e.Entrada||'')===String(entradaId));if(hit)return hit;}
  if(lote){const hit=ents.find(e=>String(e.Lote||'').trim()===String(lote).trim());if(hit)return hit;}
  return ents[ents.length-1]||{};
}
function bpPublicMaterialRowsV401(bp){
  const codes=bpFamilyCodesV401(bp);
  const mats=(data.op_materiais||[]).filter(m=>codes.includes(m.CodOP)&&!String(m.TipoConsumo||'').toLowerCase().includes('pi intermedi'));
  const rows=[];
  mats.forEach(m=>{
    let lotes=splitLotesV401(m.LotesConsumidos||m.LoteConsumido||m.Lote||m.CodigoLote||'');
    if(!lotes.length && m.EntradaMaterial){const e=entradaMaterialLoteV401(m.CodigoMaterial,'',m.EntradaMaterial);if(e.Lote)lotes=[e.Lote];}
    if(!lotes.length)lotes=[''];
    lotes.forEach(lote=>{
      const e=entradaMaterialLoteV401(m.CodigoMaterial,lote,m.EntradaMaterial);
      rows.push({
        OP:m.CodOP||'',Etapa:m.OrdemEtapa||m.Ordem||'',Processo:m.Processo||'',
        CodigoMaterial:m.CodigoMaterial||'',Material:m.DescricaoMaterial||materialPorCodigo(m.CodigoMaterial)?.DescricaoMateriais||'',
        Quantidade:fmtMax4V395(m.QtdConsumida||m.ConsumoReal||m.QtdReal||m.QtdPlanejada||m.QtdBase||''),UM:m.UM||'',
        Lote:lote||e.Lote||'',Entrada:e.Entrada||m.EntradaMaterial||'',Fornecedor:e.NomeFornecedor||e.RazaoSocial||m.Fornecedor||'',
        CNPJFornecedor:e.CNPJFornecedor||'',NotaFiscal:e['N° NF']||e.NF||''
      });
    });
  });
  return rows;
}
