/* =========================================================
   MES LION V40.1.4 — recursos únicos por etapa + custos reais por lote
   Corrige duplicação de equipamentos/energia e prioriza custos dos lotes
   efetivamente apontados, sem alterar a estrutura do roteiro.
   ========================================================= */
const APP_PATCH_V4014='v40.1.4-recursos-unicos-custos-lote';

function opStagesUniqueV4014(cod){
  const op=opPorCodigo(cod)||{};
  const raw=(data.op_etapas||[]).filter(e=>String(e.CodOP||'')===String(cod||''));
  const rr=(data.roteiro_recursos||[]).filter(r=>String(r.CodRoteiro||'')===String(op.CodRoteiro||''));
  const routeKeys=new Set(rr.map(r=>String(r.IdRecursoRoteiro||'')||[r.OrdemEtapa||r.Ordem||'',r.CodEquipamento||'',r.Processo||'',r.SubProcesso||''].join('|')));
  const seen=new Set(),out=[];
  raw.forEach(e=>{
    const key=String(e.IdRecursoRoteiro||'')||[e.Ordem||e.OrdemEtapa||'',e.CodEquipamento||'',e.Processo||'',e.SubProcesso||''].join('|');
    if(seen.has(key))return;
    // Quando existe estrutura de recursos no roteiro, somente aceita recursos pertencentes a ela.
    if(rr.length){
      const ok=routeKeys.has(key) || rr.some(r=>
        String(r.OrdemEtapa||r.Ordem||'')===String(e.Ordem||e.OrdemEtapa||'') &&
        String(r.CodEquipamento||'')===String(e.CodEquipamento||'')
      );
      if(!ok)return;
    }
    seen.add(key);out.push(e);
  });
  // Compatibilidade com OPs antigas que não possuem op_etapas copiada: usa cada recurso do roteiro uma única vez.
  if(!out.length && rr.length){
    rr.forEach(r=>{
      const key=String(r.IdRecursoRoteiro||'')||[r.OrdemEtapa||r.Ordem||'',r.CodEquipamento||'',r.Processo||'',r.SubProcesso||''].join('|');
      if(seen.has(key))return;seen.add(key);
      out.push({CodOP:cod,Ordem:r.OrdemEtapa||r.Ordem||'',Processo:r.Processo||'',SubProcesso:r.SubProcesso||'',CodEquipamento:r.CodEquipamento||'',Equipamento:r.Equipamento||'',TempoOperacaoMin:r.TempoOperacaoMin||'',NPessoas:r.NPessoas||'',PotenciaW:r.PotenciaEquipamento||'',IdRecursoRoteiro:r.IdRecursoRoteiro||''});
    });
  }
  return out;
}
opStages=opStagesUniqueV4014;

function roteiroRecursoDaEtapaV4014(op,e){
  const rr=(data.roteiro_recursos||[]).filter(r=>String(r.CodRoteiro||'')===String(op.CodRoteiro||''));
  return rr.find(r=>String(r.IdRecursoRoteiro||'')&&String(r.IdRecursoRoteiro)===String(e.IdRecursoRoteiro||'')) ||
         rr.find(r=>String(r.OrdemEtapa||r.Ordem||'')===String(e.Ordem||e.OrdemEtapa||'')&&String(r.CodEquipamento||'')===String(e.CodEquipamento||'')) || {};
}
function entradaDoConsumoV4014(c){
  return (data.entradas||[]).find(e=>String(e.Entrada||'')===String(c.Entrada||'')&&String(e['CódigoMaterial']||'')===String(c.CodigoMaterial||'')) ||
         (data.entradas||[]).find(e=>String(e['CódigoMaterial']||'')===String(c.CodigoMaterial||'')&&String(e.Lote||'')===String(c.Lote||'')) || {};
}
function custoUnitarioConsumoV4014(c){
  const ent=entradaDoConsumoV4014(c);
  return num(c.CustoUnitarioLote)||num(c.CustoUnitario)||custoEntradaNormalizadoV3822(ent,c.CodigoMaterial)||materialUnitCostV3822(c.CodigoMaterial);
}
function custoPerdaPorLoteV4014(p){
  const cod=p.CodigoMaterial||p.ItemPerdaCodigo||'';
  const lote=p.Lote||p.LoteMaterial||p.LoteConsumido||'';
  const ent=(data.entradas||[]).find(e=>String(e['CódigoMaterial']||'')===String(cod)&&String(e.Lote||'')===String(lote))||{};
  return (ent.Entrada||ent.Lote)?custoEntradaNormalizadoV3822(ent,cod):materialUnitCostV3822(cod);
}

function opEnergyKWhV4014(cod){
  const op=opPorCodigo(cod)||{};
  return opStagesUniqueV4014(cod).reduce((sum,e)=>{
    const rr=roteiroRecursoDaEtapaV4014(op,e);
    const cad=(data.recursos||[]).find(x=>String(x.CodEquipamento||'')===String(e.CodEquipamento||rr.CodEquipamento||''))||{};
    const potW=num(e.PotenciaW)||num(e.PotenciaEquipamento)||num(rr.PotenciaEquipamento)||num(cad['PotenciaEquipamento (W)']);
    const min=num(e.TempoReal)||num(e.TempoOperacaoMin)||num(e.TempoPlanejado)||num(rr.TempoOperacaoMin)||num(cad['TempoOperação (min)']);
    return sum+(potW/1000)*(min/60);
  },0);
}
opEnergyKWh=opEnergyKWhV4014;

function opMODCostV4014(cod,fatorMOD){
  const op=opPorCodigo(cod)||{}, taxaBase=fatorMOD?num(fatorMOD.CustoUnitario):0;
  return opStagesUniqueV4014(cod).reduce((sum,e)=>{
    const rr=roteiroRecursoDaEtapaV4014(op,e);
    const cad=(data.recursos||[]).find(x=>String(x.CodEquipamento||'')===String(e.CodEquipamento||rr.CodEquipamento||''))||{};
    const min=num(e.TempoReal)||num(e.TempoOperacaoMin)||num(e.TempoPlanejado)||num(rr.TempoOperacaoMin)||num(cad['TempoOperação (min)']);
    const pessoas=num(e.NPessoas)||num(e.PessoasPlanejado)||num(rr.NPessoas)||num(cad.NPessoas)||1;
    const taxa=taxaBase||num(cad['TaxaMOD (R$/h)'])||num(((data.custos_fatores||[]).find(f=>f.Tipo==='Mão de obra')||{}).CustoUnitario)||5;
    return sum+(min/60)*pessoas*taxa;
  },0);
}
opMODCostV33=opMODCostV4014;

function auditCostFamilyV4014(codMae){
  const fam=typeof opFamilyV33==='function'?opFamilyV33(codMae):[(opPorCodigo(codMae)||{})].filter(Boolean);
  const fEnergia=typeof selectedCustoFactorV33==='function'?selectedCustoFactorV33($('c_energy_factor')?.value||'','Energia'):null;
  const fMOD=typeof selectedCustoFactorV33==='function'?selectedCustoFactorV33($('c_mod_factor')?.value||'','Mão de obra'):null;
  const taxaEnergia=fEnergia?num(fEnergia.CustoUnitario):(num(((data.custos_fatores||[]).find(f=>f.Tipo==='Energia')||{}).CustoUnitario)||0.82);
  const taxaMODPadrao=fMOD?num(fMOD.CustoUnitario):(num(((data.custos_fatores||[]).find(f=>f.Tipo==='Mão de obra')||{}).CustoUnitario)||5);
  const materiais=[],etapas=[],perdas=[];let matTotal=0,energiaTotal=0,modTotal=0,perdasTotal=0;

  fam.forEach(op=>{
    const cod=op.CodOP;
    const consumos=(data.consumos_materiais||[]).filter(c=>String(c.CodOP||'')===String(cod));
    const matsOP=(data.op_materiais||[]).filter(m=>String(m.CodOP||'')===String(cod)&&!String(m.TipoConsumo||'').toLowerCase().includes('pi intermedi'));
    const codsComConsumo=new Set(consumos.map(c=>String(c.CodigoMaterial||'')));

    // Custos efetivos: cada apontamento usa exatamente o lote/entrada selecionado.
    consumos.forEach(c=>{
      const q=num(c.ConsumoLiquido)||Math.max(0,num(c.QtdRetirada)-num(c.QtdDevolvida));
      const unit=custoUnitarioConsumoV4014(c),total=num(c.CustoEfetivo)||q*unit,ent=entradaDoConsumoV4014(c);
      matTotal+=total;
      materiais.push({OP:cod,Etapa:c.OrdemEtapa||c.Ordem||'',CodigoMaterial:c.CodigoMaterial||'',Material:c.DescricaoMaterial||materialPorCodigo(c.CodigoMaterial).DescricaoMateriais||'',Quantidade:q,UM:c.UM||materialPorCodigo(c.CodigoMaterial).UM||'',Lote:c.Lote||ent.Lote||'',Entrada:c.Entrada||ent.Entrada||'',Fornecedor:ent.NomeFornecedor||ent.RazaoSocial||'',CustoUnitario:unit,'Cálculo aberto':`${q} × ${unit} = ${total}`,Resultado:total,'Origem custo':'Lote/entrada efetivamente apontado'});
    });
    // Materiais ainda sem apontamento mantêm custo projetado pela média ponderada, sem duplicar os já consumidos.
    const seenPlan=new Set();
    matsOP.forEach(m=>{
      if(codsComConsumo.has(String(m.CodigoMaterial||'')))return;
      const key=[m.CodigoMaterial||'',m.OrdemEtapa||m.Ordem||'',m.IdRecursoRoteiro||''].join('|');if(seenPlan.has(key))return;seenPlan.add(key);
      const q=num(m.QtdPlanejada)||num(m.QtdBase)||num(m.Qtd),media=custoMedioPonderadoMaterialV3822(m.CodigoMaterial),unit=media.valor,total=q*unit;matTotal+=total;
      materiais.push({OP:cod,Etapa:m.OrdemEtapa||m.Ordem||'',CodigoMaterial:m.CodigoMaterial||'',Material:m.DescricaoMaterial||materialPorCodigo(m.CodigoMaterial).DescricaoMateriais||'',Quantidade:q,UM:m.UM||materialPorCodigo(m.CodigoMaterial).UM||'',Lote:'',Entrada:'',Fornecedor:'',CustoUnitario:unit,'Cálculo aberto':`${q} × ${unit} = ${total}`,Resultado:total,'Origem custo':'Projetado — média ponderada das entradas (sem consumo apontado)'});
    });

    // Energia e MOD: cada recurso da estrutura do roteiro é considerado UMA única vez por OP/etapa.
    opStagesUniqueV4014(cod).forEach(e=>{
      const rr=roteiroRecursoDaEtapaV4014(op,e);
      const cad=(data.recursos||[]).find(x=>String(x.CodEquipamento||'')===String(e.CodEquipamento||rr.CodEquipamento||''))||{};
      const min=num(e.TempoReal)||num(e.TempoOperacaoMin)||num(e.TempoPlanejado)||num(rr.TempoOperacaoMin)||num(cad['TempoOperação (min)']);
      const pessoas=num(e.NPessoas)||num(e.PessoasPlanejado)||num(rr.NPessoas)||num(cad.NPessoas)||1;
      const potW=num(e.PotenciaW)||num(e.PotenciaEquipamento)||num(rr.PotenciaEquipamento)||num(cad['PotenciaEquipamento (W)']);
      const kwh=(potW/1000)*(min/60),ce=kwh*taxaEnergia,tm=num(cad['TaxaMOD (R$/h)'])||taxaMODPadrao,cm=(min/60)*pessoas*tm;
      energiaTotal+=ce;modTotal+=cm;
      etapas.push({OP:cod,Ordem:e.Ordem||e.OrdemEtapa||'',Processo:e.Processo||rr.Processo||'',Equipamento:e.Equipamento||rr.Equipamento||cad.Equipamento||'',IdRecursoRoteiro:e.IdRecursoRoteiro||rr.IdRecursoRoteiro||'',TempoMin:min,Pessoas:pessoas,PotenciaW:potW,EnergiaKWh:kwh,TaxaEnergia_R_kWh:taxaEnergia,CustoEnergia:ce,TaxaMOD_R_h:tm,CustoMOD:cm,'Cálculo energia':`${potW}/1000 × ${min}/60 × ${taxaEnergia} = ${ce}`,'Cálculo MOD':`${min}/60 × ${pessoas} × ${tm} = ${cm}`});
    });

    (data.perdas||[]).filter(p=>String(p.CodOP||p.NOPP||'')===String(cod)).forEach(p=>{
      const q=num(p.QuantidadePerdida),codMat=p.CodigoMaterial||p.ItemPerdaCodigo||'',unit=String(p.PerdaAlvoTipo||'').toUpperCase()==='MATERIAL'?custoPerdaPorLoteV4014(p):0,tot=q*unit;perdasTotal+=tot;
      perdas.push({OP:cod,Tipo:p.PerdaAlvoTipo||'',Item:codMat||p.ItemPerda||'',Lote:p.Lote||p.LoteMaterial||'',QuantidadePerdida:q,UM:p.Unidade||p.UM||'',CustoUnitario:unit,'Cálculo aberto':`${q} × ${unit} = ${tot}`,Resultado:tot});
    });
  });

  const total=matTotal+energiaTotal+modTotal+perdasTotal;
  return {resumo:[{OPMae:codMae,OPsIncluidas:fam.map(o=>o.CodOP).join('; '),CustoMateriais:matTotal,CustoEnergia:energiaTotal,CustoMOD:modTotal,CustoPerdas:perdasTotal,CustoTotal:total,'Regra total':'Materiais por lote/apontamento + energia dos recursos únicos do roteiro + MOD + perdas'}],materiais,etapas,perdas,regras:[
    {'Ordem':1,'Campo calculado':'Material efetivo','Regra/Fórmula':'Consumo líquido apontado × custo unitário do lote/entrada efetivamente utilizado'},
    {'Ordem':2,'Campo calculado':'Material sem apontamento','Regra/Fórmula':'Quantidade planejada × média ponderada das entradas compatíveis'},
    {'Ordem':3,'Campo calculado':'Energia','Regra/Fórmula':'Cada recurso único do roteiro é contado uma vez: (Potência W ÷ 1000) × (tempo real ou planejado min ÷ 60) × tarifa R$/kWh'},
    {'Ordem':4,'Campo calculado':'Mão de obra','Regra/Fórmula':'Para cada recurso único do roteiro: (tempo min ÷ 60) × pessoas × taxa R$/h'},
    {'Ordem':5,'Campo calculado':'Perda de material','Regra/Fórmula':'Quantidade perdida × custo do lote indicado; na ausência de lote, média ponderada'},
    {'Ordem':6,'Campo calculado':'Total','Regra/Fórmula':'Materiais + Energia + MOD + Perdas'}
  ]};
}
auditCostFamilyV3822=auditCostFamilyV4014;
auditCostFamilyV3819=auditCostFamilyV4014;

// Mantém o consolidado da família sincronizado com a auditoria corrigida.
calcCustoFamiliaOPV33=function(codMae,persist=true,opts={}){
  const a=auditCostFamilyV4014(codMae),r0=a.resumo[0]||{},mae=opPorCodigo(codMae)||{},produz=num(mae.QtdProduzida)||num(mae.QtdPlanejada)||1;
  const energiaKWh=(a.etapas||[]).reduce((s,e)=>s+num(e.EnergiaKWh),0);
  const row={CodOP:codMae,CodOPMae:codMae,ProdutoPA:mae.CodigoProduto||mae.Produto||'',DescricaoProduto:mae.DescricaoProduto||'',DataCalculo:new Date().toLocaleString('pt-BR'),OPsRelacionadas:r0.OPsIncluidas||'',CustoMateriais:String(r0.CustoMateriais||0),CustoEnergia:String(r0.CustoEnergia||0),CustoMOD:String(r0.CustoMOD||0),CustoPerdas:String(r0.CustoPerdas||0),CustoTotal:String(r0.CustoTotal||0),CustoUnitario:String(produz?num(r0.CustoTotal)/produz:0),EnergiaKWh:String(energiaKWh),TaxaMODBase:String(((data.custos_fatores||[]).find(f=>f.Tipo==='Mão de obra')||{}).CustoUnitario||''),TaxaEnergiaBase:String(((data.custos_fatores||[]).find(f=>f.Tipo==='Energia')||{}).CustoUnitario||''),Observacoes:'V40.1.4: família PA + PIs; recursos únicos conforme roteiro; custos efetivos pelos lotes apontados.'};
  if(persist){data.custos_op=data.custos_op||[];const i=data.custos_op.findIndex(x=>(x.CodOPMae||x.CodOP)===codMae);if(i>=0)data.custos_op[i]=row;else data.custos_op.unshift(row);saveLocal();}
  return row;
};

