/* ============================================================
   MES LION V40.2 — Dashboard MRP operacional fidedigno
   - Sem KPIs inventados: todos os valores derivam dos módulos.
   - Calendário usa data programada quando existir; senão DataOP/DataCriacao,
     com indicação explícita de fallback.
   - Custos/energia/CO2eq são recalculados em memória pelas regras vigentes.
   ============================================================ */
const APP_PATCH_V402='v40.2-dashboard-mrp-fidedigno-banco-preservado';
let v402WeekOffset=0;
let v402SelectedDay='';

function v402Date(v){
  if(!v)return null;
  const s=String(v).trim();
  let m=s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if(m)return new Date(+m[3],+m[2]-1,+m[1]);
  const d=new Date(s);return isNaN(d)?null:d;
}
function v402ISO(d){if(!d||isNaN(d))return '';return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function v402FmtDate(d){return d?d.toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'}):'-';}
function v402Monday(base){const d=new Date(base.getFullYear(),base.getMonth(),base.getDate());const day=d.getDay()||7;d.setDate(d.getDate()-day+1);return d;}
function v402AddDays(d,n){const x=new Date(d);x.setDate(x.getDate()+n);return x;}
function v402ScheduleInfo(op){
  const plannedFields=['DataPlanejadaInicio','DataProgramada','DataInicioPlanejada','DataProgramacao','DataPrevista'];
  for(const k of plannedFields){if(op&&op[k]){const d=v402Date(op[k]);if(d)return {date:d,source:k,planned:true};}}
  const d=v402Date(op?.DataOP||op?.DataCriacao);
  return {date:d,source:op?.DataOP?'DataOP':'DataCriacao',planned:false};
}
function v402RootRows(){
  try{return v397DashboardRows();}catch(e){return [];}
}
function v402Project(op){try{return v397ProjectOfOP(op)||'';}catch(e){return '';}}
function v402Chem(op){try{return v397ChemOfOP(op)||'';}catch(e){return '';}}
function v402RootFamiliesFiltered(){
  const opf=$('v402_op')?.value||'', pf=$('v402_proj')?.value||'', cf=$('v402_chem')?.value||'', sf=$('v402_status')?.value||'', q=String($('v402_q')?.value||'').trim().toLowerCase();
  return v402RootRows().filter(r=>{
    const text=[r.root,r.op.CodigoProduto,r.op.DescricaoProduto,r.op.Status,v402Project(r.op),v402Chem(r.op)].join(' ').toLowerCase();
    return (!opf||r.root===opf)&&(!pf||v402Project(r.op)===pf)&&(!cf||v402Chem(r.op)===cf)&&(!sf||v40StatusClass(r.op.Status)===sf)&&(!q||text.includes(q));
  });
}
function v402CurrentWeek(){
  const all=v402RootRows().map(r=>v402ScheduleInfo(r.op).date).filter(Boolean).sort((a,b)=>a-b);
  const seed=all.length?all[all.length-1]:new Date();
  return v402AddDays(v402Monday(seed),v402WeekOffset*7);
}
function v402SetWeek(delta){v402WeekOffset+=delta;v402UpdateDashboard();}
function v402GoToday(){v402WeekOffset=0;v402SelectedDay='';v402UpdateDashboard();}
function v402SelectDay(iso){v402SelectedDay=iso;v402UpdateAgenda();}
function v402StatusLabel(s){const c=v40StatusClass(s);return c==='done'?'Concluída':c==='run'?'Em produção / reaberta':c==='alert'?'Atenção / bloqueada':'Planejada';}
function v402Kpi(icon,label,value,sub,cls=''){return `<article class="v402-kpi ${cls}"><i>${icon}</i><div><span>${htmlEscape(label)}</span><strong>${value}</strong><small>${htmlEscape(sub||'')}</small></div></article>`;}
function v402FamilyProgress(r){return Math.max(0,Math.min(100,num(r.pct)));}
function v402PlanBoard(rows){
  const monday=v402CurrentWeek(), days=Array.from({length:7},(_,i)=>v402AddDays(monday,i));
  const hasTruePlanning=rows.some(r=>v402ScheduleInfo(r.op).planned);
  const heads=['SEG','TER','QUA','QUI','SEX','SÁB','DOM'];
  const cols=days.map((d,i)=>{
    const iso=v402ISO(d), rr=rows.filter(r=>v402ISO(v402ScheduleInfo(r.op).date)===iso);
    const cards=rr.map(r=>{const info=v402ScheduleInfo(r.op),p=v402FamilyProgress(r),st=v40StatusClass(r.op.Status);return `<button class="v402-plan-card ${st}" onclick="render('op')"><header><b>${htmlEscape(r.root)}</b><em>${htmlEscape(v402StatusLabel(r.op.Status))}</em></header><strong>${htmlEscape(r.op.DescricaoProduto||r.op.CodigoProduto||'Produto')}</strong><div class="v402-cardmeta"><span>${htmlEscape(v402Project(r.op)||'Projeto não informado')}</span><span>${htmlEscape(v402Chem(r.op)||'Química não informada')}</span></div><div class="v402-progress"><i style="width:${p}%"></i></div><footer><span>${p}% das etapas</span><span>${info.planned?'Programada':'Data OP'}</span></footer></button>`}).join('');
    return `<section class="v402-day ${v402SelectedDay===iso?'selected':''}"><button class="v402-dayhead" onclick="v402SelectDay('${iso}')"><b>${heads[i]}</b><span>${v402FmtDate(d)}</span><em>${rr.length}</em></button><div>${cards||'<p class="v402-empty">Sem OP registrada.</p>'}</div></section>`;
  }).join('');
  const end=v402AddDays(monday,6);
  return `<div class="v402-plan-toolbar"><div><b>Plano de produção por calendário</b><span>${v402FmtDate(monday)} a ${v402FmtDate(end)}</span></div><div><button onclick="v402SetWeek(-1)">‹</button><button onclick="v402GoToday()">Semana dos dados</button><button onclick="v402SetWeek(1)">›</button></div></div>${!hasTruePlanning?'<div class="v402-data-note">Não há campo de data programada preenchido nas OPs filtradas. Para não inventar informação, o calendário está posicionando as famílias pela <b>DataOP/DataCriacao</b>.</div>':''}<div class="v402-week">${cols}</div>`;
}
function v402FamilyOps(root){try{return opFamilyV33(root)||[];}catch(e){return (data.op||[]).filter(o=>o.CodOP===root||o.OP_Pai===root||o.OP_Base===root);}}
function v402ResourceLoad(rows){
  const roots=new Set(rows.map(r=>r.root)), opCodes=new Set(); rows.forEach(r=>v402FamilyOps(r.root).forEach(o=>opCodes.add(o.CodOP)));
  const seen=new Set(), sums={};
  (data.op_etapas||[]).forEach(e=>{
    if(!opCodes.has(e.CodOP))return;
    const key=[e.CodOP,e.Ordem||e.OrdemEtapa,e.IdRecursoRoteiro||e.CodEquipamento||e.Equipamento].join('|'); if(seen.has(key))return; seen.add(key);
    const name=String(e.Equipamento||e.Recurso||'Recurso não informado').trim(); const h=(num(e.TempoReal)||num(e.TempoOperacaoMin)||num(e.TempoPlanejado))/60;
    sums[name]=(sums[name]||0)+h;
  });
  const arr=Object.entries(sums).sort((a,b)=>b[1]-a[1]).slice(0,8),max=Math.max(1,...arr.map(x=>x[1]));
  return `<div class="v402-resource-bars">${arr.map(([n,h])=>`<div><label><span>${htmlEscape(n)}</span><b>${v397N(h,2)} h</b></label><div><i style="width:${h/max*100}%"></i></div></div>`).join('')||'<p class="muted">Nenhum recurso associado às OPs filtradas.</p>'}</div>`;
}
function v402RealAlerts(rows){
  const opCodes=new Set();rows.forEach(r=>v402FamilyOps(r.root).forEach(o=>opCodes.add(o.CodOP)));
  const planned=rows.filter(r=>v40StatusClass(r.op.Status)==='plan').length;
  const missingLots=(data.consumos_materiais||[]).filter(c=>opCodes.has(c.CodOP)&&!String(c.Lote||'').trim()).length;
  const missingFactor=(data.materiais||[]).filter(m=>String(m.UM||'').toLowerCase()!=='kg'&&!num(m['Fator conversão para kg']||m.FatorConversaoKg)).length;
  const losses=(data.perdas||[]).filter(p=>opCodes.has(p.CodOP||p.NOPP)).length;
  const items=[['OPs ainda planejadas',planned,'op'],['Consumos apontados sem lote',missingLots,'op'],['Materiais sem fator para kg',missingFactor,'materiais'],['Apontamentos de perda',losses,'perdas']];
  return `<div class="v402-alerts">${items.map(([t,n,m])=>`<button onclick="render('${m}')" class="${n?'warn':'ok'}"><b>${n}</b><span>${t}</span><em>${n?'verificar':'OK'}</em></button>`).join('')}</div>`;
}
function v402Agenda(rows){
  const iso=v402SelectedDay||v402ISO(v402CurrentWeek());
  const d=v402Date(iso), rr=rows.filter(r=>v402ISO(v402ScheduleInfo(r.op).date)===iso);
  return `<div class="v402-agenda-head"><b>${d?d.toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'2-digit'}):'Dia'}</b><span>${rr.length} família(s)</span></div><div class="v402-agenda-list">${rr.map(r=>`<button onclick="render('op')"><b>${htmlEscape(r.root)}</b><span>${htmlEscape(r.op.DescricaoProduto||r.op.CodigoProduto||'')}</span><em>${htmlEscape(v402StatusLabel(r.op.Status))}</em></button>`).join('')||'<p>Sem OPs registradas nesta data.</p>'}</div>`;
}
function v402UpdateAgenda(){const rows=v402RootFamiliesFiltered();if($('v402_agenda'))$('v402_agenda').innerHTML=v402Agenda(rows);}
function v402CostSummary(rows){
  let mat=0,en=0,mod=0,loss=0,kwh=0,co2=0,lossKg=0;
  rows.forEach(r=>{mat+=num(r.c?.CustoMateriais);en+=num(r.c?.CustoEnergia);mod+=num(r.c?.CustoMOD);loss+=num(r.c?.CustoPerdas);co2+=num(r.s?.CO2eqTotal);kwh+=num(r.s?.EnergiaKWh||r.s?.EnergiaTotal||r.c?.EnergiaKWh);lossKg+=num(r.s?.MassaPerdasMateriaisKg||r.s?.MassaPerdas);});
  return {mat,en,mod,loss,total:mat+en+mod+loss,kwh,co2,lossKg};
}
function v402MonthlyHistory(){
  const roots=v402RootRows();const map={};
  roots.forEach(r=>{const d=v402ScheduleInfo(r.op).date;if(!d)return;const k=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;map[k]=(map[k]||0)+1;});
  const arr=Object.entries(map).sort().slice(-6);if(arr.length<2)return `<div class="v402-insufficient"><b>Histórico insuficiente</b><span>Existem dados de OP em apenas ${arr.length||0} mês(es). O MES não cria pontos fictícios para completar o gráfico.</span></div>`;
  const max=Math.max(...arr.map(x=>x[1]),1);return `<div class="v402-monthchart">${arr.map(([k,v])=>{const [y,m]=k.split('-');return `<div><b>${v}</b><i style="height:${Math.max(8,v/max*100)}%"></i><span>${m}/${y.slice(2)}</span></div>`}).join('')}</div>`;
}
function v402UpdateDashboard(){
  const rows=v402RootFamiliesFiltered(),sum=v402CostSummary(rows),planned=rows.filter(r=>v40StatusClass(r.op.Status)==='plan').length,run=rows.filter(r=>v40StatusClass(r.op.Status)==='run').length,done=rows.filter(r=>v40StatusClass(r.op.Status)==='done').length,alert=rows.filter(r=>v40StatusClass(r.op.Status)==='alert').length;
  const traceLines=[]; rows.forEach(r=>v402FamilyOps(r.root).forEach(o=>(data.consumos_materiais||[]).filter(c=>c.CodOP===o.CodOP).forEach(c=>traceLines.push(c)))); const traced=traceLines.filter(c=>String(c.Lote||'').trim()).length,tracePct=traceLines.length?traced/traceLines.length*100:0;
  $('v402_kpis').innerHTML=[v402Kpi('▦','OPs planejadas',planned,'famílias PA','plan'),v402Kpi('▶','Em produção',run,'famílias PA','run'),v402Kpi('✓','Concluídas',done,'famílias PA','done'),v402Kpi('!','Atenção / bloqueadas',alert,'conforme status cadastrado','alert'),v402Kpi('R$','Custo consolidado',v397Money(sum.total),'materiais + energia + MOD + perdas','money'),v402Kpi('⚡','Energia',v397N(sum.kwh,2)+' kWh','famílias filtradas','energy'),v402Kpi('CO₂','Emissões',v397N(sum.co2,4)+' kg','CO₂eq calculado','co2'),v402Kpi('◎','Rastreabilidade',v397N(tracePct,1)+'%','consumos apontados com lote','trace')].join('');
  $('v402_plan').innerHTML=v402PlanBoard(rows); $('v402_agenda').innerHTML=v402Agenda(rows); $('v402_alerts').innerHTML=v402RealAlerts(rows); $('v402_load').innerHTML=v402ResourceLoad(rows); $('v402_history').innerHTML=v402MonthlyHistory();
  $('v402_econ').innerHTML=`<div class="v402-econ"><div><span>Materiais</span><b>${v397Money(sum.mat)}</b></div><div><span>Energia</span><b>${v397Money(sum.en)}</b></div><div><span>Mão de obra</span><b>${v397Money(sum.mod)}</b></div><div><span>Perdas</span><b>${v397Money(sum.loss)}</b></div><div><span>Massa perdida</span><b>${v397N(sum.lossKg,4)} kg</b></div></div>`;
}
function dashboard(){
  if($('title')) $('title').textContent='Dashboard operacional';
  if($('subtitle')) $('subtitle').textContent='Planejamento visual e indicadores calculados exclusivamente a partir dos módulos do MES LION.';
  const rows=v402RootRows(),roots=rows.map(r=>r.op);
  $('content').innerHTML=`<div class="v402-dashboard">
    <section class="v402-filters"><label>OP PA<select id="v402_op" onchange="v402UpdateDashboard()">${v397FilterOptions(rows.map(r=>r.root),'Todas as OPs')}</select></label><label>Projeto<select id="v402_proj" onchange="v402UpdateDashboard()">${v397FilterOptions(roots.map(v402Project),'Todos os projetos')}</select></label><label>Química<select id="v402_chem" onchange="v402UpdateDashboard()">${v397FilterOptions(roots.map(v402Chem),'Todas as químicas')}</select></label><label>Status<select id="v402_status" onchange="v402UpdateDashboard()"><option value="">Todos</option><option value="plan">Planejada</option><option value="run">Em produção / reaberta</option><option value="alert">Atenção / bloqueada</option><option value="done">Concluída</option></select></label><label class="search">Pesquisa<input id="v402_q" oninput="v402UpdateDashboard()" placeholder="OP, produto, status..."></label></section>
    <section id="v402_kpis" class="v402-kpis"></section>
    <section class="v402-main-grid"><article class="v402-panel v402-plan-panel"><div id="v402_plan"></div></article><aside><article class="v402-panel"><header><b>Agenda da data selecionada</b><span>somente registros existentes</span></header><div id="v402_agenda"></div></article><article class="v402-panel"><header><b>Alertas operacionais</b><span>derivados dos cadastros e apontamentos</span></header><div id="v402_alerts"></div></article></aside></section>
    <section class="v402-lower-grid"><article class="v402-panel"><header><b>Composição econômica</b><span>famílias PA + PIs filtradas</span></header><div id="v402_econ"></div></article><article class="v402-panel"><header><b>Carga planejada por recurso</b><span>horas das etapas únicas do roteiro/OP</span></header><div id="v402_load"></div></article><article class="v402-panel"><header><b>Histórico de OPs</b><span>somente meses existentes no banco</span></header><div id="v402_history"></div></article></section>
    <footer class="v402-footer"><span>MES LION · Dashboard MRP operacional</span><small>Sem dados sintéticos: indicadores, custos, energia, CO₂eq, lotes e status são derivados do banco e dos módulos do sistema.</small></footer>
  </div>`;
  v402UpdateDashboard();
}
try{data.meta=data.meta||{};data.meta.patchV402=APP_PATCH_V402;}catch(e){}

/* =========================================================
   MES LION V40.2.2 — OP COMPACTA + MATERIAIS POR RECURSO
   ========================================================= */
const APP_PATCH_V4022='v40.2.2-op-layout-recurso';
function opMaterialMatchesResourceV4022(m,e){
  const mo=String(m.OrdemEtapa||m.Ordem||''), eo=String(e.OrdemEtapa||e.Ordem||'');
  if(mo && eo && mo!==eo) return false;
  const mid=String(m.IdRecursoRoteiro||''), eid=String(e.IdRecursoRoteiro||'');
  if(mid && eid) return mid===eid;
  const mc=String(m.CodEquipamento||''), ec=String(e.CodEquipamento||'');
  if(mc && ec) return mc===ec;
  const mn=String(m.Equipamento||m.Recurso||'').trim().toLowerCase();
  const en=String(e.Equipamento||e.Recurso||recursoNomeV32(e.CodEquipamento,e.Processo)||'').trim().toLowerCase();
  if(mn && en) return mn===en;
  // Registro legado sem vínculo explícito: só pode aparecer no primeiro recurso da etapa.
  if(!mid && !mc && !mn){
    const siblings=(data.op_etapas||[]).filter(x=>String(x.CodOP||'')===String(e.CodOP||'')&&String(x.OrdemEtapa||x.Ordem||'')===eo)
      .sort((a,b)=>num(a.SequenciaRecurso)-num(b.SequenciaRecurso));
    return siblings[0]===e;
  }
  return false;
}
function opProductionPageV4022(op,first=false){
  const cod=op.CodOP||'';
  const mats=(data.op_materiais||[]).filter(x=>String(x.CodOP||'')===String(cod));
  const ets=(data.op_etapas||[]).filter(x=>String(x.CodOP||'')===String(cod)).sort((a,b)=>num(a.Ordem||a.OrdemEtapa)-num(b.Ordem||b.OrdemEtapa)||num(a.SequenciaRecurso)-num(b.SequenciaRecurso));
  const info=opProductInfo(op), mp=massProjectionV395(op);
  let stages=''; const usados=new Set();
  ets.forEach((e,i)=>{
    const em=mats.filter(m=>opMaterialMatchesResourceV4022(m,e));
    em.forEach(m=>usados.add(m));
    const recurso=e.Recurso||e.Equipamento||recursoNomeV32(e.CodEquipamento,e.Processo)||'-';
    const rows=em.map(m=>{const lot=m.Lote||'',en=entradaLoteMaterialV395(m.CodigoMaterial,lot);return `<tr><td>${htmlEscape(m.CodigoMaterial||'')}</td><td>${htmlEscape(m.DescricaoMaterial||'')}</td><td class="num">${fmtMax4V395(m.QtdPlanejada||m.QtdBase||'')}</td><td>${htmlEscape(m.UM||'')}</td><td>${htmlEscape(lot)}</td><td>${htmlEscape(en.NomeFornecedor||'')}</td><td></td><td></td></tr>`}).join('');
    stages+=`<section class="op-stage op-stage-v4022"><div class="op-stage-head-v4022"><div><span class="stage-no">${String(e.Ordem||e.OrdemEtapa||'')}</span><div><small>ETAPA</small><h2>${htmlEscape(e.Processo||'Processo não informado')}</h2></div></div><div class="stage-resource"><b>${htmlEscape(recurso)}</b><span>${fmtMax4V395(e.TempoReal||e.TempoPlanejado||e.TempoOperacaoMin||'')} min · ${fmtMax4V395(e.PessoasPlanejado||e.NPessoas||'')} pessoa(s)</span></div></div>${rows?`<table class="op-mat-table-v4022"><thead><tr><th>Código</th><th>Material</th><th>Qtd.</th><th>UM</th><th>Lote</th><th>Fornecedor</th><th>Consumo real</th><th>Perda</th></tr></thead><tbody>${rows}</tbody></table>`:`<div class="op-no-mat-v4022">Nenhum material vinculado a este recurso no roteiro.</div>`}<div class="annotation-grid op-annotation-v4022"><div class="blank"><b>Início</b></div><div class="blank"><b>Fim</b></div><div class="blank"><b>Operador</b></div><div class="blank"><b>Quantidade produzida</b></div><div class="blank"><b>Quantidade rejeitada</b></div><div class="blank"><b>Conferência</b></div></div><div class="obs-big op-obs-v4022"><b>Observações da etapa:</b></div></section>`;
  });
  const soltos=mats.filter(m=>!usados.has(m)&&!String(m.TipoConsumo||'').toLowerCase().includes('pi intermedi'));
  const pending=soltos.length?`<section class="op-stage op-warning-v4022"><h2>Materiais sem vínculo de recurso</h2><p>Estes registros existem na OP, mas não possuem vínculo suficiente para serem atribuídos automaticamente a um equipamento. Corrija o roteiro antes de utilizá-los em produção.</p><table><thead><tr><th>Código</th><th>Material</th><th>Qtd.</th><th>UM</th></tr></thead><tbody>${soltos.map(m=>`<tr><td>${htmlEscape(m.CodigoMaterial||'')}</td><td>${htmlEscape(m.DescricaoMaterial||'')}</td><td>${fmtMax4V395(m.QtdPlanejada||m.QtdBase||'')}</td><td>${htmlEscape(m.UM||'')}</td></tr>`).join('')}</tbody></table></section>`:'';
  const all=familyMaterialsV395(op).map(m=>{const lot=m.Lote||'',en=entradaLoteMaterialV395(m.CodigoMaterial,lot);return `<tr><td>${htmlEscape(m.CodOP||'')}</td><td>${htmlEscape(m.CodigoMaterial||'')}</td><td>${htmlEscape(m.DescricaoMaterial||'')}</td><td>${htmlEscape(lot)}</td><td>${htmlEscape(en.NomeFornecedor||'')}</td><td class="num">${fmtMax4V395(m.QtdConsumida||m.QtdPlanejada||m.QtdBase||'')}</td><td>${htmlEscape(m.UM||'')}</td></tr>`}).join('');
  return `<div class="op-card op-card-v4022 ${first?'':'break'}"><div class="op-title-v4022"><div><small>MES LION · ORDEM DE PRODUÇÃO</small><h1>${htmlEscape(cod)}</h1></div><span class="status-v4022">${htmlEscape(op.Status||'')}</span></div><table class="op-head op-head-v4022"><tr><th>Produto</th><td colspan="3">${htmlEscape(info.cod+' — '+info.desc)}</td></tr><tr><th>Roteiro</th><td>${htmlEscape(op.CodRoteiro||'')}</td><th>Quantidade planejada</th><td>${fmtMax4V395(op.QtdPlanejada)} ${htmlEscape(op.UM||'')}</td></tr></table>${stages}${pending}<section class="op-stage op-close-v4022"><h2>Fechamento de massa e rastreabilidade</h2><div class="op-summary-v395 op-summary-v4022"><div><b>Massa projetada / consumida</b><span>${num4V395(mp.total)} kg</span></div><div><b>Massa perdida</b><span>${num4V395(mp.lost)} kg</span></div><div><b>Saldo de massa</b><span>${num4V395(mp.total-mp.lost)} kg</span></div><div><b>Conversões pendentes</b><span>${htmlEscape(mp.missing.join(', ')||'Nenhuma')}</span></div></div><table><thead><tr><th>OP</th><th>Código</th><th>Material</th><th>Lote</th><th>Fornecedor</th><th>Quantidade</th><th>UM</th></tr></thead><tbody>${all||'<tr><td colspan="7">Sem materiais.</td></tr>'}</tbody></table></section><div class="obs-big op-general-v4022"><b>Observações gerais:</b></div><div class="sign"><div class="line">Produção</div><div class="line">Qualidade</div><div class="line">PCP / Engenharia</div></div></div>`;
}
opProductionPage=opProductionPageV4022;
try{data.meta=data.meta||{};data.meta.patchV4022=APP_PATCH_V4022;}catch(e){}

/* =========================================================
   MES LION V40.3 — PI ISOLADO + LOTES DE PI + ABASTECIMENTO PA
   Mantém o fluxo PA completo e acrescenta produção isolada de PI,
   estoque rastreável de lotes PI e consumo proporcional por vários PAs.
   ========================================================= */
const APP_PATCH_V403='v40.3-pi-isolado-lotes-abastecimento-pa';
data.pi_lotes=data.pi_lotes||[];
data.op_pi_consumos=data.op_pi_consumos||[];

function v403Prod(cod){return (data.estrutura||[]).find(p=>String(p['Código']||'')===String(cod||''))||{};}
function v403IsPI(op){const c=op?.CodigoPI||op?.Produto||op?.CodigoProduto||''; const p=v403Prod(c);return String(op?.TipoOP||'').toUpperCase()==='PI'||String(p['Tipo Produto']||'').toUpperCase()==='PI'||String(c).startsWith('PI');}
function v403StatusClosed(op){return typeof isStatusFinal==='function'?isStatusFinal(op.Status):/concl|encerr|final/i.test(String(op.Status||''));}
function v403Produced(op){return Math.max(0,num(op?.QtdProduzida)||num(typeof opProduced==='function'?opProduced(op?.CodOP):0)||num(op?.QtdPlanejada));}
