calcCustoFamiliaOPV33=function(codMae,persist=true,opts={}){const a=auditCostFamilyV4014(codMae),r0=a.resumo[0]||{},mae=opPorCodigo(codMae)||{},produz=num(mae.QtdProduzida)||num(mae.QtdPlanejada)||1,energiaKWh=(a.etapas||[]).reduce((s,e)=>s+num(e.EnergiaKWh),0)+(data.op_pi_consumos||[]).filter(c=>c.CodOPPA===codMae&&String(c.Status||'ATIVO')!=='CANCELADO').reduce((s,c)=>{const l=(data.pi_lotes||[]).find(x=>x.IdLotePI===c.IdLotePI)||{},ss=v403SourceSust(l);return s+(ss.q?ss.energiaKWh*num(c.QuantidadeConsumida)/ss.q:0)},0);const row={CodOP:codMae,CodOPMae:codMae,ProdutoPA:mae.CodigoProduto||mae.Produto||'',DescricaoProduto:mae.DescricaoProduto||'',DataCalculo:new Date().toLocaleString('pt-BR'),OPsRelacionadas:r0.OPsIncluidas||'',CustoMateriais:String(r0.CustoMateriais||0),CustoEnergia:String(r0.CustoEnergia||0),CustoMOD:String(r0.CustoMOD||0),CustoPerdas:String(r0.CustoPerdas||0),CustoTotal:String(r0.CustoTotal||0),CustoUnitario:String(produz?num(r0.CustoTotal)/produz:0),EnergiaKWh:String(energiaKWh),Observacoes:'V40.3: família PA + OPs PI novas + lotes PI herdados proporcionalmente.'};if(persist){data.custos_op=data.custos_op||[];const i=data.custos_op.findIndex(x=>(x.CodOPMae||x.CodOP)===codMae);if(i>=0)data.custos_op[i]=row;else data.custos_op.unshift(row);saveLocal();}return row;};

const calcSustFamiliaOPV403Base=calcSustFamiliaOPV33;
calcSustFamiliaOPV33=function(codMae,persist=true,opts={}){const row=calcSustFamiliaOPV403Base(codMae,false,opts)||{},cons=(data.op_pi_consumos||[]).filter(c=>c.CodOPPA===codMae&&String(c.Status||'ATIVO')!=='CANCELADO');let total=0,mat=0,en=0,loss=0,kwh=0;cons.forEach(c=>{const l=(data.pi_lotes||[]).find(x=>x.IdLotePI===c.IdLotePI)||{},s=v403SourceSust(l),f=s.q?num(c.QuantidadeConsumida)/s.q:0;total+=s.total*f;mat+=s.mat*f;en+=s.en*f;loss+=s.loss*f;kwh+=s.energiaKWh*f;});row.CO2eqTotal=String(num(row.CO2eqTotal)+total);row.CO2eqProduto=String(num(row.CO2eqProduto)+mat);row.CO2eqEnergia=String(num(row.CO2eqEnergia)+en);row.CO2eqPerdas=String(num(row.CO2eqPerdas)+loss);row.EnergiaKWh=String(num(row.EnergiaKWh)+kwh);row.EnergiaTotal=row.EnergiaKWh;row.Observacoes=(row.Observacoes||'')+' V40.3: inclui impacto herdado proporcionalmente dos lotes PI consumidos.';if(persist){data.sust_op=data.sust_op||[];const i=data.sust_op.findIndex(x=>(x.CodOPMae||x.CodOP)===codMae);if(i>=0)data.sust_op[i]=row;else data.sust_op.unshift(row);saveLocal();}return row;};

