function abrirSimulacaoAbastecimentoV403(){const pas=(data.estrutura||[]).filter(p=>String(p['Tipo Produto']||'').toUpperCase()==='PA');if(!pas.length)return alert('Nenhum PA cadastrado.');$('sim_form').innerHTML=`<div class="form"><h3>Simulação de abastecimento por PI</h3><div class="form-grid"><label class="wide"><span>PA</span><select id="v403_sim_pa" onchange="v403RenderSimSources()">${pas.map(p=>`<option value="${htmlEscape(p['Código'])}">${htmlEscape(p['Código']+' — '+(p['Descrição']||''))}</option>`).join('')}</select></label><label><span>Multiplicador</span><input id="v403_sim_mult" type="number" value="1" min="0.0001" step="0.0001" oninput="v403RenderSimSources()"></label></div><div id="v403_sim_sources"></div><div class="form-actions"><button onclick="v403CalcSupplySimulation()">Calcular cenário</button></div></div>`;v403RenderSimSources();}
function v403RenderSimSources(){const cod=$('v403_sim_pa')?.value,r=roteiroSalvoProdutoV387(cod),mult=num($('v403_sim_mult')?.value)||1,box=$('v403_sim_sources');if(!r){box.innerHTML='<div class="warn">Sem roteiro salvo.</div>';return;}box.innerHTML=pisDoPA(cod).map(pi=>{const lots=v403LotesDisponiveis(pi['Código']),req=v403RequiredPIQty(r,pi['Código'],mult);return `<div class="v403-pi-source" data-pi="${pi['Código']}"><div><b>${pi['Código']}</b><span>${htmlEscape(pi['Descrição']||'')}</span></div><select class="v403-action"><option value="PRODUZIR">Produzir novo</option>${lots.map(l=>`<option value="LOT:${l.IdLotePI}">Usar ${htmlEscape(l.IdLotePI)} — saldo ${fmtMax4V395(v403SaldoLote(l))}</option>`).join('')}</select><input class="v403-qtd" type="number" value="${req.q}" step="0.0001"><span>${req.um}</span></div>`}).join('');}
function v403CalcSupplySimulation(){let total=0,det=[];[...document.querySelectorAll('#v403_sim_sources .v403-pi-source')].forEach(row=>{const act=row.querySelector('.v403-action').value,q=num(row.querySelector('.v403-qtd').value),pi=row.dataset.pi;if(act.startsWith('LOT:')){const l=(data.pi_lotes||[]).find(x=>x.IdLotePI===act.slice(4))||{},s=v403SourceCost(l),c=s.q?q*s.total/s.q:0;total+=c;det.push({PI:pi,Origem:l.IdLotePI,Quantidade:q,Custo:c});}else{const r=v403RoteiroPI(pi),mats=(data.roteiro_materiais||[]).filter(m=>m.CodRoteiro===r?.CodRoteiro),base=produtoPlanejadoRoteiroV35(r||{},pi).qtd||1,scale=q/base,c=mats.reduce((sum,m)=>sum+num(m.QtdBase)*scale*materialUnitCostV3822(m.CodigoMaterial),0);total+=c;det.push({PI:pi,Origem:'Nova produção — materiais projetados',Quantidade:q,Custo:c});}});$('sim_result').innerHTML=`<div class="card"><h3>Cenário de abastecimento dos PIs</h3>${tableHTML(det,['PI','Origem','Quantidade','Custo'])}<p><b>Custo dos PIs no cenário: ${money(total)}</b></p><p class="muted">Simulação não reserva lotes e não altera estoque. Custos de nova produção são projeções do roteiro; lotes existentes usam custo herdado da OP original.</p></div>`;}
