/* =========================================================
   MES LION V40.3.1 — OP ESPELHO DO ROTEIRO / PI ISOLADO
   - Corrige geração de OP de PI isolado e PA misto.
   - A OP copia somente as etapas do produto alvo.
   - Recursos vêm de roteiro_recursos, mantendo IdRecursoRoteiro.
   - Materiais vêm somente das etapas/recursos correspondentes.
   - Quantidades-base dos materiais escalam pela quantidade do produto.
   - Nenhum material de outro recurso/etapa é inferido ou duplicado.
   ========================================================= */
const APP_PATCH_V4031='v40.3.1-op-espelho-roteiro-pi-isolado';

function v4031TargetStages(r,target){
  const all=(data.roteiro_etapas||[]).filter(e=>e.CodRoteiro===r.CodRoteiro);
  const t=String(target||'');
  const exact=all.filter(e=>String(e.ProdutoGerado||e.CodigoProduto||e.CodigoPI||'')===t);
  // Roteiro isolado pertence integralmente ao PI: aceita etapas legadas sem CodigoPI preenchido.
  if(exact.length) return exact;
  if(String(r.TipoRoteiro||'').toUpperCase()==='PI_ISOLADO' && String(r.CodigoProduto||r.CodigoPI||'')===t) return all;
  return [];
}
function v4031ResourcesForStage(r,e){
  const rows=(data.roteiro_recursos||[]).filter(x=>x.CodRoteiro===r.CodRoteiro && String(x.OrdemEtapa||x.Ordem||'')===String(e.Ordem||e.OrdemEtapa||''));
  if(rows.length) return rows;
  if(e.CodEquipamento||e.Equipamento||e.Recurso) return [{
    IdRecursoRoteiro:e.IdRecursoRoteiro||'',OrdemEtapa:e.Ordem||e.OrdemEtapa||'',CodEquipamento:e.CodEquipamento||'',
    Equipamento:e.Equipamento||e.Recurso||'',Processo:e.Processo||'',SubProcesso:e.SubProcesso||'',
    TempoOperacaoMin:e.TempoOperacaoMin||e.TempoPlanejado||'',NPessoas:e.NPessoas||e.PessoasPlanejado||'',
    PotenciaEquipamento:e.PotenciaEquipamento||''
  }];
  return [];
}
function v4031MaterialsForTarget(r,target,stages){
  const ordens=new Set(stages.map(e=>String(e.Ordem||e.OrdemEtapa||'')));
  return (data.roteiro_materiais||[]).filter(m=>{
    if(m.CodRoteiro!==r.CodRoteiro) return false;
    const mt=String(m.CodigoPI||m.CodigoProduto||m.ProdutoGerado||'');
    if(mt && mt===String(target||'')) return true;
    return ordens.has(String(m.OrdemEtapa||m.Ordem||''));
  });
}
function v4031RouteProductBase(r,target,stages){
  const e=stages.find(x=>num(x.QtdPlanejadaProduto||x.QtdPlanejada)>0)||stages[0]||{};
  return {q:num(e.QtdPlanejadaProduto||e.QtdPlanejada||0)||1,um:e.UMProduto||e.UM||prodUMV382(target)||unidadeProdutoV35(target)||'un'};
}

criarOPFromRoteiroFiltradoV29=function(r,qtd,codOP,tipoOP,opBase,codigoPIFiltro){
  data.op=data.op||[]; data.op_etapas=data.op_etapas||[]; data.op_materiais=data.op_materiais||[];
  const target=String(codigoPIFiltro || r.CodigoProduto || r.CodigoPI || '');
  const produto=(data.estrutura||[]).find(x=>String(x['Código'])===target)||{};
  const stages=v4031TargetStages(r,target);
  if(!stages.length) throw new Error(`O roteiro ${r.CodRoteiro} não possui etapa vinculada ao produto ${target}.`);
  const baseProd=v4031RouteProductBase(r,target,stages);
  const planned=num(qtd)>0?num(qtd):baseProd.q;
  const fator=baseProd.q>0?planned/baseProd.q:1;
  const tipo=String(tipoOP||produto['Tipo Produto']||'').toUpperCase()==='PI'?'PI':'PA';
  const codigoPA=tipo==='PA'?target:(produto['Código Pai']||r.CodigoPAOrigem||'');
  const o={
    CodOP:codOP,CodRoteiro:r.CodRoteiro,CodigoProduto:target,CodigoPA:codigoPA,CodigoPI:tipo==='PI'?target:'',
    Produto:target,ProdutoGerado:target,Versao:r.Versao||'',IdCelula:r.IdCelula||produto['Célula']||'',
    QtdPlanejada:String(planned),QtdBaseRoteiro:String(baseProd.q),FatorEscalaRoteiro:String(fator),QtdProduzida:'',
    Status:'Planejada',DataCriacao:new Date().toLocaleString('pt-BR'),Usuario:'admin',OP_Pai:tipo==='PI'?(opBase||''):'',
    OP_Base:opBase||codOP,Observacoes:`OP espelho do roteiro ${r.CodRoteiro}. Etapas, recursos e materiais copiados somente do produto ${target}.`,
    UM:baseProd.um,DataOP:new Date().toLocaleDateString('pt-BR'),TipoOP:tipo,OrigemGeracao:tipo==='PI'&&String(r.TipoRoteiro||'').toUpperCase()==='PI_ISOLADO'?'PI_ISOLADO':'WEB',
    DescricaoProduto:produto['Descrição']||r.DescricaoRoteiro||'',RoteiroValidado:'Sim',DataValidacaoRoteiro:r.DataValidacao||'',OrigemDados:'ROTEIRO_ESPELHO'
  };
  data.op.unshift(o);

  stages.forEach(e=>{
    const recs=v4031ResourcesForStage(r,e);
    if(recs.length){
      recs.forEach((rec,ri)=>data.op_etapas.push({
        CodOP:codOP,CodRoteiro:r.CodRoteiro,Ordem:e.Ordem||e.OrdemEtapa||'',CodigoProduto:target,CodigoPI:tipo==='PI'?target:'',
        ProdutoGerado:target,DescricaoProdutoGerado:produto['Descrição']||'',QtdPlanejadaProduto:String(planned),UMProduto:baseProd.um,
        Processo:e.Processo||rec.Processo||'',SubProcesso:rec.SubProcesso||e.SubProcesso||'',IdProcesso:e.IdProcesso||'',
        IdRecursoRoteiro:rec.IdRecursoRoteiro||'',SequenciaRecurso:ri+1,CodEquipamento:rec.CodEquipamento||'',
        Recurso:rec.Equipamento||'',Equipamento:rec.Equipamento||'',TempoPlanejado:rec.TempoOperacaoMin||e.TempoOperacaoMin||'',
        TempoOperacaoMin:rec.TempoOperacaoMin||e.TempoOperacaoMin||'',PessoasPlanejado:rec.NPessoas||e.NPessoas||'',
        NPessoas:rec.NPessoas||e.NPessoas||'',PotenciaEquipamento:rec.PotenciaEquipamento||'',Status:'PENDENTE',Obs:e.Obs||'',OrigemDados:'ROTEIRO_ETAPA_RECURSO_ESPELHO'
      }));
    } else {
      data.op_etapas.push({CodOP:codOP,CodRoteiro:r.CodRoteiro,Ordem:e.Ordem||'',CodigoProduto:target,CodigoPI:tipo==='PI'?target:'',ProdutoGerado:target,
        DescricaoProdutoGerado:produto['Descrição']||'',QtdPlanejadaProduto:String(planned),UMProduto:baseProd.um,Processo:e.Processo||'',IdProcesso:e.IdProcesso||'',
        IdRecursoRoteiro:'',SequenciaRecurso:1,CodEquipamento:'',Recurso:'',Equipamento:'',TempoPlanejado:e.TempoOperacaoMin||'',TempoOperacaoMin:e.TempoOperacaoMin||'',
        PessoasPlanejado:e.NPessoas||'',NPessoas:e.NPessoas||'',PotenciaEquipamento:'',Status:'PENDENTE',Obs:e.Obs||'',OrigemDados:'ROTEIRO_ETAPA_SEM_RECURSO'});
    }
  });

  const mats=v4031MaterialsForTarget(r,target,stages);
  mats.forEach(m=>{
    const mat=materialObjV32(m.CodigoMaterial)||{};
    const qBase=num(m.QtdBase||m.QtdPlanejada||m.Qtd||0);
    const qPlan=qBase*fator;
    const unit=num(m.CustoUnitario)||materialUnitCost(m.CodigoMaterial)||0;
    data.op_materiais.push({
      CodOP:codOP,CodRoteiro:r.CodRoteiro,Ordem:m.OrdemEtapa||m.Ordem||'',OrdemEtapa:m.OrdemEtapa||m.Ordem||'',CodigoProduto:target,CodigoPI:tipo==='PI'?target:'',
      Processo:m.Processo||'',IdRecursoRoteiro:m.IdRecursoRoteiro||'',CodEquipamento:m.CodEquipamento||'',CodigoMaterial:m.CodigoMaterial||'',
      DescricaoMaterial:m.DescricaoMaterial||mat.DescricaoMateriais||'',EntradaMaterial:'',Lote:'',QtdPlanejada:String(qPlan),QtdBase:String(qBase),
      UM:m.UMConsumo||m.UM||mat.UM||'',CustoUnitario:String(unit),CustoTotal:String(unit*qPlan),TipoConsumo:m.TipoConsumo||'Consumo Direto',
      Observacoes:m.Obs||m.Observacoes||'',OrigemDados:'ROTEIRO_RECURSO_MATERIAL_ESPELHO'
    });
  });
  return o;
};

// Associação estrita na impressão/visualização da OP: recurso do roteiro é a chave principal.
materiaisRecursoOPV392=function(materiais,e){
  const ord=String(e.Ordem||e.OrdemEtapa||''),eid=String(e.IdRecursoRoteiro||'');
  return (materiais||[]).filter(m=>{
    if(String(m.OrdemEtapa||m.Ordem||'')!==ord) return false;
    const mid=String(m.IdRecursoRoteiro||'');
    if(eid) return mid===eid;
    if(mid) return false;
    if(e.CodEquipamento && m.CodEquipamento) return String(e.CodEquipamento)===String(m.CodEquipamento);
    return !e.CodEquipamento && !m.CodEquipamento;
  });
};

try{data.meta=data.meta||{};data.meta.patchV4031=APP_PATCH_V4031;saveLocal();}catch(e){console.warn('Patch V40.3.1:',e);}

/* =========================================================
   MES LION V40.3.2 — QUANTIDADE DA OP = BASE DO ROTEIRO × FATOR
   - Nunca substitui a quantidade específica do PA/PI por 1 kg/un.
   - O valor informado ao gerar OP é fator/multiplicador da base do roteiro.
   - Cada PA/PI mantém sua própria QtdPlanejadaProduto e UM do roteiro.
   - Formulação usa a QtdPlanejada final da OP como massa-base.
   - Se a quantidade-base estiver ausente/zerada, bloqueia a geração.
   ========================================================= */
const APP_PATCH_V4032='v40.3.2-quantidade-roteiro-vezes-fator';

function v4032BaseProdutoRoteiro(r,codProduto){
  const stages=v4031TargetStages(r,codProduto);
  if(!stages.length) throw new Error(`O roteiro ${r.CodRoteiro} não possui etapa vinculada ao produto ${codProduto}.`);
  const e=stages.find(x=>num(x.QtdPlanejadaProduto||x.QtdPlanejada)>0);
  if(!e) throw new Error(`O produto ${codProduto} não possui quantidade planejada válida no roteiro ${r.CodRoteiro}. Informe a quantidade na etapa do roteiro antes de gerar a OP.`);
  const q=num(e.QtdPlanejadaProduto||e.QtdPlanejada);
  if(!(q>0)) throw new Error(`Quantidade-base inválida para ${codProduto} no roteiro ${r.CodRoteiro}.`);
  return {q,um:e.UMProduto||e.UM||prodUMV382(codProduto)||unidadeProdutoV35(codProduto)||'',etapa:e,stages};
}

// Elimina qualquer fallback silencioso para 1.
v4031RouteProductBase=function(r,target,stages){
  const useStages=(stages&&stages.length)?stages:v4031TargetStages(r,target);
  const e=useStages.find(x=>num(x.QtdPlanejadaProduto||x.QtdPlanejada)>0);
  if(!e) throw new Error(`O produto ${target} não possui quantidade planejada válida no roteiro ${r.CodRoteiro}.`);
  const q=num(e.QtdPlanejadaProduto||e.QtdPlanejada);
  if(!(q>0)) throw new Error(`Quantidade-base inválida para ${target} no roteiro ${r.CodRoteiro}.`);
  return {q,um:e.UMProduto||e.UM||prodUMV382(target)||unidadeProdutoV35(target)||'un'};
};

// Geração de família: o número informado é um FATOR sobre a quantidade-base de CADA produto.
gerarTodasOPsDoRoteiroValidadoV29=function(r,fatorInformado=1){
  data.op=data.op||[];data.op_etapas=data.op_etapas||[];data.op_materiais=data.op_materiais||[];
  const fator=num(fatorInformado);
  if(!(fator>0)) throw new Error('O fator/quantidade de produção deve ser maior que zero.');
  const base=baseOPCode(),produtos=roteiroProdutosV32(r),criadas=[];
  if(!produtos.length) throw new Error(`O roteiro ${r.CodRoteiro} não possui produtos/etapas para gerar OP.`);
  produtos.forEach((prodCod,idx)=>{
    const b=v4032BaseProdutoRoteiro(r,prodCod);
    const qtdFinal=b.q*fator;
    const prod=v403Prod(prodCod),tipo=String(prod['Tipo Produto']||'').toUpperCase()==='PI'?'PI':'PA';
    const sufixo=tipo==='PA'?'-PA':'-'+pad(idx+1,2);
    const op=criarOPFromRoteiroFiltradoV29(r,qtdFinal,base+sufixo,tipo,base,tipo==='PI'?prodCod:'');
    op.QtdBaseRoteiro=String(b.q);
    op.FatorEscalaRoteiro=String(fator);
    op.QtdPlanejada=String(qtdFinal);
    op.UM=b.um||op.UM;
    op.OrigemQtdPlanejada='ROTEIRO_ETAPA_X_FATOR';
    op.Observacoes=`Quantidade planejada = ${b.q} ${b.um} (base da etapa do roteiro) × ${fator} = ${qtdFinal} ${b.um}.`;
    // Garante que todas as linhas de etapa reflitam a quantidade final do produto.
    (data.op_etapas||[]).filter(e=>e.CodOP===op.CodOP).forEach(e=>{e.QtdPlanejadaProduto=String(qtdFinal);e.UMProduto=b.um||e.UMProduto;});
    criadas.push(op);
  });
  const mae=criadas.find(o=>String(o.TipoOP||'').toUpperCase()==='PA');
  if(mae){
    criadas.filter(o=>String(o.TipoOP||'').toUpperCase()==='PI').forEach(f=>data.op_materiais.push({
      CodOP:mae.CodOP,CodRoteiro:r.CodRoteiro,Ordem:'PI',OrdemEtapa:'PI',CodigoProduto:mae.Produto,CodigoPI:f.Produto,
      Processo:'Integração / genealogia',CodigoMaterial:f.Produto,DescricaoMaterial:f.DescricaoProduto||f.Produto,Lote:'',
      QtdPlanejada:String(f.QtdPlanejada),QtdBase:String(f.QtdBaseRoteiro||f.QtdPlanejada),UM:f.UM||'un',TipoConsumo:'PI intermediário',
      CustoUnitario:'0',CustoTotal:'0',OrigemDados:'ROTEIRO_ETAPA_PI',
      Observacoes:`PI produzido pela OP filha ${f.CodOP}. Quantidade = base específica do roteiro × fator ${f.FatorEscalaRoteiro||fator}.`
    }));
  }
  return criadas;
};

// Formulário genérico: deixa explícito que o valor escala as quantidades do roteiro.
novaOPPorRoteiro=function(){
  const ativos=(data.roteiro||[]).filter(r=>String(r.Ativo||'TRUE').toUpperCase()!=='FALSE' && roteiroEstaSalvoV387(r));
  if(!ativos.length) return alert('Não há roteiros salvos. Salve um roteiro antes de gerar OP.');
  const opts=ativos.map(r=>`<option value="${htmlEscape(r.CodRoteiro||'')}">${htmlEscape((r.CodRoteiro||'')+' | '+(r.CodigoProduto||r.CodigoPI||'')+' | '+(r.DescricaoRoteiro||''))}</option>`).join('');
  $('crudBox').innerHTML=`<div class="form"><h3>Gerar OP por roteiro salvo</h3><div class="form-grid"><label class="wide"><span>Roteiro salvo</span><select id="op_rot_v24">${opts}</select></label><label><span>Fator de produção / nº de bases do roteiro</span><input type="number" id="op_qtd_v24" min="0.000001" step="0.0001" value="1"></label></div><div class="form-actions"><button onclick="confirmarNovaOPPorRoteiro()">Gerar OP</button><button class="secondary" onclick="$('crudBox').innerHTML=''">Cancelar</button></div><p class="muted"><b>1 = exatamente as quantidades cadastradas no roteiro.</b> Ex.: se um PI tem 0,8957 kg no roteiro, fator 1 gera 0,8957 kg; fator 2 gera 1,7914 kg. Materiais, formulação e custos escalam pela mesma base.</p></div>`;
  $('crudBox').scrollIntoView({behavior:'smooth',block:'start'});
};

// PI isolado: não admite base implícita 1; sempre mostra e utiliza a base real do roteiro.
v403AtualizaOPPIInfo=function(){
  const cod=$('v403_op_pi')?.value,r=v403RoteiroPI(cod);if(!r)return;
  let b;try{b=v4032BaseProdutoRoteiro(r,cod);}catch(e){if($('v403_pi_info'))$('v403_pi_info').innerHTML=`<span class="danger-text">${htmlEscape(e.message)}</span>`;return;}
  const mult=num($('v403_pi_mult')?.value);
  const final=(mult>0)?b.q*mult:0;
  if($('v403_pi_info'))$('v403_pi_info').innerHTML=`Quantidade-base do roteiro: <b>${fmtMax4V395(b.q)} ${htmlEscape(b.um)}</b> · Fator: <b>${fmtMax4V395(mult)}</b> · Quantidade planejada da OP: <b>${fmtMax4V395(final)} ${htmlEscape(b.um)}</b>`;
};
confirmarOPPIIsolado=function(){
  const cod=$('v403_op_pi')?.value,r=v403RoteiroPI(cod);if(!r)return alert('Roteiro do PI não encontrado.');
  let b;try{b=v4032BaseProdutoRoteiro(r,cod);}catch(e){return alert(e.message);}
  const mult=num($('v403_pi_mult')?.value);if(!(mult>0))return alert('Informe um fator de produção maior que zero.');
  const q=b.q*mult,base=baseOPCode(),op=criarOPFromRoteiroFiltradoV29(r,q,base+'-PI','PI',base,cod);
  op.OP_Pai='';op.OP_Base=op.CodOP;op.TipoOP='PI';op.OrigemGeracao='PI_ISOLADO';op.UM=b.um||op.UM;op.QtdBaseRoteiro=String(b.q);op.FatorEscalaRoteiro=String(mult);op.QtdPlanejada=String(q);op.OrigemQtdPlanejada='ROTEIRO_ETAPA_X_FATOR';
  (data.op_etapas||[]).filter(e=>e.CodOP===op.CodOP).forEach(e=>{e.QtdPlanejadaProduto=String(q);e.UMProduto=b.um||e.UMProduto;});
  const f=$('v403_pi_formula')?.value||'';if(f&&typeof aplicarFormulaNasOPsV3813==='function')aplicarFormulaNasOPsV3813([op],f);
  saveLocal();alert(`OP isolada ${op.CodOP} criada para ${cod}: ${b.q} ${b.um} × ${mult} = ${q} ${b.um}.`);render('op');
};

// Necessidade de PI em PA também parte obrigatoriamente da quantidade-base do roteiro.
v403RequiredPIQty=function(r,codPI,mult){
  const b=v4032BaseProdutoRoteiro(r,codPI),f=num(mult);
  return {q:b.q*(f>0?f:1),um:b.um,base:b.q,fator:f>0?f:1};
};

try{data.meta=data.meta||{};data.meta.patchV4032=APP_PATCH_V4032;saveLocal();}catch(e){console.warn('Patch V40.3.2:',e);}

/* =========================================================
   MES LION V40.3.3 — SIMULAÇÃO FLEXÍVEL PI + CUSTOS PI + DASH PRODUÇÃO + PASSAPORTE COMPOSIÇÃO
   - Simulações sem popup genérico de quantidade; PA ou PI isolado.
   - Custos industriais calculáveis por família PA ou OP PI isolada.
   - Dashboard sem custos/emissões nos KPIs e sem faixa amarela de fallback.
   - Avanço por tipo de processo abaixo do calendário.
   - Passaporte: gráfico de composição mássica e indicadores ambientais/econômicos internos.
   - Cliente: somente composição mássica + CO2eq/kWh entre os indicadores novos.
   ========================================================= */
const APP_PATCH_V4033='v40.3.3-simulacao-pi-custos-pi-dashboard-producao-passaporte-composicao';

function v4033PIs(){return (data.estrutura||[]).filter(p=>String(p['Tipo Produto']||'').toUpperCase()==='PI');}
function v4033PIBase(cod){const r=v403RoteiroPI(cod);if(!r)return {r:null,q:0,um:prodUMV382(cod)||''};try{const b=v4032BaseProdutoRoteiro(r,cod);return {r,q:b.q,um:b.um};}catch(e){return {r,q:0,um:prodUMV382(cod)||''};}}
function v4033EnergyRate(){return num(((data.custos_fatores||[]).find(f=>String(f.Tipo||'').toLowerCase()==='energia'&&String(f.Ativo||'Sim').toLowerCase()!=='não')||{}).CustoUnitario)||0.82;}
function v4033MODRate(){return num(((data.custos_fatores||[]).find(f=>String(f.Tipo||'').toLowerCase()==='mão de obra'&&String(f.Ativo||'Sim').toLowerCase()!=='não')||{}).CustoUnitario)||5;}
function v4033ProjectedPICost(codPI,qtd){
  const b=v4033PIBase(codPI);if(!b.r||!(b.q>0)||!(qtd>0))return {total:0,mat:0,en:0,mod:0,loss:0,energiaKWh:0,rows:[]};
  const stages=v4031TargetStages(b.r,codPI),mats=v4031MaterialsForTarget(b.r,codPI,stages),f=qtd/b.q;
  let mat=0,en=0,mod=0,energiaKWh=0;const rows=[];
  mats.forEach(m=>{const q=num(m.QtdBase||m.QtdPlanejada||m.Qtd)*f,u=materialUnitCostV3822(m.CodigoMaterial),t=q*u;mat+=t;rows.push({Tipo:'Material',Item:m.DescricaoMaterial||m.CodigoMaterial,Quantidade:q,UM:m.UMConsumo||m.UM||'',ValorUnitario:u,Total:t});});
  const rateE=v4033EnergyRate(),rateM=v4033MODRate(),seen=new Set();
  stages.forEach(e=>v4031ResourcesForStage(b.r,e).forEach(rec=>{const key=String(rec.IdRecursoRoteiro||'')||[e.Ordem||e.OrdemEtapa||'',rec.CodEquipamento||'',rec.Equipamento||''].join('|');if(seen.has(key))return;seen.add(key);const cad=(data.recursos||[]).find(x=>String(x.CodEquipamento||'')===String(rec.CodEquipamento||''))||{};const min=num(rec.TempoOperacaoMin||e.TempoOperacaoMin||cad['TempoOperação (min)']),pessoas=num(rec.NPessoas||e.NPessoas||cad.NPessoas)||1,pot=num(rec.PotenciaEquipamento||cad['PotenciaEquipamento (W)']),kwh=(pot/1000)*(min/60),ce=kwh*rateE,tm=num(cad['TaxaMOD (R$/h)'])||rateM,cm=(min/60)*pessoas*tm;energiaKWh+=kwh;en+=ce;mod+=cm;rows.push({Tipo:'Recurso',Item:rec.Equipamento||cad.Equipamento||rec.CodEquipamento,Quantidade:min,UM:'min',ValorUnitario:0,Total:ce+cm});}));
  return {total:mat+en+mod,mat,en,mod,loss:0,energiaKWh,rows};
}

function abrirSimulacaoAbastecimentoV403(){
  const pas=(data.estrutura||[]).filter(p=>String(p['Tipo Produto']||'').toUpperCase()==='PA'),pis=v4033PIs();
  $('sim_form').innerHTML=`<div class="form v4033-sim"><h3>Simulação de produção / abastecimento</h3><div class="form-grid"><label><span>Escopo</span><select id="v4033_sim_mode" onchange="v4033RenderSimulator()"><option value="PA">PA com seleção de PIs</option><option value="PI">PI isolado</option></select></label><label class="wide"><span>Produto</span><select id="v4033_sim_product" onchange="v4033RenderSimulatorBody()"></select></label></div><div id="v4033_sim_body"></div><div class="form-actions"><button onclick="v4033CalcSimulator()">Calcular cenário</button></div></div>`;
  v4033RenderSimulator();
}
function v4033RenderSimulator(){const mode=$('v4033_sim_mode')?.value||'PA',sel=$('v4033_sim_product');if(!sel)return;const arr=mode==='PI'?v4033PIs():(data.estrutura||[]).filter(p=>String(p['Tipo Produto']||'').toUpperCase()==='PA');sel.innerHTML=arr.map(p=>`<option value="${htmlEscape(p['Código'])}">${htmlEscape(p['Código']+' — '+(p['Descrição']||''))}</option>`).join('');v4033RenderSimulatorBody();}
function v4033RenderSimulatorBody(){const mode=$('v4033_sim_mode')?.value||'PA',cod=$('v4033_sim_product')?.value,box=$('v4033_sim_body');if(!box)return;if(mode==='PI'){const b=v4033PIBase(cod),lots=v403LotesDisponiveis(cod);box.innerHTML=`<div class="form-grid"><label><span>Quantidade a simular</span><input id="v4033_pi_q" type="number" min="0.0001" step="0.0001" value="${b.q||''}"></label><label><span>UM</span><input readonly value="${htmlEscape(b.um||'')}"></label><label class="wide"><span>Origem do PI</span><select id="v4033_pi_origin"><option value="PRODUZIR">Produzir novo pelo roteiro</option>${lots.map(l=>`<option value="LOT:${htmlEscape(l.IdLotePI)}">Usar ${htmlEscape(l.IdLotePI)} — saldo ${fmtMax4V395(v403SaldoLote(l))} ${htmlEscape(l.UM||'')}</option>`).join('')}</select></label></div>${!b.r?'<div class="card warn">Este PI não possui roteiro isolado salvo. Para simular nova produção, cadastre o roteiro do PI.</div>':''}`;return;}
  const r=roteiroSalvoProdutoV387(cod);if(!r){box.innerHTML='<div class="card warn">O PA selecionado não possui roteiro salvo.</div>';return;}box.innerHTML=`<div class="form-grid"><label><span>Multiplicador do PA</span><input id="v403_sim_mult" type="number" value="1" min="0.0001" step="0.0001" oninput="v403RenderSimSources()"></label></div><div id="v403_sim_sources"></div>`;v403RenderSimSources();}
function v4033CalcSimulator(){const mode=$('v4033_sim_mode')?.value||'PA';if(mode==='PA')return v403CalcSupplySimulation();const pi=$('v4033_sim_product')?.value,q=num($('v4033_pi_q')?.value),act=$('v4033_pi_origin')?.value||'PRODUZIR';if(!(q>0))return alert('A quantidade do PI deve ser maior que zero.');let d;if(act.startsWith('LOT:')){const l=(data.pi_lotes||[]).find(x=>x.IdLotePI===act.slice(4));if(!l)return alert('Selecione um lote disponível.');if(q>v403SaldoLote(l)+1e-9)return alert(`Saldo insuficiente. Disponível: ${fmtMax4V395(v403SaldoLote(l))} ${l.UM||''}.`);const s=v403SourceCost(l),f=s.q?q/s.q:0;d={PI:pi,Origem:l.IdLotePI,Quantidade:q,UM:l.UM||'',Materiais:s.mat*f,Energia:s.en*f,MOD:s.mod*f,Perdas:s.loss*f,Total:s.total*f};}else{const b=v4033PIBase(pi);if(!b.r)return alert('Este PI não possui roteiro isolado salvo.');const s=v4033ProjectedPICost(pi,q);d={PI:pi,Origem:'Nova produção pelo roteiro',Quantidade:q,UM:b.um,Materiais:s.mat,Energia:s.en,MOD:s.mod,Perdas:s.loss,Total:s.total};}$('sim_result').innerHTML=`<div class="card"><h3>Simulação do PI ${htmlEscape(pi)}</h3>${tableHTML([d],['PI','Origem','Quantidade','UM','Materiais','Energia','MOD','Perdas','Total'])}<p class="muted">A simulação não cria OP, não reserva lote e não altera estoque.</p></div>`;}

// Nova simulação abre sempre o simulador flexível; elimina o fluxo legado que exigia quantidade sem contexto.
const simulacoesModuleV4033Base=simulacoesModule;
simulacoesModule=function(){simulacoesModuleV4033Base();const tb=document.querySelector('#content .toolbar');if(tb){[...tb.querySelectorAll('button')].forEach(b=>{if(/^\+?\s*Nova simulação$/i.test(b.textContent.trim())){b.onclick=abrirSimulacaoAbastecimentoV403;b.textContent='+ Nova simulação PA / PI';}});const btn=document.getElementById('v403_sim_supply');if(btn){btn.textContent='Simular PA / PI';btn.onclick=abrirSimulacaoAbastecimentoV403;}}};

function v4033AuditCostPI(cod){const op=opPorCodigo(cod);if(!op)return {resumo:[{}],materiais:[],etapas:[],perdas:[],regras:[]};const old=opFamilyV33;try{opFamilyV33=()=>[op];return auditCostFamilyV4014(cod);}finally{opFamilyV33=old;}}
function v4033CostScope(cod,persist=true){const op=opPorCodigo(cod)||{},isPI=v403IsPI(op),a=isPI?v4033AuditCostPI(cod):auditCostFamilyV4014(cod),r=a.resumo?.[0]||{},q=num(op.QtdProduzida)||num(op.QtdPlanejada)||1,energia=(a.etapas||[]).reduce((s,e)=>s+num(e.EnergiaKWh),0),row={CodOP:cod,CodOPMae:isPI?'':cod,Escopo:isPI?'PI ISOLADO':'FAMÍLIA PA',ProdutoPA:op.CodigoProduto||op.Produto||'',DescricaoProduto:op.DescricaoProduto||'',DataCalculo:new Date().toLocaleString('pt-BR'),OPsRelacionadas:r.OPsIncluidas||cod,CustoMateriais:String(r.CustoMateriais||0),CustoEnergia:String(r.CustoEnergia||0),CustoMOD:String(r.CustoMOD||0),CustoPerdas:String(r.CustoPerdas||0),CustoTotal:String(r.CustoTotal||0),CustoUnitario:String(q?num(r.CustoTotal)/q:0),EnergiaKWh:String(energia),Observacoes:isPI?'Custo da OP de PI isolada: somente materiais, recursos, apontamentos e perdas desta OP.':'Custo consolidado da família PA conforme regras vigentes.'};if(persist){data.custos_op=data.custos_op||[];const i=data.custos_op.findIndex(x=>String(x.CodOP||x.CodOPMae||'')===String(cod));if(i>=0)data.custos_op[i]=row;else data.custos_op.unshift(row);saveLocal();}return {row,a};}
function v4033CostOptions(){return (data.op||[]).filter(o=>isPAOPV33(o)||v403IsPI(o)).map(o=>`<option value="${htmlEscape(o.CodOP)}">${v403IsPI(o)?'[PI] ':'[PA] '}${htmlEscape(opLabel(o))}</option>`).join('');}
function custosModule(){
  $('title').textContent='Custos Industriais';$('subtitle').textContent='Cálculo auditável para família de PA ou OP de PI isolada, usando materiais/lotes apontados, recursos únicos, energia, MOD e perdas.';
  $('content').innerHTML=`<div class="toolbar"><label>OP / escopo<select id="c_op"><option value="">Selecione uma OP</option>${v4033CostOptions()}</select></label><label>Taxa MOD<select id="c_mod_factor">${custoFactorOptionsV33('Mão de obra')}</select></label><label>Taxa energia<select id="c_energy_factor">${custoFactorOptionsV33('Energia')}</select></label><button onclick="v4033CalcCostSelected()">Calcular / atualizar</button><button class="secondary" onclick="v4033ExportCostSelected()">Exportar Excel auditável</button><button onclick="genericModule('custos_fatores','Fatores de custo')">Configurar custos e taxas</button></div><div id="c_result"></div><h3>Histórico de custos calculados</h3><div>${table('custos_op')}</div>`;
}
function v4033CalcCostSelected(){const cod=$('c_op')?.value;if(!cod)return alert('Selecione uma OP de PA ou PI.');const {row,a}=v4033CostScope(cod,true);$('c_result').innerHTML=`<div class="cards"><div class="card"><b>Escopo</b><div class="metric">${htmlEscape(row.Escopo)}</div></div><div class="card"><b>Custo total</b><div class="metric">${money(row.CustoTotal)}</div></div><div class="card"><b>Materiais</b><div class="metric">${money(row.CustoMateriais)}</div></div><div class="card"><b>Energia</b><div class="metric">${money(row.CustoEnergia)}</div></div><div class="card"><b>Mão de obra</b><div class="metric">${money(row.CustoMOD)}</div></div><div class="card"><b>Perdas</b><div class="metric">${money(row.CustoPerdas)}</div></div></div><div class="report"><h3>Memória auditável</h3>${tableHTML(a.materiais||[],['OP','Etapa','CodigoMaterial','Material','Quantidade','UM','Lote','Entrada','Fornecedor','CustoUnitario','Cálculo aberto','Resultado'])}${tableHTML(a.etapas||[],['OP','Ordem','Processo','Equipamento','TempoMin','Pessoas','PotenciaW','EnergiaKWh','CustoEnergia','CustoMOD'])}</div>`;}
function v4033ExportCostSelected(){const cod=$('c_op')?.value;if(!cod)return alert('Selecione uma OP de PA ou PI.');const {row,a}=v4033CostScope(cod,false);downloadAuditExcelV3819(`auditoria_custos_${cod}.xls`,`Auditoria de custos — ${cod}`,[{title:'Resumo',rows:[row]},{title:'Materiais',rows:a.materiais||[]},{title:'Energia e MOD',rows:a.etapas||[]},{title:'Perdas',rows:a.perdas||[]},{title:'Regras',rows:a.regras||[]}]);}

// Dashboard: remove cards financeiros/ambientais do resumo, retira a faixa amarela e inclui avanço por processo.
v402PlanBoard=function(rows){
  const monday=v402CurrentWeek(),days=Array.from({length:7},(_,i)=>v402AddDays(monday,i)),heads=['SEG','TER','QUA','QUI','SEX','SÁB','DOM'];
  const cols=days.map((d,i)=>{const iso=v402ISO(d),rr=rows.filter(r=>v402ISO(v402ScheduleInfo(r.op).date)===iso);const cards=rr.map(r=>{const info=v402ScheduleInfo(r.op),p=v402FamilyProgress(r),st=v40StatusClass(r.op.Status);return `<button class="v402-plan-card ${st}" onclick="render('op')"><header><b>${htmlEscape(r.root)}</b><em>${htmlEscape(v402StatusLabel(r.op.Status))}</em></header><strong>${htmlEscape(r.op.DescricaoProduto||r.op.CodigoProduto||'Produto')}</strong><div class="v402-cardmeta"><span>${htmlEscape(v402Project(r.op)||'Projeto não informado')}</span><span>${htmlEscape(v402Chem(r.op)||'Química não informada')}</span></div><div class="v402-progress"><i style="width:${p}%"></i></div><footer><span>${p}% das etapas</span><span>${info.planned?'Programada':'Data OP'}</span></footer></button>`}).join('');return `<section class="v402-day ${v402SelectedDay===iso?'selected':''}"><button class="v402-dayhead" onclick="v402SelectDay('${iso}')"><b>${heads[i]}</b><span>${v402FmtDate(d)}</span><em>${rr.length}</em></button><div>${cards||'<p class="v402-empty">Sem OP registrada.</p>'}</div></section>`;}).join('');const end=v402AddDays(monday,6);return `<div class="v402-plan-toolbar"><div><b>Plano de produção por calendário</b><span>${v402FmtDate(monday)} a ${v402FmtDate(end)}</span></div><div><button onclick="v402SetWeek(-1)">‹</button><button onclick="v402GoToday()">Semana dos dados</button><button onclick="v402SetWeek(1)">›</button></div></div><div class="v402-week">${cols}</div>`;
};
function v4033LotsAvailableCount(){v403SyncPILots();return (data.pi_lotes||[]).filter(l=>v403SaldoLote(l)>0).length;}
function v4033ProcessProgress(rows){return v397ProcessHealth(rows);}
function dashboard(){
  if($('title'))$('title').textContent='Dashboard operacional';if($('subtitle'))$('subtitle').textContent='Planejamento, andamento da produção e rastreabilidade calculados a partir dos registros do MES LION.';const rows=v402RootRows(),roots=rows.map(r=>r.op);
  $('content').innerHTML=`<div class="v402-dashboard"><section class="v402-filters"><label>OP PA<select id="v402_op" onchange="v402UpdateDashboard()">${v397FilterOptions(rows.map(r=>r.root),'Todas as OPs')}</select></label><label>Projeto<select id="v402_proj" onchange="v402UpdateDashboard()">${v397FilterOptions(roots.map(v402Project),'Todos os projetos')}</select></label><label>Química<select id="v402_chem" onchange="v402UpdateDashboard()">${v397FilterOptions(roots.map(v402Chem),'Todas as químicas')}</select></label><label>Status<select id="v402_status" onchange="v402UpdateDashboard()"><option value="">Todos</option><option value="plan">Planejada</option><option value="run">Em produção / reaberta</option><option value="alert">Atenção / bloqueada</option><option value="done">Concluída</option></select></label><label class="search">Pesquisa<input id="v402_q" oninput="v402UpdateDashboard()" placeholder="OP, produto, status..."></label></section><section id="v402_kpis" class="v402-kpis"></section><section class="v402-main-grid"><article class="v402-panel v402-plan-panel"><div id="v402_plan"></div></article><aside><article class="v402-panel"><header><b>Agenda da data selecionada</b><span>registros existentes</span></header><div id="v402_agenda"></div></article><article class="v402-panel"><header><b>Alertas operacionais</b><span>cadastros e apontamentos</span></header><div id="v402_alerts"></div></article></aside></section><section class="v402-panel v4033-process-panel"><header><b>Avanço dos apontamentos por tipo de processo</b><span>percentual de etapas concluídas nas famílias filtradas</span></header><div id="v4033_process"></div></section><section class="v402-lower-grid v4033-lower"><article class="v402-panel"><header><b>Carga planejada por recurso</b><span>horas das etapas únicas</span></header><div id="v402_load"></div></article><article class="v402-panel"><header><b>Histórico de OPs</b><span>meses existentes no banco</span></header><div id="v402_history"></div></article><article class="v402-panel"><header><b>Rastreabilidade de produção</b><span>lotes e perdas registrados</span></header><div id="v4033_trace"></div></article></section></div>`;v402UpdateDashboard();
}
v402UpdateDashboard=function(){const rows=v402RootFamiliesFiltered(),planned=rows.filter(r=>v40StatusClass(r.op.Status)==='plan').length,run=rows.filter(r=>v40StatusClass(r.op.Status)==='run').length,done=rows.filter(r=>v40StatusClass(r.op.Status)==='done').length,alert=rows.filter(r=>v40StatusClass(r.op.Status)==='alert').length;const opCodes=new Set();rows.forEach(r=>v402FamilyOps(r.root).forEach(o=>opCodes.add(o.CodOP)));const cons=(data.consumos_materiais||[]).filter(c=>opCodes.has(c.CodOP)),traced=cons.filter(c=>String(c.Lote||'').trim()).length,tracePct=cons.length?traced/cons.length*100:0,losses=(data.perdas||[]).filter(p=>opCodes.has(p.CodOP||p.NOPP)).length,lots=v4033LotsAvailableCount();$('v402_kpis').innerHTML=[v402Kpi('▦','OPs planejadas',planned,'famílias PA','plan'),v402Kpi('▶','Em produção',run,'famílias PA','run'),v402Kpi('✓','Concluídas',done,'famílias PA','done'),v402Kpi('!','Atenção / bloqueadas',alert,'conforme status','alert'),v402Kpi('◎','Rastreabilidade',v397N(tracePct,1)+'%','consumos com lote','trace'),v402Kpi('PI','Lotes de PI disponíveis',lots,'saldo maior que zero',''),v402Kpi('↘','Apontamentos de perda',losses,'registros nas OPs filtradas','loss')].join('');$('v402_plan').innerHTML=v402PlanBoard(rows);$('v402_agenda').innerHTML=v402Agenda(rows);$('v402_alerts').innerHTML=v402RealAlerts(rows);$('v402_load').innerHTML=v402ResourceLoad(rows);$('v402_history').innerHTML=v402MonthlyHistory();$('v4033_process').innerHTML=v4033ProcessProgress(rows);$('v4033_trace').innerHTML=`<div class="v402-econ"><div><span>Consumos com lote</span><b>${traced}/${cons.length}</b></div><div><span>Rastreabilidade</span><b>${v397N(tracePct,1)}%</b></div><div><span>Perdas apontadas</span><b>${losses}</b></div><div><span>Lotes PI disponíveis</span><b>${lots}</b></div></div>`;};

function v4033MaterialMassRows(bp){const codes=bpFamilyCodesV401(bp),cons=(data.consumos_materiais||[]).filter(c=>codes.includes(c.CodOP));const by={};if(cons.length){cons.forEach(c=>{const cod=c.CodigoMaterial||'',q=num(c.ConsumoLiquido)||Math.max(0,num(c.QtdRetirada)-num(c.QtdDevolvida)),f=fatorKgMaterialV3822(cod)||0,m=q*f;if(!(m>0))return;const mat=materialPorCodigo(cod)||{};by[cod]=by[cod]||{CodigoMaterial:cod,Material:c.DescricaoMaterial||mat.DescricaoMateriais||cod,MassaKg:0};by[cod].MassaKg+=m;});}else{(data.op_materiais||[]).filter(m=>codes.includes(m.CodOP)&&!String(m.TipoConsumo||'').toLowerCase().includes('pi intermedi')).forEach(x=>{const cod=x.CodigoMaterial||'',q=num(x.QtdConsumida||x.ConsumoReal||x.QtdReal||x.QtdPlanejada||x.QtdBase),f=fatorKgMaterialV3822(cod)||0,m=q*f;if(!(m>0))return;const mat=materialPorCodigo(cod)||{};by[cod]=by[cod]||{CodigoMaterial:cod,Material:x.DescricaoMaterial||mat.DescricaoMateriais||cod,MassaKg:0};by[cod].MassaKg+=m;});}const arr=Object.values(by),total=arr.reduce((s,x)=>s+x.MassaKg,0);arr.forEach(x=>x.PercentualMassa=total?x.MassaKg/total*100:0);return {rows:arr.sort((a,b)=>b.MassaKg-a.MassaKg),total};}
function v4033PieHTML(bp){const d=v4033MaterialMassRows(bp);if(!d.rows.length)return '<div class="muted">Não há massa de materiais suficiente para calcular a composição.</div>';let acc=0;const colors=['#0b5ea8','#39a935','#78b82a','#1f7a8c','#f2a900','#6c5ce7','#00a8a8','#d35400','#7f8c8d','#2d98da','#8854d0','#20bf6b'];const stops=d.rows.map((x,i)=>{const a=acc,b=acc+x.PercentualMassa;acc=b;return `${colors[i%colors.length]} ${a}% ${b}%`;}).join(',');return `<div class="v4033-pie-wrap"><div class="v4033-pie" style="background:conic-gradient(${stops})"><span>${fmtMax4V395(d.total)}<small>kg</small></span></div><div class="v4033-pie-legend">${d.rows.map((x,i)=>`<div><i style="background:${colors[i%colors.length]}"></i><span>${htmlEscape(x.Material)}</span><b>${v397N(x.PercentualMassa,2)}%</b><small>${fmtMax4V395(x.MassaKg)} kg</small></div>`).join('')}</div></div>`;}
function v4033PassportMetrics(bp){const op=opPorCodigo(bp.CodOrdemProducao)||{},root=rootOPV395(op||{CodOP:bp.CodOrdemProducao}),s=calcSustFamiliaOPV33(root,false,{})||{},c=calcCustoFamiliaOPV33(root,false,{})||{},prod=produtoPorCodigo(bp.CodProduto)||{},mass=v4033MaterialMassRows(bp).total,co2=num(s.CO2eqTotal),energyKWh=num(prod['Energia (Wh)'])/1000,totalCost=num(c.CustoTotal);return {co2,energyKWh,co2PerKWh:energyKWh>0?co2/energyKWh:null,co2PerReal:totalCost>0?co2/totalCost:null,costPerKg:mass>0?totalCost/mass:null,mass,totalCost};}
