try{data.meta=data.meta||{};data.meta.patchV4033=APP_PATCH_V4033;saveLocal();}catch(e){console.warn('Patch V40.3.3:',e);}

/* =========================================================
   MES LION V40.3.4 — ARREDONDAMENTO, SIMULAÇÃO PI E PASSAPORTE PA+PI
   - apresentação numérica com no máximo 3 casas decimais;
   - simulador flexível não usa mais validação legada de sim_q;
   - composição mássica consolida PA + OPs PI da família + lotes PI herdados;
   - cliente recebe CO2eq/kWh, CO2eq/R$ e composição mássica completa.
   ========================================================= */
const APP_PATCH_V4034='v40.3.4-arredondamento-simulacao-pi-passaporte-pa-pi';

function v4034FormatNumber(v,max=3){
  const n=typeof v==='number'?v:num(v);
  if(!Number.isFinite(n))return String(v??'');
  return n.toLocaleString('pt-BR',{minimumFractionDigits:0,maximumFractionDigits:Math.min(3,Math.max(0,max))});
}
fmt=function(v,d=2){return v4034FormatNumber(Number(v)||0,Math.min(3,d));};
fmtMax4V395=function(v){
  if(v===null||v===undefined||v==='')return '';
  if(typeof v==='number'&&Number.isFinite(v))return v4034FormatNumber(v,3);
  const s=String(v).trim();
  if(/^[-+]?\d+(?:[.,]\d+)?$/.test(s))return v4034FormatNumber(num(s),3);
  return s;
};
num4V395=function(v){return v4034FormatNumber(num(v)||0,3);};
v397N=function(v,d=2){return v4034FormatNumber(Number(v||0),Math.min(3,d));};
v4033MetricValue=function(v,suffix){return v===null||v===undefined||!isFinite(v)?'N/D':`${v4034FormatNumber(v,3)}${suffix||''}`;};

const displayValueV4034Base=displayValue;
displayValue=function(field,value){
  if(value===undefined||value===null)return '';
  if(/^Imagem/i.test(field)||/_Imagem|Imagem/.test(field))return value?'Imagem anexada':'';
  const f=String(field||'');
  const identifier=/(^|_)(cod|codigo|código|id|guid|hash)\b|cnpj|nota.?fiscal|\bnf\b|lote|status|vers[aã]o|data|roteiro|\bop\b/i.test(f);
  if(!identifier){
    if(typeof value==='number'&&Number.isFinite(value))return v4034FormatNumber(value,3);
    const s=String(value).trim();
    if(/^[-+]?\d+(?:[.,]\d+)?$/.test(s))return v4034FormatNumber(num(s),3);
  }
  return displayValueV4034Base(field,value);
};

function v4034QuantityForMaterialRecord(x){
  return num(x.ConsumoLiquido)||Math.max(0,num(x.QtdRetirada)-num(x.QtdDevolvida))||num(x.QtdConsumida||x.ConsumoReal||x.QtdReal||x.QtdPlanejada||x.QtdBase||x.Qtd);
}
function v4034AddMass(by,cod,desc,q,scale=1){
  if(!cod||!(q>0)||!(scale>0))return;
  const f=fatorKgMaterialV3822(cod)||0,m=q*f*scale;
  if(!(m>0))return;
  const mat=materialPorCodigo(cod)||{};
  by[cod]=by[cod]||{CodigoMaterial:cod,Material:desc||mat.DescricaoMateriais||cod,MassaKg:0};
  by[cod].MassaKg+=m;
}
function v4034AddRawMassFromOP(by,codOP,scale=1){
  const planned=(data.op_materiais||[]).filter(x=>x.CodOP===codOP&&!String(x.TipoConsumo||'').toLowerCase().includes('pi intermedi'));
  const actual=(data.consumos_materiais||[]).filter(x=>x.CodOP===codOP);
  const actualBy={};
  actual.forEach(x=>{const cod=x.CodigoMaterial||'';if(!cod)return;actualBy[cod]=actualBy[cod]||{q:0,desc:x.DescricaoMaterial||''};actualBy[cod].q+=v4034QuantityForMaterialRecord(x);});
  const used=new Set();
  planned.forEach(x=>{const cod=x.CodigoMaterial||'';if(!cod)return;if(used.has(cod))return;used.add(cod);const a=actualBy[cod],q=a&&a.q>0?a.q:v4034QuantityForMaterialRecord(x);v4034AddMass(by,cod,(a&&a.desc)||x.DescricaoMaterial||'',q,scale);});
  Object.entries(actualBy).forEach(([cod,a])=>{if(!used.has(cod))v4034AddMass(by,cod,a.desc,a.q,scale);});
}
function v4034RootPAForBP(bp){
  const op=opPorCodigo(bp?.CodOrdemProducao||'')||{};
  if(String(op.TipoOP||'').toUpperCase()==='PA')return op.CodOP;
  return op.OP_Pai||op.OP_Base||rootOPV395(op)||bp?.CodOrdemProducao||'';
}
function v4034MaterialMassRows(bp){
  const by={},root=v4034RootPAForBP(bp),family=opFamilyV33(root)||[];
  const familyCodes=family.length?family.map(o=>o.CodOP):[root].filter(Boolean);
  familyCodes.forEach(c=>v4034AddRawMassFromOP(by,c,1));
  const inherited=(data.op_pi_consumos||[]).filter(c=>c.CodOPPA===root&&String(c.Status||'ATIVO').toUpperCase()!=='CANCELADO');
  inherited.forEach(c=>{
    const lot=(data.pi_lotes||[]).find(l=>l.IdLotePI===c.IdLotePI)||{},src=opPorCodigo(c.CodOPOrigemPI||lot.CodOPOrigem)||{};
    const produced=v403Produced(src)||num(lot.QuantidadeProduzida),cons=num(c.QuantidadeConsumida),scale=produced>0?cons/produced:0;
    if(scale>0)v4034AddRawMassFromOP(by,src.CodOP||c.CodOPOrigemPI,scale);
  });
  const arr=Object.values(by),total=arr.reduce((s,x)=>s+x.MassaKg,0);
  arr.forEach(x=>x.PercentualMassa=total?x.MassaKg/total*100:0);
  return {rows:arr.sort((a,b)=>b.MassaKg-a.MassaKg),total};
}
v4033MaterialMassRows=v4034MaterialMassRows;

v4033PieHTML=function(bp){
  const d=v4034MaterialMassRows(bp);if(!d.rows.length)return '<div class="muted">Não há massa de materiais suficiente para calcular a composição completa da célula.</div>';
  let acc=0;const colors=['#0b5ea8','#39a935','#78b82a','#1f7a8c','#f2a900','#6c5ce7','#00a8a8','#d35400','#7f8c8d','#2d98da','#8854d0','#20bf6b'];
  const stops=d.rows.map((x,i)=>{const a=acc,b=acc+x.PercentualMassa;acc=b;return `${colors[i%colors.length]} ${a}% ${b}%`;}).join(',');
  return `<div class="v4033-pie-wrap"><div class="v4033-pie" style="background:conic-gradient(${stops})"><span>${v4034FormatNumber(d.total,3)}<small>kg</small></span></div><div class="v4033-pie-legend">${d.rows.map((x,i)=>`<div><i style="background:${colors[i%colors.length]}"></i><span>${htmlEscape(x.Material)}</span><b>${v4034FormatNumber(x.PercentualMassa,3)}%</b><small>${v4034FormatNumber(x.MassaKg,3)} kg</small></div>`).join('')}</div></div>`;
};

v4033PassportMetrics=function(bp){
  const op=opPorCodigo(bp.CodOrdemProducao)||{},root=v4034RootPAForBP(bp),s=calcSustFamiliaOPV33(root,false,{})||{},c=calcCustoFamiliaOPV33(root,false,{})||{},prod=produtoPorCodigo(bp.CodProduto)||{},mass=v4034MaterialMassRows(bp).total,co2=num(s.CO2eqTotal),energyKWh=num(prod['Energia (Wh)'])/1000,totalCost=num(c.CustoTotal);
  return {co2,energyKWh,co2PerKWh:energyKWh>0?co2/energyKWh:null,co2PerReal:totalCost>0?co2/totalCost:null,costPerKg:mass>0?totalCost/mass:null,mass,totalCost};
};

// O simulador flexível nunca chama a validação antiga de sim_q. Se o campo PI estiver vazio,
// restaura silenciosamente a quantidade-base do roteiro para permitir o cálculo.
v4033CalcSimulator=function(){
  const mode=$('v4033_sim_mode')?.value||'PA';
  if(mode==='PA'){
    v403CalcSupplySimulation();window.__v4034FlexibleSim={mode:'PA',Produto:$('v4033_sim_product')?.value||'',Data:new Date().toLocaleString('pt-BR')};return;
  }
  const pi=$('v4033_sim_product')?.value,b=v4033PIBase(pi);let q=num($('v4033_pi_q')?.value);if(!(q>0)){q=b.q||1;if($('v4033_pi_q'))$('v4033_pi_q').value=String(q);}
  const act=$('v4033_pi_origin')?.value||'PRODUZIR';let d;
  if(act.startsWith('LOT:')){const l=(data.pi_lotes||[]).find(x=>x.IdLotePI===act.slice(4));if(!l)return alert('Selecione um lote disponível.');if(q>v403SaldoLote(l)+1e-9)return alert(`Saldo insuficiente. Disponível: ${v4034FormatNumber(v403SaldoLote(l),3)} ${l.UM||''}.`);const s=v403SourceCost(l),f=s.q?q/s.q:0;d={PI:pi,Origem:l.IdLotePI,Quantidade:q,UM:l.UM||'',Materiais:s.mat*f,Energia:s.en*f,MOD:s.mod*f,Perdas:s.loss*f,Total:s.total*f};}
  else{if(!b.r)return alert('Este PI não possui roteiro isolado salvo.');const s=v4033ProjectedPICost(pi,q);d={PI:pi,Origem:'Nova produção pelo roteiro',Quantidade:q,UM:b.um,Materiais:s.mat,Energia:s.en,MOD:s.mod,Perdas:s.loss,Total:s.total};}
  window.__v4034FlexibleSim={mode:'PI',...d,Data:new Date().toLocaleString('pt-BR')};
  $('sim_result').innerHTML=`<div class="card"><h3>Simulação do PI ${htmlEscape(pi)}</h3>${tableHTML([d],['PI','Origem','Quantidade','UM','Materiais','Energia','MOD','Perdas','Total'])}<p class="muted">A simulação não cria OP, não reserva lote e não altera estoque.</p></div>`;
};

const salvarSimulacaoAtualV4034Base=salvarSimulacaoAtual;
salvarSimulacaoAtual=function(){
  if($('v4033_sim_mode')){
    if(!window.__v4034FlexibleSim)v4033CalcSimulator();
    const r=window.__v4034FlexibleSim;if(!r)return;
    data.simulacoes=data.simulacoes||[];
    data.simulacoes.unshift({IdSimulacao:getSimCode(),Data:new Date().toLocaleDateString('pt-BR'),Escopo:r.mode,Produto:r.Produto||r.PI||'',Origem:r.Origem||'',Quantidade:r.Quantidade||'',UM:r.UM||'',CustoMateriais:r.Materiais||'',CustoEnergia:r.Energia||'',CustoMOD:r.MOD||'',CustoOutros:r.Perdas||'',CustoTotal:r.Total||'',Observacoes:'Simulação flexível PA/PI. Não altera OP nem estoque.'});
    saveLocal();alert('Simulação salva.');render('simulacoes');return;
  }
  return salvarSimulacaoAtualV4034Base();
};

