/* =========================================================
   MES LION V40.3.8 — DASHBOARD ANALÍTICO LEVE
   - NÃO executa motores de Custos/ACV ao abrir o dashboard.
   - Usa somente registros já persistidos em OPs, custos e ACV.
   - Evita varrer sust_lci (biblioteca LCI grande) no dashboard.
   - Sem cache volumoso e sem listeners/intervalos adicionais.
   ========================================================= */
const APP_PATCH_V4038='v40.3.8-dashboard-analitico-leve';
function v4038FamilyRoot(op){
  if(!op)return '';
  return String(op.OP_Pai||op.CodOPMae||op.CodOP||'');
}
function v4038FilteredRoots(){
  const roots=v402RootRows();
  const opf=String($('v4038_op')?.value||''), proj=String($('v4038_proj')?.value||''), chem=String($('v4038_chem')?.value||''), st=String($('v4038_status')?.value||''), q=String($('v4038_q')?.value||'').trim().toLowerCase();
  return roots.filter(r=>{
    const op=r.op||{};
    if(opf && String(r.root)!==opf)return false;
    if(proj && String(v402Project(op))!==proj)return false;
    if(chem && String(v402Chem(op))!==chem)return false;
    if(st && String(v402StatusBucket(op))!==st)return false;
    if(q){const hay=`${r.root} ${op.CodigoProduto||''} ${op.DescricaoProduto||''}`.toLowerCase();if(!hay.includes(q))return false;}
    return true;
  });
}
function v4038FamilyOpsSet(root){
  const s=new Set([String(root)]);
  (data.op||[]).forEach(o=>{if(v4038FamilyRoot(o)===String(root))s.add(String(o.CodOP));});
  return s;
}
function v4038CostByProcess(roots){
  const out={};
  roots.forEach(r=>{
    const set=v4038FamilyOpsSet(r.root);
    (data.op_materiais||[]).forEach(m=>{
      if(!set.has(String(m.CodOP)))return;
      const p=v4036ProcessName(m.Processo||((data.op_etapas||[]).find(e=>String(e.CodOP)===String(m.CodOP)&&String(e.Ordem??'')===String(m.Ordem??m.OrdemEtapa??''))||{}).Processo);
      let v=num(m.CustoEfetivo);
      if(!(v>=0))v=num(m.CustoProjetado||m.CustoTotal);
      v4036Add(out,p,v);
    });
  });
  return Object.entries(out).map(([name,value])=>({name,value})).filter(x=>x.value>0).sort((a,b)=>b.value-a.value);
}
function v4038EnergyByProcess(roots){
  const out={}, seen=new Set();
  roots.forEach(r=>{
    const set=v4038FamilyOpsSet(r.root);
    (data.op_etapas||[]).forEach(e=>{
      if(!set.has(String(e.CodOP)))return;
      const unique=`${e.CodOP}|${e.Ordem??''}|${e.IdRecursoRoteiro||e.CodEquipamento||e.Recurso||''}`;
      if(seen.has(unique))return;seen.add(unique);
      const p=v4036ProcessName(e.Processo||e.DescricaoProcesso);
      const power=num(e.PotenciaEquipamento); // W
      const mins=num(e.TempoRealMin||e.TempoApontadoMin||e.TempoOperacaoMin||e.TempoPlanejado);
      const kwh=(power>0&&mins>0)?power/1000*mins/60:0;
      v4036Add(out,p,kwh);
    });
  });
  return Object.entries(out).map(([name,value])=>({name,value})).filter(x=>x.value>0).sort((a,b)=>b.value-a.value);
}
function v4038SustRowsForRoot(root){
  const s=(data.sust_op||[]).filter(x=>String(x.CodOPMae||x.CodOP||'')===String(root));
  if(!s.length)return [];
  const rec=s[s.length-1];
  try{return JSON.parse(rec.AuditoriaCO2JSON||'[]')||[];}catch(e){return [];}
}
function v4038Co2ByProcess(roots,energyRows){
  const out={};
  roots.forEach(r=>{
    const rows=v4038SustRowsForRoot(r.root);
    rows.filter(x=>String(x.Tipo||'').toUpperCase()!=='ENERGIA').forEach(x=>v4036Add(out,v4036ProcessName(x.Etapa),num(x.CO2eq)));
  });
  // Energia: usa o fator persistido atual, sem chamar biblioteca LCI/ACV.
  let ef=0;const f=(data.sust_fatores||[]).find(x=>String(x.Item||'').toLowerCase().includes('energia elétrica')&&String(x.Indicador||'').toLowerCase().includes('co2'));
  ef=num(f?.Fator);
  if(ef>0)(energyRows||[]).forEach(x=>v4036Add(out,x.name,x.value*ef));
  return Object.entries(out).map(([name,value])=>({name,value})).filter(x=>x.value>0).sort((a,b)=>b.value-a.value);
}
function v4038Co2ByCell(roots){
  const out={};
  roots.forEach(r=>{
    const rec=(data.sust_op||[]).filter(x=>String(x.CodOPMae||x.CodOP||'')===String(r.root)).slice(-1)[0];
    if(rec)v4036Add(out,v4036CellType(r.op),num(rec.CO2eqTotal));
  });
  return Object.entries(out).map(([name,value])=>({name,value})).filter(x=>x.value>0).sort((a,b)=>b.value-a.value);
}
function v4038Completion(roots){
  const acc={};
  roots.forEach(r=>{
    const set=v4038FamilyOpsSet(r.root), seen=new Set();
    (data.op_etapas||[]).forEach(e=>{
      if(!set.has(String(e.CodOP)))return;
      const key=`${e.CodOP}|${e.Ordem??''}|${e.Processo||''}`;
      if(seen.has(key))return;seen.add(key);
      const p=v4036ProcessName(e.Processo||e.DescricaoProcesso);acc[p]=acc[p]||{done:0,total:0};acc[p].total++;
      const prod=(data.producao||[]).some(a=>String(a.CodOP||'')===String(e.CodOP)&&String(a.Ordem??a.OrdemEtapa??'')===String(e.Ordem??'')&&num(a.QtdProduzida||a.QuantidadeRealProduzida)>0);
      if(isConcluido(e.Status)||prod)acc[p].done++;
    });
  });
  return Object.entries(acc).map(([name,x])=>({name,value:x.total?x.done/x.total*100:0,count:x.total})).sort((a,b)=>b.value-a.value);
}
let v4038_refresh_timer=0;
function v4038ScheduleRefresh(){clearTimeout(v4038_refresh_timer);v4038_refresh_timer=setTimeout(v4038Refresh,180);}
function v4038Refresh(){
  const roots=v4038FilteredRoots();
  const energy=v4038EnergyByProcess(roots);
  const set=(id,h)=>{const e=$(id);if(e)e.innerHTML=h;};
  set('v4038_cost',v4036Pie(v4038CostByProcess(roots)));
  set('v4038_energy',v4036Bars(energy,' kWh'));
  set('v4038_co2proc',v4036Bars(v4038Co2ByProcess(roots,energy),' kg CO₂eq'));
  set('v4038_co2cell',v4036Bars(v4038Co2ByCell(roots),' kg CO₂eq'));
  set('v4038_progress',v4036Bars(v4038Completion(roots),'',true));
}
function v4038Dashboard(){
  if($('title'))$('title').textContent='Dashboard Industrial';
  if($('subtitle'))$('subtitle').textContent='Indicadores consolidados já registrados no MES.';
  const rows=v402RootRows(),roots=rows.map(r=>r.op);
  $('content').innerHTML=`<div class="v4036-dashboard v4038-dashboard">
   <section class="v4036-filters v4038-filters">
    <label>OP<select id="v4038_op" onchange="v4038Refresh()">${v397FilterOptions(rows.map(r=>r.root),'Todas')}</select></label>
    <label>Projeto<select id="v4038_proj" onchange="v4038Refresh()">${v397FilterOptions(roots.map(v402Project),'Todos')}</select></label>
    <label>Química<select id="v4038_chem" onchange="v4038Refresh()">${v397FilterOptions(roots.map(v402Chem),'Todas')}</select></label>
    <label>Status<select id="v4038_status" onchange="v4038Refresh()"><option value="">Todos</option><option value="plan">Planejada</option><option value="run">Em produção</option><option value="alert">Atenção</option><option value="done">Concluída</option></select></label>
    <label class="search">Pesquisa<input id="v4038_q" oninput="v4038ScheduleRefresh()" placeholder="OP ou produto"></label>
   </section>
   <section class="v4036-grid v4038-grid">
    <article class="v4036-chart"><header><b>Custos de materiais por processo</b><span>R$</span></header><div id="v4038_cost"></div></article>
    <article class="v4036-chart"><header><b>Energia por processo</b><span>kWh</span></header><div id="v4038_energy"></div></article>
    <article class="v4036-chart"><header><b>Emissões de CO₂eq por processo</b><span>dados ACV já calculados</span></header><div id="v4038_co2proc"></div></article>
    <article class="v4036-chart"><header><b>CO₂eq por tipo de célula</b><span>dados ACV já calculados</span></header><div id="v4038_co2cell"></div></article>
    <article class="v4036-chart v4036-wide"><header><b>Produção concluída por processo</b><span>% apontado/concluído</span></header><div id="v4038_progress"></div></article>
   </section>
  </div>`;
  // Aguarda um frame para pintar a tela antes de agregar dados.
  requestAnimationFrame(()=>setTimeout(v4038Refresh,0));
}
dashboard=v4038Dashboard;
v402UpdateDashboard=v4038Refresh;
