/* =========================================================
   MES LION V40.4.0 — HOME NEUTRA + HELP DESK COMPACTO
   - Dashboard permanece removido.
   - O sistema inicia em HOME, sem abrir qualquer módulo.
   - HOME é somente uma tela neutra de entrada; não executa cálculos.
   - Atalho lateral mantém o texto "Help Desk", em formato compacto.
   ========================================================= */
const APP_PATCH_V4040='v40.4.0-home-neutra-helpdesk-compacto';
function v4040Home(){
  current='home';
  document.body.classList.remove('dashboard-mode');
  document.querySelectorAll('nav button').forEach(b=>b.classList.remove('active'));
  document.getElementById('nav_home')?.classList.add('active');
  if($('title')) $('title').textContent='MES LION';
  if($('subtitle')) $('subtitle').textContent='Manufacturing Execution System';
  if($('content')) $('content').innerHTML=`
    <section class="v4040-home" aria-label="Página inicial do MES LION">
      <img src="assets/logo-mes.jpg" alt="MES LION" class="v4040-home-logo">
      <div class="v4040-home-line"></div>
      <p>Selecione um módulo no menu lateral para iniciar.</p>
    </section>`;
}
const _renderNavV4040=renderNav;
renderNav=function(){
  _renderNavV4040();
  document.getElementById('nav_dashboard')?.remove();
  const nav=$('nav');
  if(nav && !document.getElementById('nav_home')){
    const b=document.createElement('button');
    b.id='nav_home';
    b.className='nav-home v4040-home-nav';
    b.innerHTML='<span class="v4040-home-icon">⌂</span><span>Home</span>';
    b.onclick=()=>render('home');
    nav.insertBefore(b,nav.firstChild);
  }
  const h=document.getElementById('helpDeskNavV400')||document.getElementById('helpDeskNavV395');
  if(h){
    h.textContent='? Help Desk';
    h.title='Help Desk / Fluxo';
    h.setAttribute('aria-label','Help Desk / Fluxo');
    h.classList.remove('v4039-help-compact');
    h.classList.add('v4040-help-compact');
  }
};
const _renderV4040=render;
render=function(k){
  if(!k || k==='dashboard' || k==='home') return v4040Home();
  return _renderV4040(k);
};
