current='home';
try{data.meta=data.meta||{};data.meta.patchV4040=APP_PATCH_V4040;}catch(e){}


/* =========================================================
   MES LION V40.4.1 — PASSAPORTE LEVE + MASSA DE PROCESSO COMPLETA
   - HOME totalmente vazia, somente fundo claro;
   - Passaporte não recalcula Custos/ACV ao abrir: usa resultados já salvos;
   - composição mássica usa a auditoria ACV salva quando disponível,
     consolidando todos os CONSUMOS da família PA + PI (LFP, grafite,
     binders, condutores, solventes, coletores, separador, eletrólito, case etc.);
   - fallback leve pelos apontamentos/OPs quando ainda não existir ACV salvo;
   - nenhuma biblioteca pesada ou varredura da LCI ao abrir o Passaporte.
   ========================================================= */
const APP_PATCH_V4041='v40.4.1-passaporte-leve-massa-processos-home-vazia';

function v4041SavedRootRow(arr,root){
  const stem=v4035StemOP(root);
  return (arr||[]).find(r=>{
    const c=String(r.CodOP||''),m=String(r.CodOPMae||'');
    return c===root||c===stem||m===root||m===stem;
  })||null;
}
function v4041FamilyForBP(bp){
  const root=v4034RootPAForBP(bp);
  const ops=v4035FamilyOps(root);
  return {root,ops,codes:new Set(ops.map(o=>o.CodOP))};
}
function v4041MassFromSavedAudit(bp){
  const {root}=v4041FamilyForBP(bp),s=v4041SavedRootRow(data.sust_op,root);
  if(!s||!s.AuditoriaCO2JSON)return null;
  try{
    const audit=JSON.parse(s.AuditoriaCO2JSON),by={};
    audit.forEach(x=>{
      if(String(x.Tipo||'').toUpperCase()!=='CONSUMO')return;
      const cod=String(x.CodigoMaterial||'').trim();
      if(!cod||cod==='ENERGIA'||cod.toUpperCase().startsWith('PI'))return;
      const m=num(x.MassaKg);if(!(m>0))return;
      by[cod]=by[cod]||{CodigoMaterial:cod,Material:x.Material||cod,MassaKg:0,Processos:new Set()};
      by[cod].MassaKg+=m;
      if(x.Etapa)by[cod].Processos.add(String(x.Etapa));
    });
    const rows=Object.values(by).map(x=>({...x,Processos:[...x.Processos].join('; ')}));
    const total=rows.reduce((s,x)=>s+x.MassaKg,0);
    rows.forEach(x=>x.PercentualMassa=total?x.MassaKg/total*100:0);
    rows.sort((a,b)=>b.MassaKg-a.MassaKg);
    return rows.length?{rows,total,fonte:'ACV auditável salva'}:null;
  }catch(e){console.warn('V40.4.1: auditoria ACV inválida, usando fallback de OP.',e);return null;}
}
function v4041AddMass(by,cod,desc,q,proc,scale=1){
  if(!cod||String(cod).toUpperCase().startsWith('PI')||!(q>0)||!(scale>0))return;
  const f=fatorKgMaterialV3822(cod)||0,m=q*f*scale;if(!(m>0))return;
  const mat=materialPorCodigo(cod)||{};
  by[cod]=by[cod]||{CodigoMaterial:cod,Material:desc||mat.DescricaoMateriais||cod,MassaKg:0,Processos:new Set()};
  by[cod].MassaKg+=m;if(proc)by[cod].Processos.add(String(proc));
}
function v4041AddOPMass(by,codOP,scale=1){
  if(!(scale>0)||!codOP)return;
  const planned=(data.op_materiais||[]).filter(x=>x.CodOP===codOP&&!String(x.TipoConsumo||'').toLowerCase().includes('pi intermedi'));
  const actual=(data.consumos_materiais||[]).filter(x=>x.CodOP===codOP);
  const etapas=(data.op_etapas||[]).filter(e=>e.CodOP===codOP);
  const pmap={};etapas.forEach(e=>pmap[String(e.Ordem||e.OrdemEtapa||'')]=e.Processo||e.Etapa||'');
  const actualBy={};
  actual.forEach(x=>{const cod=x.CodigoMaterial||'';if(!cod)return;actualBy[cod]=actualBy[cod]||{q:0,desc:x.DescricaoMaterial||'',proc:x.Processo||x.Etapa||''};actualBy[cod].q+=v4034QuantityForMaterialRecord(x);});
  const used=new Set();
  planned.forEach(x=>{const cod=x.CodigoMaterial||'';if(!cod||used.has(cod))return;used.add(cod);const a=actualBy[cod],q=a&&a.q>0?a.q:v4034QuantityForMaterialRecord(x),proc=(a&&a.proc)||x.Processo||x.Etapa||pmap[String(x.Ordem||x.OrdemEtapa||'')]||'';v4041AddMass(by,cod,(a&&a.desc)||x.DescricaoMaterial||'',q,proc,scale);});
  Object.entries(actualBy).forEach(([cod,a])=>{if(!used.has(cod))v4041AddMass(by,cod,a.desc,a.q,a.proc,scale);});
}
function v4041ProcessMassRows(bp){
  const saved=v4041MassFromSavedAudit(bp);if(saved)return saved;
  const by={},fam=v4041FamilyForBP(bp);fam.ops.forEach(o=>v4041AddOPMass(by,o.CodOP,1));
  const stem=v4035StemOP(fam.root),inherited=(data.op_pi_consumos||[]).filter(c=>[fam.root,stem].includes(String(c.CodOPPA||''))&&String(c.Status||'ATIVO').toUpperCase()!=='CANCELADO');
  inherited.forEach(c=>{const lot=(data.pi_lotes||[]).find(l=>l.IdLotePI===c.IdLotePI)||{},src=opPorCodigo(c.CodOPOrigemPI||lot.CodOPOrigem)||{},produced=v403Produced(src)||num(lot.QuantidadeProduzida),cons=num(c.QuantidadeConsumida),scale=produced>0?cons/produced:0;if(scale>0)v4041AddOPMass(by,src.CodOP||c.CodOPOrigemPI,scale);});
  const rows=Object.values(by).map(x=>({...x,Processos:[...x.Processos].join('; ')})),total=rows.reduce((s,x)=>s+x.MassaKg,0);
  rows.forEach(x=>x.PercentualMassa=total?x.MassaKg/total*100:0);rows.sort((a,b)=>b.MassaKg-a.MassaKg);
  return {rows,total,fonte:'apontamentos/OPs'};
}

v4033MaterialMassRows=v4041ProcessMassRows;
v4034MaterialMassRows=v4041ProcessMassRows;

v4033PieHTML=function(bp){
  const d=v4041ProcessMassRows(bp);if(!d.rows.length)return '<div class="muted">Não há massa convertível registrada para a família desta OP.</div>';
  let acc=0;const colors=['#0b5ea8','#39a935','#78b82a','#1f7a8c','#f2a900','#6c5ce7','#00a8a8','#d35400','#7f8c8d','#2d98da','#8854d0','#20bf6b','#3867d6','#eb3b5a'];
  const stops=d.rows.map((x,i)=>{const a=acc,b=acc+x.PercentualMassa;acc=b;return `${colors[i%colors.length]} ${a}% ${b}%`;}).join(',');
  const legend=d.rows.map((x,i)=>`<div class="v4041-mass-row"><i style="background:${colors[i%colors.length]}"></i><span title="${htmlEscape(x.Processos||'')}">${htmlEscape(x.Material)}</span><b>${v4034FormatNumber(x.PercentualMassa,3)}%</b><small>${v4034FormatNumber(x.MassaKg,3)} kg</small></div>`).join('');
  return `<div class="v4041-pie-wrap"><div class="v4041-pie" style="background:conic-gradient(${stops})"><span>${v4034FormatNumber(d.total,3)}<small>kg</small></span></div><div class="v4041-pie-legend">${legend}</div></div><div class="v4041-mass-source">Massa total envolvida nos processos da família PA + PI · fonte: ${htmlEscape(d.fonte)}</div>`;
};

v4033PassportMetrics=function(bp){
  const root=v4034RootPAForBP(bp),s=v4041SavedRootRow(data.sust_op,root)||{},c=v4041SavedRootRow(data.custos_op,root)||{},prod=produtoPorCodigo(bp.CodProduto)||{},mass=v4041ProcessMassRows(bp).total,co2=num(s.CO2eqTotal),energyKWh=num(prod['Energia (Wh)'])/1000,totalCost=num(c.CustoTotal);
  return {co2,energyKWh,co2PerKWh:energyKWh>0&&co2>0?co2/energyKWh:null,co2PerReal:totalCost>0&&co2>0?co2/totalCost:null,costPerKg:mass>0&&totalCost>0?totalCost/mass:null,mass,totalCost};
};

// Passaporte leve: não chama versões anteriores de showBP, que recalculavam custos/ACV.
showBP=function(){
  const id=$('bp_sel')?.value||val(data.bp[0]||{},['BatteryPassportID']);if($('bp_sel'))$('bp_sel').value=id;
  const bp=(data.bp||[]).find(b=>b.BatteryPassportID==id)||{};if(!$('bpDet'))return;if(!bp.BatteryPassportID){$('bpDet').innerHTML='';return;}
  const op=opPorCodigo(bp.CodOrdemProducao)||{},prod=produtoPorCodigo(bp.CodProduto)||{},m=v4033PassportMetrics(bp),mass=v4041ProcessMassRows(bp);
  const rows=mass.rows.map(x=>({Codigo:x.CodigoMaterial,Material:x.Material,Processos:x.Processos,MassaKg:v4034FormatNumber(x.MassaKg,3),Percentual:v4034FormatNumber(x.PercentualMassa,3)+'%'}));
  $('bpDet').innerHTML=`<div class="card v4041-passport-lite"><div class="v4041-pass-head"><div><b>${htmlEscape(bp.BatteryPassportID||'Passaporte')}</b><span>${htmlEscape(bp.CodProduto||'')} · ${htmlEscape(op.DescricaoProduto||prod['Descrição']||'')}</span></div><span class="${bpStatusClass(bp.StatusPassaporte)}">${htmlEscape(bp.StatusPassaporte||'')}</span></div><div class="v4041-kpis"><div><small>Massa total envolvida nos processos</small><b>${v4033MetricValue(m.mass,' kg')}</b></div><div><small>CO₂eq/kWh</small><b>${v4033MetricValue(m.co2PerKWh,' kg CO₂eq/kWh')}</b></div><div><small>CO₂eq/R$</small><b>${v4033MetricValue(m.co2PerReal,' kg CO₂eq/R$')}</b></div><div><small>R$/kg</small><b>${v4033MetricValue(m.costPerKg,' R$/kg')}</b></div></div><h3>Composição de massa de todos os insumos processados</h3>${v4033PieHTML(bp)}<details class="v4041-pass-details"><summary>Relação auditável das massas</summary>${tableHTML(rows,['Codigo','Material','Processos','MassaKg','Percentual'])}</details><details class="v4041-pass-details"><summary>Identificação do passaporte</summary>${kvHTML({...bp,DescricaoProduto:prod['Descrição']||op.DescricaoProduto||''},['BatteryPassportID','BatteryPassportGUID','CodOrdemProducao','CodProduto','DescricaoProduto','IDLote','ClienteNomeSnapshot','StatusPassaporte','VersaoPassaporte'])}</details></div>`;
};

// HOME: nenhuma imagem, texto ou cálculo; somente fundo claro.
v4040Home=function(){
  current='home';document.body.classList.remove('dashboard-mode');document.body.classList.add('v4041-home-blank');
  document.querySelectorAll('nav button').forEach(b=>b.classList.remove('active'));document.getElementById('nav_home')?.classList.add('active');
  if($('title'))$('title').textContent='';if($('subtitle'))$('subtitle').textContent='';if($('content'))$('content').innerHTML='<div class="v4041-home-empty" aria-label="Página inicial"></div>';
};
const _renderV4041=render;
render=function(k){
  if(!k||k==='dashboard'||k==='home')return v4040Home();
  document.body.classList.remove('v4041-home-blank');return _renderV4041(k);
};
