/* =========================================================
   MES LION V40.4.2 — PASSAPORTE CLIENTE: GRÁFICO VISUAL + CO2eq TOTAL
   - Dashboard/HTML/PDF do cliente usa a mesma composição visual do módulo interno;
   - estilos do gráfico são inline para sobreviver à exportação HTML e impressão;
   - substitui CO₂eq/R$ no cliente por CO₂eq total (kg);
   - indicadores internos de gestão permanecem inalterados;
   - reutiliza a massa consolidada V40.4.1, sem novos recálculos pesados.
   ========================================================= */
const APP_PATCH_V4042='v40.4.2-cliente-pie-inline-co2-total';

function v4042PublicPieHTML(bp){
  const d=v4041ProcessMassRows(bp);
  if(!d.rows.length)return '<div style="color:#6d7d8c;font-size:12px;padding:8px 0">Não há massa convertível registrada para a família desta OP.</div>';
  let acc=0;
  const colors=['#0b5ea8','#39a935','#78b82a','#1f7a8c','#f2a900','#6c5ce7','#00a8a8','#d35400','#7f8c8d','#2d98da','#8854d0','#20bf6b','#3867d6','#eb3b5a'];
  const stops=d.rows.map((x,i)=>{const a=acc,b=acc+x.PercentualMassa;acc=b;return `${colors[i%colors.length]} ${a}% ${b}%`;}).join(',');
  const legend=d.rows.map((x,i)=>`<div style="display:grid;grid-template-columns:10px minmax(150px,1fr) 75px 72px;gap:7px;align-items:center;border-bottom:1px solid #eaf0f5;padding:5px 0;font-size:11px;line-height:1.15"><i style="width:8px;height:8px;border-radius:50%;background:${colors[i%colors.length]}"></i><span style="color:#24435a;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${htmlEscape(x.Processos||'')}">${htmlEscape(x.Material)}</span><b style="color:#0b4d80;text-align:right">${v4034FormatNumber(x.PercentualMassa,3)}%</b><small style="color:#6d7d8c;text-align:right">${v4034FormatNumber(x.MassaKg,3)} kg</small></div>`).join('');
  return `<div style="display:grid;grid-template-columns:170px minmax(360px,1fr);gap:22px;align-items:center;padding:8px 2px;max-width:900px"><div style="width:150px;height:150px;border-radius:50%;position:relative;margin:auto;background:conic-gradient(${stops});box-shadow:inset 0 0 0 1px #d8e4ef"><div style="position:absolute;inset:27%;background:#fff;border-radius:50%;box-shadow:0 0 0 1px #d8e4ef"></div><div style="position:absolute;z-index:2;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;font-weight:800;color:#0b4d80;font-size:17px">${v4034FormatNumber(d.total,3)}<small style="font-size:10px;font-weight:600;color:#667">kg</small></div></div><div style="max-height:190px;overflow:auto;padding-right:4px">${legend}</div></div><div style="font-size:10px;color:#6d7d8c;margin-top:4px">Massa total envolvida nos processos da família PA + PI · fonte: ${htmlEscape(d.fonte)}</div>`;
}

bpDashboardBody=function(bp){
  const prod=produtoPorCodigo(bp.CodProduto)||{},op=opPorCodigo(bp.CodOrdemProducao)||{},mats=bpPublicMaterialRowsV401(bp),filhos=(data.estrutura||[]).filter(p=>p['Código Pai']==bp.CodProduto),descricao=prod['Descrição']||op.DescricaoProduto||op.Produto||'',met=v4033PassportMetrics(bp),line=v403PILineageRowsForBP(bp);
  return `<div class="dash-public passport-public"><section class="passport-hero"><div><span class="eyebrow">DIGITAL BATTERY PASSPORT</span><h1>${htmlEscape(descricao||bp.CodProduto||'Bateria')}</h1><p>${htmlEscape(bp.CodProduto||'')} · ${htmlEscape(bp.IDLote||'Lote da bateria não informado')}</p></div><div class="passport-status"><span>${htmlEscape(bp.StatusPassaporte||'RASCUNHO')}</span><b>${htmlEscape(bp.BatteryPassportID||'')}</b></div></section><div class="kpis passport-kpis"><div class="kpi"><b>Produto</b><span>${htmlEscape(bp.CodProduto||'-')}</span></div><div class="kpi"><b>OP de origem</b><span>${htmlEscape(bp.CodOrdemProducao||'-')}</span></div><div class="kpi"><b>CO₂eq/kWh</b><span>${v4033MetricValue(met.co2PerKWh,' kg CO₂eq/kWh')}</span></div><div class="kpi"><b>Emissões totais</b><span>${v4033MetricValue(met.co2,' kg CO₂eq')}</span></div></div><section class="passport-section"><h2>Composição mássica da célula completa</h2>${v4042PublicPieHTML(bp)}</section><details open class="passport-section"><summary><b>Identificação e rastreabilidade</b></summary>${kvHTML({...bp,DescricaoProduto:descricao},['BatteryPassportID','BatteryPassportGUID','CodOrdemProducao','CodProduto','DescricaoProduto','IDLote','ClienteNomeSnapshot','StatusPassaporte','VersaoPassaporte'])}<h2>Materiais, lotes e fornecedores</h2>${tableHTML(mats,['OP','Etapa','CodigoMaterial','Material','Quantidade','UM','Lote','Fornecedor','NotaFiscal'])}${line.length?`<h2>Lotes de produtos intermediários</h2>${tableHTML(line,['PI','Descrição','LotePI','OPOrigem','Quantidade','UM','DataProdução'])}`:''}</details><details class="passport-section" open><summary><b>Dados técnicos e desempenho</b></summary>${kvHTML({...prod,...bp},['Célula','Composição','Modelo','Capacidade Final (Ah)','Tensão Nominal (V)','Energia (Wh)','Tec_VidaUtil_Texto','Tec_ResistenciaInterna_Texto','Tec_RoundTripEfficiency_Texto','Tec_FaixaTemperatura_Texto'])}</details><details class="passport-section"><summary><b>Qualificação da bateria</b></summary><div class="bp-img-grid">${imageBlock('Imagem da bateria',bp.ImagemBateria)}${imageBlock('Teste de ciclos',bp.ImagemTesteCiclos)}${imageBlock('Teste de impedância',bp.ImagemImpedancia||bp.Tec_ResistenciaInterna_ImagemPath)}${imageBlock('Teste de aging',bp.ImagemAging)}</div></details><details class="passport-section" open><summary><b>Sustentabilidade e conformidade</b></summary>${kvHTML(bp,['Sust_CarbonFootprint_Texto','Sust_DueDiligence_Texto','Sust_ConteudoReciclado_Texto','Sust_ConteudoRenovavel_Texto','Comp_DeclaracaoUE_Texto','Eng_Seguranca_Texto'])}</details><section class="passport-section two"><div><h2>Estrutura PA → PI</h2>${tableHTML(filhos,['Código','Descrição','Tipo Produto','Código Pai','Composição','Modelo'])}</div>${qrCardHTML(bp,'Consultar relatório digital')}</section></div>`;
};

reportBPObj=function(bp){
  if(bp&&typeof bp.then==='function')return bp.then(reportBPObj);if(!bp||!bp.BatteryPassportID)return alert('Selecione ou salve um passaporte antes de gerar o PDF.');
  const prod=produtoPorCodigo(bp.CodProduto)||{},op=opPorCodigo(bp.CodOrdemProducao)||{},filhos=(data.estrutura||[]).filter(p=>p['Código Pai']==bp.CodProduto),mats=bpPublicMaterialRowsV401(bp),descricao=prod['Descrição']||op.DescricaoProduto||op.Produto||'',met=v4033PassportMetrics(bp),line=v403PILineageRowsForBP(bp);
  const body=`<div class="kpis"><div class="kpi"><b>Produto</b><span>${htmlEscape(bp.CodProduto||'-')}</span></div><div class="kpi"><b>OP</b><span>${htmlEscape(bp.CodOrdemProducao||'-')}</span></div><div class="kpi"><b>CO₂eq/kWh</b><span>${v4033MetricValue(met.co2PerKWh,' kg CO₂eq/kWh')}</span></div><div class="kpi"><b>Emissões totais</b><span>${v4033MetricValue(met.co2,' kg CO₂eq')}</span></div></div><section class="passport-section"><h2>Composição mássica da célula completa</h2>${v4042PublicPieHTML(bp)}</section><section class="passport-section"><h2>1. Identificação</h2>${kvHTML({...bp,DescricaoProduto:descricao},['BatteryPassportID','BatteryPassportGUID','CodProduto','DescricaoProduto','IDLote','VersaoEngenharia','CodOrdemProducao','ClienteNomeSnapshot','DataCriacao','DataUltimaAlteracao'])}</section><section class="passport-section"><h2>2. Materiais, lotes e fornecedores</h2>${tableHTML(mats,['OP','Etapa','CodigoMaterial','Material','Quantidade','UM','Lote','Fornecedor','NotaFiscal'])}</section>${line.length?`<section class="passport-section"><h2>3. Lotes de produtos intermediários</h2>${tableHTML(line,['PI','Descrição','LotePI','OPOrigem','Quantidade','UM','DataProdução'])}</section>`:''}<section class="passport-section"><h2>4. Dados técnicos</h2>${kvHTML(prod,['Código','Descrição','Tipo Produto','Célula','Composição','Modelo','Capacidade Final (Ah)','Tensão Nominal (V)','Energia (Wh)','Dimensão Case'])}</section><section class="passport-section"><h2>5. Desempenho e segurança</h2>${kvHTML(bp,['Tec_VidaUtil_Texto','Tec_FaixaTemperatura_Texto','Tec_RoundTripEfficiency_Texto','Tec_ResistenciaInterna_Texto','Eng_Desmontagem_Texto','Eng_Seguranca_Texto'])}</section><section class="passport-section"><h2>6. Sustentabilidade</h2>${kvHTML(bp,['Sust_CarbonFootprint_Texto','Sust_DueDiligence_Texto','Sust_ConteudoReciclado_Texto','Comp_DeclaracaoUE_Texto'])}</section><section class="passport-section"><h2>7. Estrutura PA → PI</h2>${tableHTML(filhos,['Código','Descrição','Tipo Produto','Código Pai','Composição','Modelo'])}</section>`;
  passportPrintShell('Passaporte da Bateria',bp,body);
};

try{data.meta=data.meta||{};data.meta.patchV4042=APP_PATCH_V4042;}catch(e){}

/* =========================================================
   MES LION V40.4.3 — DASHBOARD CLIENTE INTERATIVO + TEXTOS DE VALIDAÇÃO
   - exportação HTML mantém seções expansíveis nativas (<details>);
   - composição mássica traz gráfico + detalhamento percentual expansível;
   - imagens de qualificação ficam em seção expansível e permanecem embutidas no HTML;
   - QR removido do dashboard/relatório do cliente (permanece na etiqueta/validação interna);
   - textos genéricos de validação preenchidos apenas quando os campos estão vazios;
   - sem bibliotecas externas e sem novos cálculos pesados.
   ========================================================= */
const APP_PATCH_V4043='v40.4.3-client-html-interactive-generic-validation';

const V4043_BP_GENERIC_TEXTS={
  Sust_DueDiligence_Texto:'Texto de validação: fornecedores avaliados conforme critérios internos de qualidade, origem dos materiais, conformidade ambiental e requisitos de responsabilidade na cadeia de fornecimento.',
  Sust_ConteudoReciclado_Texto:'Texto de validação: conteúdo reciclado declarado para os materiais aplicáveis, conforme documentação e rastreabilidade dos respectivos fornecedores.',
  Sust_ConteudoRenovavel_Texto:'Texto de validação: conteúdo de origem renovável informado para os insumos aplicáveis, conforme documentação dos respectivos fornecedores.',
  Comp_DeclaracaoUE_Texto:'Texto de validação: produto avaliado quanto aos requisitos aplicáveis de conformidade para baterias, sujeito à validação documental e emissão formal da declaração correspondente.',
  Eng_Seguranca_Texto:'Texto de validação: manter a bateria protegida contra impactos, perfuração, curto-circuito, temperaturas elevadas e exposição direta ao fogo. Utilizar somente dentro das condições especificadas para o produto.'
};
function v4043ApplyGenericBPFields(bp){
  if(!bp||typeof bp!=='object')return bp;
  Object.entries(V4043_BP_GENERIC_TEXTS).forEach(([k,v])=>{if(!String(bp[k]||'').trim())bp[k]=v;});
  return bp;
}
function v4043FillGenericBPForm(){
  const map={bp_dd:'Sust_DueDiligence_Texto',bp_rec:'Sust_ConteudoReciclado_Texto',bp_ren:'Sust_ConteudoRenovavel_Texto',bp_ue:'Comp_DeclaracaoUE_Texto',bp_seg:'Eng_Seguranca_Texto'};
  Object.entries(map).forEach(([id,key])=>{const el=$(id);if(el&&!String(el.value||'').trim())el.value=V4043_BP_GENERIC_TEXTS[key];});
}
const _openBPFormV4043=openBPForm;
openBPForm=function(idx=-1){
  const r=_openBPFormV4043(idx);
  v4043FillGenericBPForm();
  return r;
};
const _bpModuleV4043=bpModule;
bpModule=function(){
  (data.bp||[]).forEach(v4043ApplyGenericBPFields);
  return _bpModuleV4043();
};

function v4043ClientMetrics(bp){
  const root=v4034RootPAForBP(bp),s=v4041SavedRootRow(data.sust_op,root)||{},prod=produtoPorCodigo(bp.CodProduto)||{};
  const co2=num(s.CO2eqTotal),energyKWh=num(prod['Energia (Wh)'])/1000;
  return {co2,co2PerKWh:energyKWh>0&&co2>0?co2/energyKWh:null};
}
function v4043PublicPieFromData(d){
  if(!d||!d.rows||!d.rows.length)return '<div style="color:#6d7d8c;font-size:12px;padding:8px 0">Não há massa convertível registrada para a família desta OP.</div>';
  let acc=0;
  const colors=['#0b5ea8','#39a935','#78b82a','#1f7a8c','#f2a900','#6c5ce7','#00a8a8','#d35400','#7f8c8d','#2d98da','#8854d0','#20bf6b','#3867d6','#eb3b5a'];
  const stops=d.rows.map((x,i)=>{const a=acc,b=acc+x.PercentualMassa;acc=b;return `${colors[i%colors.length]} ${a}% ${b}%`;}).join(',');
  const legend=d.rows.map((x,i)=>`<div style="display:grid;grid-template-columns:10px minmax(150px,1fr) 75px 72px;gap:7px;align-items:center;border-bottom:1px solid #eaf0f5;padding:5px 0;font-size:11px;line-height:1.15"><i style="width:8px;height:8px;border-radius:50%;background:${colors[i%colors.length]}"></i><span style="color:#24435a;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${htmlEscape(x.Processos||'')}">${htmlEscape(x.Material)}</span><b style="color:#0b4d80;text-align:right">${v4034FormatNumber(x.PercentualMassa,3)}%</b><small style="color:#6d7d8c;text-align:right">${v4034FormatNumber(x.MassaKg,3)} kg</small></div>`).join('');
  return `<div style="display:grid;grid-template-columns:170px minmax(300px,1fr);gap:22px;align-items:center;padding:8px 2px;max-width:900px"><div style="width:150px;height:150px;border-radius:50%;position:relative;margin:auto;background:conic-gradient(${stops});box-shadow:inset 0 0 0 1px #d8e4ef"><div style="position:absolute;inset:27%;background:#fff;border-radius:50%;box-shadow:0 0 0 1px #d8e4ef"></div><div style="position:absolute;z-index:2;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;font-weight:800;color:#0b4d80;font-size:17px">${v4034FormatNumber(d.total,3)}<small style="font-size:10px;font-weight:600;color:#667">kg</small></div></div><div style="max-height:190px;overflow:auto;padding-right:4px">${legend}</div></div><div style="font-size:10px;color:#6d7d8c;margin-top:4px">Massa total envolvida nos processos da família PA + PI · fonte: ${htmlEscape(d.fonte)}</div>`;
}
function v4043MassAuditHTML(d){
  const rows=(d?.rows||[]).map(x=>({
    Código:x.CodigoMaterial||'',
    Material:x.Material||'',
    Processos:x.Processos||'',
    'Massa (kg)':v4034FormatNumber(x.MassaKg,3),
    'Percentual (%)':v4034FormatNumber(x.PercentualMassa,3)
  }));
  return rows.length?tableHTML(rows,['Código','Material','Processos','Massa (kg)','Percentual (%)']):'<div class="muted">Sem dados de massa.</div>';
}

bpDashboardBody=function(bp){
  const view=v4043ApplyGenericBPFields({...bp});
  const prod=produtoPorCodigo(view.CodProduto)||{},op=opPorCodigo(view.CodOrdemProducao)||{},mats=bpPublicMaterialRowsV401(view),filhos=(data.estrutura||[]).filter(p=>p['Código Pai']==view.CodProduto),descricao=prod['Descrição']||op.DescricaoProduto||op.Produto||'',met=v4043ClientMetrics(view),line=v403PILineageRowsForBP(view),mass=v4041ProcessMassRows(view);
  return `<div class="dash-public passport-public">
    <section class="passport-hero"><div><span class="eyebrow">DIGITAL BATTERY PASSPORT</span><h1>${htmlEscape(descricao||view.CodProduto||'Bateria')}</h1><p>${htmlEscape(view.CodProduto||'')} · ${htmlEscape(view.IDLote||'Lote da bateria não informado')}</p></div><div class="passport-status"><span>${htmlEscape(view.StatusPassaporte||'RASCUNHO')}</span><b>${htmlEscape(view.BatteryPassportID||'')}</b></div></section>
    <div class="kpis passport-kpis"><div class="kpi"><b>Produto</b><span>${htmlEscape(view.CodProduto||'-')}</span></div><div class="kpi"><b>OP de origem</b><span>${htmlEscape(view.CodOrdemProducao||'-')}</span></div><div class="kpi"><b>CO₂eq/kWh</b><span>${v4033MetricValue(met.co2PerKWh,' kg CO₂eq/kWh')}</span></div><div class="kpi"><b>Emissões totais</b><span>${v4033MetricValue(met.co2,' kg CO₂eq')}</span></div></div>
    <section class="passport-section"><h2>Composição mássica da célula completa</h2>${v4043PublicPieFromData(mass)}</section>
    <details class="passport-section passport-toggle"><summary><b>Detalhamento percentual da composição mássica</b><span>expandir/recolher</span></summary><div class="passport-detail-body">${v4043MassAuditHTML(mass)}</div></details>
    <details open class="passport-section passport-toggle"><summary><b>Identificação e rastreabilidade</b><span>expandir/recolher</span></summary><div class="passport-detail-body">${kvHTML({...view,DescricaoProduto:descricao},['BatteryPassportID','BatteryPassportGUID','CodOrdemProducao','CodProduto','DescricaoProduto','IDLote','ClienteNomeSnapshot','StatusPassaporte','VersaoPassaporte'])}<h2>Materiais, lotes e fornecedores</h2>${tableHTML(mats,['OP','Etapa','CodigoMaterial','Material','Quantidade','UM','Lote','Fornecedor','NotaFiscal'])}${line.length?`<h2>Lotes de produtos intermediários</h2>${tableHTML(line,['PI','Descrição','LotePI','OPOrigem','Quantidade','UM','DataProdução'])}`:''}</div></details>
    <details class="passport-section passport-toggle"><summary><b>Qualificação da bateria e imagens</b><span>expandir/recolher</span></summary><div class="passport-detail-body"><div class="bp-img-grid">${imageBlock('Imagem da bateria',view.ImagemBateria)}${imageBlock('Teste de ciclos',view.ImagemTesteCiclos)}${imageBlock('Teste de impedância',view.ImagemImpedancia||view.Tec_ResistenciaInterna_ImagemPath)}${imageBlock('Teste de aging',view.ImagemAging)}</div></div></details>
    <details open class="passport-section passport-toggle"><summary><b>Dados técnicos e desempenho</b><span>expandir/recolher</span></summary><div class="passport-detail-body">${kvHTML({...prod,...view},['Célula','Composição','Modelo','Capacidade Final (Ah)','Tensão Nominal (V)','Energia (Wh)','Tec_VidaUtil_Texto','Tec_ResistenciaInterna_Texto','Tec_RoundTripEfficiency_Texto','Tec_FaixaTemperatura_Texto'])}</div></details>
    <details open class="passport-section passport-toggle"><summary><b>Sustentabilidade e conformidade</b><span>expandir/recolher</span></summary><div class="passport-detail-body">${kvHTML(view,['Sust_CarbonFootprint_Texto','Sust_DueDiligence_Texto','Sust_ConteudoReciclado_Texto','Sust_ConteudoRenovavel_Texto','Comp_DeclaracaoUE_Texto','Eng_Seguranca_Texto'])}</div></details>
    <section class="passport-section"><h2>Estrutura PA → PI</h2>${tableHTML(filhos,['Código','Descrição','Tipo Produto','Código Pai','Composição','Modelo'])}</section>
  </div>`;
};

standaloneDashboardHTML=function(bp){
  const title='Passaporte Digital da Bateria — '+(bp.BatteryPassportID||'');
  const body=bpDashboardBody(bp);
  const css=`*{box-sizing:border-box}body{font-family:Arial,Helvetica,sans-serif;margin:0;background:#edf2f6;color:#172a3a}.page{max-width:1180px;margin:auto;padding:24px}.head{background:linear-gradient(110deg,#003b70,#0067a8);color:white;border-radius:18px;padding:20px;display:grid;grid-template-columns:190px 1fr;gap:20px;align-items:center}.head img{width:180px;max-height:65px;object-fit:contain;background:white;border-radius:9px;padding:5px}.head h1{margin:0;font-size:25px}.head p{margin:6px 0 0;opacity:.9}.dash-public{background:white;border:1px solid #d8e3eb;border-radius:18px;padding:20px;margin-top:16px}.passport-hero{display:flex;justify-content:space-between;gap:18px;align-items:center;padding-bottom:16px;border-bottom:1px solid #dfe8ee}.passport-hero h1{margin:4px 0;color:#003b70}.passport-hero p{margin:0;color:#5e7484}.eyebrow{font-size:11px;color:#5b8e22;font-weight:800;letter-spacing:.13em}.passport-status{text-align:right}.passport-status span{display:inline-block;background:#73b72b;color:white;border-radius:999px;padding:7px 11px;font-size:11px;font-weight:800}.passport-status b{display:block;color:#003b70;margin-top:8px}.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;margin:16px 0}.kpi{background:#f5f8fa;border:1px solid #dfe8ee;border-radius:13px;padding:13px}.kpi b{display:block;color:#607786;font-size:11px;text-transform:uppercase}.kpi span{display:block;color:#003b70;font-size:20px;font-weight:800;margin-top:6px;overflow-wrap:anywhere}.passport-section{margin-top:16px}.passport-section h2{color:#003b70;border-bottom:2px solid #72b62b;padding-bottom:7px}.passport-toggle{border:1px solid #dfe8ee;border-radius:12px;background:#fff;overflow:hidden}.passport-toggle>summary{list-style:none;cursor:pointer;padding:12px 14px;display:flex;justify-content:space-between;align-items:center;gap:14px;color:#003b70;background:#f7fafc;user-select:none}.passport-toggle>summary::-webkit-details-marker{display:none}.passport-toggle>summary:before{content:'+';display:inline-flex;align-items:center;justify-content:center;width:22px;height:22px;border-radius:50%;background:#0b5ea8;color:#fff;font-weight:800;flex:0 0 auto}.passport-toggle[open]>summary:before{content:'−';background:#39a935}.passport-toggle>summary b{flex:1}.passport-toggle>summary span{font-size:10px;color:#6a7e8c;font-weight:normal}.passport-detail-body{padding:12px 14px}.kv{width:100%;border-collapse:collapse}.kv td{padding:8px;border-bottom:1px solid #e7edf1}.kv td:first-child{font-weight:700;color:#31566f;width:36%;background:#f8fafb}table{width:100%;border-collapse:collapse;font-size:12px}th,td{border:1px solid #e0e8ed;padding:7px;text-align:left}th{background:#eaf2f7;color:#003b70}.bp-img-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px}.bp-img-card{border:1px solid #dfe8ee;border-radius:13px;padding:10px;text-align:center}.bp-img-card b{display:block;text-align:left;color:#003b70;margin-bottom:8px}.bp-img-card img{width:100%;height:260px;object-fit:contain}.img-empty{height:200px;display:flex;align-items:center;justify-content:center;background:#f1f5f7;color:#718490;border-radius:9px}@media(max-width:760px){.page{padding:10px}.head{grid-template-columns:1fr}.passport-hero{display:block}.passport-status{text-align:left;margin-top:12px}.passport-toggle>summary span{display:none}}`;
  return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${htmlEscape(title)}</title><style>${css}</style></head><body><div class="page"><header class="head"><img src="${MES_LION_LOGO_DATA_URI}"><div><h1>${htmlEscape(title)}</h1><p>Sistema FIEP · SENAI — identificação, desempenho, rastreabilidade e sustentabilidade</p></div></header>${body}</div></body></html>`;
};

try{
  (data.bp||[]).forEach(v4043ApplyGenericBPFields);
  data.meta=data.meta||{};data.meta.patchV4043=APP_PATCH_V4043;
}catch(e){}

/* ============================================================
   MES LION V40.4.4 — UMA ÚNICA VISUALIZAÇÃO DO PASSAPORTE
   - Dashboard cliente, HTML exportado e QR da etiqueta usam o MESMO HTML.
   - O QR não reutiliza PDF/link antigo: publica a versão HTML atual no servidor MES.
   - A publicação local é acessível pelo celular na mesma rede do computador.
   ============================================================ */
function v4044SelectedBP(){
  const id=$('bp_sel')?.value||val(data.bp?.[0]||{},['BatteryPassportID']);
  return (data.bp||[]).find(b=>String(b.BatteryPassportID||'')===String(id||''));
}
async function v4044PublishDashboard(bp, html=null, quiet=false){
  if(!bp?.BatteryPassportID) throw new Error('Selecione um passaporte.');
  const content=html||standaloneDashboardHTML(bp);
  const r=await fetch('/api/passport-publish',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:bp.BatteryPassportID,html:content})});
  if(!r.ok) throw new Error(await r.text()||'Falha ao publicar o dashboard HTML.');
  const out=await r.json();
  if(!out?.url) throw new Error('O servidor não retornou a URL do dashboard.');
  bp.URLPassaporteWeb=out.url;
  bp.URLDashboardCliente=out.url;
  bp.TipoPublicacaoPassaporte='HTML_INTERATIVO_MES';
  bp.DataPublicacaoHTML=new Date().toLocaleString('pt-BR');
  saveLocal();
  if(!quiet) alert('Dashboard HTML atualizado para o QR.\n\n'+out.url+'\n\nNo celular, use a mesma rede do computador que executa o MES.');
  return {url:out.url,html:content};
}
function v4044IsPdfLikeUrl(u){return /\.pdf(?:$|[?#])|application\/pdf|download.*pdf/i.test(String(u||''));}

exportBPDashboardHTML=async function(){
  const bp=v4044SelectedBP();
  if(!bp)return alert('Selecione um passaporte.');
  try{
    const html=standaloneDashboardHTML(bp);
    await v4044PublishDashboard(bp,html,true);
    downloadTextFile('dashboard_cliente_'+(bp.BatteryPassportID||'BP')+'.html',html);
    showBP();
  }catch(e){alert('Não foi possível gerar/publicar o HTML do cliente.\n\n'+(e?.message||e));}
};

copyBPLink=async function(){
  const bp=v4044SelectedBP();
  if(!bp)return alert('Selecione um passaporte.');
  try{
    const pub=await v4044PublishDashboard(bp,null,true);
    if(navigator.clipboard?.writeText) await navigator.clipboard.writeText(pub.url);
    else prompt('Copie o link:',pub.url);
    showBP();
    alert('Link do mesmo dashboard HTML usado pelo QR copiado.');
  }catch(e){alert('Não foi possível atualizar o link/QR HTML.\n\n'+(e?.message||e));}
};

printBPProductLabel=async function(){
  const bp=v4044SelectedBP();
  if(!bp)return alert('Selecione um passaporte para imprimir a etiqueta.');
  const w=window.open('','_blank','width=520,height=820');
  if(!w)return alert('Permita pop-ups para imprimir a etiqueta.');
  w.document.write('<!doctype html><html><body style="font-family:Arial;padding:30px">Atualizando o dashboard HTML e o QR Code…</body></html>');
  w.document.close();
  try{
    const pub=await v4044PublishDashboard(bp,null,true);
    const prod=produtoPorCodigo(bp.CodProduto)||{},op=opPorCodigo(bp.CodOrdemProducao)||{};
    const nome=prod['Descrição']||op.DescricaoProduto||op.Produto||bp.CodProduto||'Bateria';
    const qr=qrUrlFor(pub.url);
    w.document.open();
    w.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Etiqueta ${htmlEscape(bp.CodProduto||'')}</title><style>
      @page{size:90mm 150mm;margin:0}*{box-sizing:border-box}html,body{width:90mm;height:150mm;margin:0;padding:0;font-family:Arial,Helvetica,sans-serif;color:#102b3c;background:white}body{display:flex;align-items:stretch}.label{width:90mm;height:150mm;padding:5mm;border:.45mm solid #004b87;display:flex;flex-direction:column;overflow:hidden}.top{display:grid;grid-template-columns:18mm 1fr;gap:3mm;align-items:center;border-bottom:1mm solid #69ad2c;padding-bottom:3mm}.top img{width:17mm;height:10mm;object-fit:contain}.manufacturer{font-size:3mm;line-height:1.3;text-align:right;color:#355566}.manufacturer b{display:block;color:#004b87;font-size:3.4mm}.product{padding:4mm 0 2mm}.product .ey{font-size:2.6mm;letter-spacing:.12em;font-weight:700;color:#69ad2c}.product h1{font-size:6mm;line-height:1.08;margin:1.5mm 0 2mm;color:#003f73;overflow-wrap:anywhere}.code{background:#eaf2f7;border-left:2mm solid #004b87;padding:2.5mm 3mm;font-size:3.2mm}.code strong{font-size:4.6mm;display:block;margin-top:1mm}.client{padding:3mm 0;font-size:3mm;border-bottom:.4mm solid #d7e2e8}.client b{display:block;color:#004b87;font-size:3.4mm;margin-top:1mm}.qrwrap{flex:1;display:flex;align-items:center;justify-content:center;flex-direction:column;padding-top:2mm}.qrwrap img{width:49mm;height:49mm;object-fit:contain}.qrwrap span{font-size:2.8mm;text-align:center;color:#476273;margin-top:2mm}.foot{border-top:.5mm solid #d7e2e8;padding-top:2mm;font-size:2.6mm;display:flex;justify-content:space-between;gap:2mm}.print{position:fixed;right:10px;top:10px;padding:8px 12px}@media print{.print{display:none}}
    </style></head><body><button class="print" onclick="window.print()">Imprimir</button><main class="label"><header class="top"><img src="${MES_LION_LOGO_DATA_URI}"><div class="manufacturer"><b>SENAI · ISI Eletroquímica</b>Curitiba · Paraná<br>Fabricante</div></header><section class="product"><div class="ey">IDENTIFICAÇÃO DO PRODUTO</div><h1>${htmlEscape(nome)}</h1></section><section class="code">Código do produto<strong>${htmlEscape(bp.CodProduto||'-')}</strong></section><section class="client">Cliente<b>${htmlEscape(bp.ClienteNomeSnapshot||'Não informado')}</b></section><section class="qrwrap"><img src="${qr}" alt="QR Code"><span>Escaneie para abrir o mesmo dashboard HTML interativo do passaporte</span></section><footer class="foot"><span>Lote: ${htmlEscape(bp.IDLote||'-')}</span><span>${htmlEscape(bp.BatteryPassportID||'')}</span></footer></main></body></html>`);
    w.document.close();
    showBP();
  }catch(e){
    w.close();
    alert('A etiqueta não foi gerada porque o dashboard HTML não pôde ser publicado. O MES não usará mais PDF/link antigo como fallback.\n\n'+(e?.message||e));
  }
};

const _bpModuleV4044=bpModule;
bpModule=function(){
  const r=_bpModuleV4044();
  const tb=document.querySelector('#content .toolbar');
  if(tb&&!tb.querySelector('.v4044-publish')){
    const btn=document.createElement('button');
    btn.className='secondary v4044-publish';
    btn.textContent='Atualizar HTML / QR';
    btn.onclick=async()=>{const bp=v4044SelectedBP();if(!bp)return alert('Selecione um passaporte.');try{await v4044PublishDashboard(bp,null,false);showBP();}catch(e){alert('Falha ao atualizar HTML/QR.\n\n'+(e?.message||e));}};
    const anchor=[...tb.querySelectorAll('button')].find(b=>/Copiar link|Exportar dashboard HTML/i.test(b.textContent||''));
    if(anchor)anchor.insertAdjacentElement('afterend',btn);else tb.appendChild(btn);
  }
  return r;
};

// A URL usada pelo QR passa a representar exclusivamente o HTML interativo unificado.
bpShareStatus=function(bp){
  const u=String(bp?.URLPassaporteWeb||'').trim();
  if(!u)return 'Dashboard HTML ainda não publicado para o QR';
  if(v4044IsPdfLikeUrl(u))return 'Link antigo de PDF detectado — use Atualizar HTML / QR';
  return 'Mesmo dashboard HTML interativo usado na exportação e no QR';
};

/* ============================================================
   MES LION V40.4.5 — QR PÚBLICO VIA GITHUB PAGES
   - QR da etiqueta aponta exclusivamente para o HTML público do GitHub Pages.
   - Nome público padronizado: BPxxxx.html.
   - Exportação gera exatamente o arquivo que deve ser publicado no repositório.
   - Não usa localhost, IP LAN, PDF ou URL antiga para o QR.
   ============================================================ */
const MES_LION_PUBLIC_PASSPORT_BASE='https://hellen-fiep.github.io/mes-lion-fiep/';
function v4045PublicPassportUrl(bp){
  const id=String(bp?.BatteryPassportID||'').trim();
  if(!id) throw new Error('Passaporte sem ID.');
  return MES_LION_PUBLIC_PASSPORT_BASE+encodeURIComponent(id)+'.html';
}

v4044PublishDashboard=async function(bp, html=null, quiet=false){
  if(!bp?.BatteryPassportID) throw new Error('Selecione um passaporte.');
  const content=html||standaloneDashboardHTML(bp);
  const url=v4045PublicPassportUrl(bp);
  bp.URLPassaporteWeb=url;
  bp.URLDashboardCliente=url;
  bp.TipoPublicacaoPassaporte='HTML_INTERATIVO_GITHUB_PAGES';
  bp.DataPublicacaoHTML=new Date().toLocaleString('pt-BR');
  data.meta=data.meta||{};
  data.meta.PassaportePublicBase=MES_LION_PUBLIC_PASSPORT_BASE;
  saveLocal();
  if(!quiet){
    alert('URL pública do QR atualizada.\n\n'+url+'\n\nPublique/atualize o arquivo '+bp.BatteryPassportID+'.html no repositório GitHub Pages para que o QR abra esta mesma versão interativa.');
  }
  return {url,html:content};
};

exportBPDashboardHTML=async function(){
  const bp=v4044SelectedBP();
  if(!bp)return alert('Selecione um passaporte.');
  try{
    const html=standaloneDashboardHTML(bp);
    const pub=await v4044PublishDashboard(bp,html,true);
    downloadTextFile((bp.BatteryPassportID||'BP')+'.html',html);
    showBP();
    alert('HTML gerado como '+(bp.BatteryPassportID||'BP')+'.html.\n\nApós substituir esse arquivo no GitHub, o QR da etiqueta abrirá:\n'+pub.url);
  }catch(e){alert('Não foi possível gerar o HTML do cliente.\n\n'+(e?.message||e));}
};

