bpShareStatus=function(bp){
  const u=String(bp?.URLPassaporteWeb||'').trim();
  if(!u)return 'HTML público ainda não configurado';
  if(u.startsWith(MES_LION_PUBLIC_PASSPORT_BASE))return 'QR aponta para o dashboard HTML público no GitHub Pages';
  return 'Link legado detectado — use Atualizar HTML / QR';
};


/* ============================================================
   MES LION V40.4.7 — QUALIFICAÇÃO, ANEXOS, ETIQUETAS E ESTOQUE
   - Entradas novas passam a ter NF e Projeto pré-cadastrado.
   - Anexos persistentes ficam em Dados/Anexos; o JSON guarda só referências.
   - Flags de material/fornecedor qualificado.
   - Categoria de empresa controlada por opções do sistema.
   - Etiquetas de entradas/lotes para apoio ao picking.
   - Gestão/rastreabilidade de estoque por lote e projeto + Excel.
   ============================================================ */
const APP_PATCH_V4047='v40.4.7-qualificacao-anexos-estoque';

function v4047ProjectOptions(selected=''){
  return '<option value="">Sem projeto</option>'+(data.projetos||[]).map(p=>`<option value="${htmlEscape(p.CodProjeto||'')}" ${String(selected)===String(p.CodProjeto||'')?'selected':''}>${htmlEscape(p.CodProjeto||'')} — ${htmlEscape(p['Nome Projeto']||'(sem nome)')}</option>`).join('');
}
function v4047CompanyCategoryOptions(selected=''){
  const opts=['Fornecedor','Cliente','Fornecedor e Cliente'];
  return opts.map(v=>`<option value="${v}" ${String(selected||'Fornecedor')===v?'selected':''}>${v}</option>`).join('');
}
function v4047FileNameSafe(v){return String(v||'arquivo').replace(/[<>:"/\\|?*\x00-\x1f]/g,'_').slice(0,120)}
function v4047ReadFileBase64(file){return new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>{const x=String(fr.result||'');resolve(x.includes(',')?x.split(',')[1]:x)};fr.onerror=()=>reject(fr.error||new Error('Falha ao ler arquivo'));fr.readAsDataURL(file);});}
async function v4047UploadFiles(input,scope,recordId){
  const files=[...(input?.files||[])]; if(!files.length)return [];
  const out=[];
  for(const f of files){
    if(f.size>15*1024*1024)throw new Error(`O arquivo ${f.name} excede 15 MB.`);
    const base64=await v4047ReadFileBase64(f);
    const r=await fetch('/api/attachments',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scope,recordId,name:v4047FileNameSafe(f.name),mime:f.type||'application/octet-stream',dataBase64:base64})});
    if(!r.ok)throw new Error(await r.text()||`Falha ao salvar ${f.name}`);
    const a=await r.json(); out.push({Nome:f.name,Tipo:f.type||'',Tamanho:f.size,Url:a.url||'',Path:a.path||'',DataUpload:new Date().toLocaleString('pt-BR')});
  }
  return out;
}
function v4047AttachmentList(arr){
  arr=Array.isArray(arr)?arr:[];
  if(!arr.length)return '<span class="muted">Nenhum arquivo armazenado.</span>';
  return `<div class="v4047-files">${arr.map((a,i)=>`<a href="${htmlEscape(a.Url||'#')}" target="_blank" rel="noopener">📎 ${htmlEscape(a.Nome||('Arquivo '+(i+1)))}</a>`).join('')}</div>`;
}
function v4047ProjectSnapshot(code){const p=(data.projetos||[]).find(x=>String(x.CodProjeto||'')===String(code||''))||{};return {CodigoProjeto:code||'',Projeto:p['Nome Projeto']||''};}
function v4047Qualified(v){return /^(sim|true|1|qualificado)$/i.test(String(v||''));}
function v4047QCheckbox(id,checked,label='Qualificado'){return `<label class="v4047-check"><span>${htmlEscape(label)}</span><input id="${id}" type="checkbox" ${checked?'checked':''}></label>`;}

