async function salvarMaterialCadastroV4047(idx){
  try{
    /* Captura todo o formulário antes de qualquer await. A sincronização do banco pode
       rerenderizar a tela durante o upload; por isso nenhum campo do DOM é lido depois. */
    const old=idx>=0?(data.materiais[idx]||{}):{};
    const refs={
      cod:$('v47_mat_cod'),desc:$('v47_mat_desc'),um:$('v47_mat_um'),fator:$('v47_mat_fator'),
      cat:$('v47_mat_cat'),bpm:$('v47_mat_bpm'),cf:$('v47_mat_cf'),qual:$('v47_mat_qual'),
      files:$('v47_mat_files'),obs:$('v47_mat_obs')
    };
    if(!refs.cod||!refs.desc||!refs.um)throw new Error('O formulário de material foi atualizado durante o salvamento. Abra o cadastro novamente e tente salvar.');
    const snap={
      id:refs.cod.value,
      desc:refs.desc.value.trim(),
      um:refs.um.value.trim(),
      fator:refs.fator?.value||'',
      cat:refs.cat?.value.trim()||'',
      bpm:refs.bpm?.value.trim()||'',
      cf:refs.cf?.value.trim()||'',
      qual:!!refs.qual?.checked,
      obs:refs.obs?.value||''
    };
    if(!snap.desc)return alert('Informe a descrição do material.');
    const novos=await v4047UploadFiles(refs.files,'materiais',snap.id);
    const o={...old,'CódigoMaterial':snap.id,DescricaoMateriais:snap.desc,UM:snap.um,'Fator conversão para kg':snap.fator,Categoria:snap.cat,CodigoBPM:snap.bpm,CodigoFornecedor:snap.cf,MaterialQualificado:snap.qual?'Sim':'Não',ArquivosEspecificacao:[...(Array.isArray(old.ArquivosEspecificacao)?old.ArquivosEspecificacao:[]),...novos],Observacoes:snap.obs};
    if(idx>=0)data.materiais[idx]=o;else data.materiais.unshift(o);
    saveLocal();render('materiais');
  }catch(e){alert('Não foi possível salvar o material.\n\n'+(e?.message||e));}
}

