addEntrada=async function(){
  try{
    const id=nextByPrefix(data.entradas,'Entrada','EN');
    const refs={proj:$('em_proj'),files:$('em_files'),mat:$('em_mat'),desc:$('em_desc'),qtd:$('em_qtd'),um:$('em_um'),custo:$('em_custo'),unit:$('em_unit'),lote:$('em_lote'),forn:$('em_forn'),cnpj:$('em_cnpj'),nf:$('em_nf'),qual:$('em_qual')};
    if(!refs.mat||!refs.qtd)throw new Error('O formulário de entrada foi atualizado durante o salvamento. Abra-o novamente e tente salvar.');
    const snap={proj:refs.proj?.value||'',mat:refs.mat.value,desc:refs.desc?.value||'',qtd:refs.qtd.value,um:refs.um?.value||'',custo:refs.custo?.value||'',unit:refs.unit?.value||'',lote:refs.lote?.value||'',forn:refs.forn?.value||'',cnpj:refs.cnpj?.value||'',nf:refs.nf?.value||'',qual:!!refs.qual?.checked};
    if(!snap.mat||!snap.qtd)return alert('Informe material e quantidade adquirida.');
    const ps=v4047ProjectSnapshot(snap.proj); const anexos=await v4047UploadFiles(refs.files,'entradas',id);
    const r={'Entrada':id,'CódigoMaterial':snap.mat,'DescricaoMaterial':snap.desc,'QtdAdquirida':snap.qtd,'UnidadeMedida':snap.um,'Custo R$':snap.custo,'ValorUnitario (R$/UM)':snap.unit,'Lote':snap.lote,'NomeFornecedor':snap.forn,'CNPJFornecedor':snap.cnpj,'N° NF':snap.nf,...ps,MaterialQualificado:snap.qual?'Sim':'Não',ArquivosQualificacao:anexos,DataCadatro:new Date().toLocaleDateString('pt-BR')};
    data.entradas.unshift(r);saveLocal();render('entradas');
  }catch(e){alert('Não foi possível registrar a entrada.\n\n'+(e?.message||e));}
};
editarEntrada=function(idx){
  const r=(data.entradas||[])[idx]||{};const old=$('crudBox');if(old)old.remove();const box=document.createElement('div');box.id='crudBox';
  box.innerHTML=`<div class="form edit-form"><h3>Editar Entrada de Materiais</h3><div class="form-grid"><label><span>Entrada</span><input id="ed_entrada" value="${htmlEscape(r.Entrada||'')}" readonly></label><label><span>Material</span><select id="ed_mat" onchange="entradaEditLookup()"></select></label><label><span>Descrição</span><input id="ed_desc" value="${htmlEscape(r.DescricaoMaterial||'')}" readonly></label><label><span>UM</span><input id="ed_um" value="${htmlEscape(r.UnidadeMedida||'')}" readonly></label><label><span>Qtd adquirida</span><input id="ed_qtd" value="${htmlEscape(r.QtdAdquirida||'')}" oninput="entradaEditCalc()"></label><label><span>Custo total R$</span><input id="ed_custo" value="${htmlEscape(r['Custo R$']||'')}" oninput="entradaEditCalc()"></label><label><span>Valor unitário</span><input id="ed_unit" value="${htmlEscape(r['ValorUnitario (R$/UM)']||'')}" readonly></label><label><span>Fornecedor</span><select id="ed_forn" onchange="entradaEditFornecedor()"></select></label><label><span>CNPJ</span><input id="ed_cnpj" value="${htmlEscape(r.CNPJFornecedor||'')}" readonly></label><label><span>Lote</span><input id="ed_lote" value="${htmlEscape(r.Lote||'')}"></label><label><span>Nº NF</span><input id="ed_nf" value="${htmlEscape(r['N° NF']||'')}"></label><label><span>Projeto</span><select id="ed_proj">${v4047ProjectOptions(r.CodigoProjeto||'')}</select></label>${v4047QCheckbox('ed_qual',v4047Qualified(r.MaterialQualificado),'Material/lote qualificado')}<label class="wide"><span>Adicionar arquivos da entrada / qualificação</span><input id="ed_files" type="file" multiple accept=".pdf,.doc,.docx,.xls,.xlsx,.csv,.jpg,.jpeg,.png,.webp"></label><div class="wide"><b>Arquivos armazenados</b>${v4047AttachmentList(r.ArquivosQualificacao)}</div></div><div class="form-actions"><button onclick="salvarEntradaEditada(${idx})">Salvar edição</button><button class="danger" onclick="deleteRecord('entradas',${idx})">Excluir</button><button class="secondary" onclick="render('entradas')">Cancelar</button></div></div>`;
  $('content').insertBefore(box,$('content').children[1]);fillSelect('ed_mat',data.materiais,'CódigoMaterial','DescricaoMateriais');$('ed_mat').value=r['CódigoMaterial']||'';fillSelect('ed_forn',(data.empresas||[]).filter(e=>/fornecedor/i.test(e.Categoria||'')),'RazaoSocial','CNPJ');$('ed_forn').value=r.NomeFornecedor||'';box.scrollIntoView({behavior:'smooth',block:'start'});
};
