    const refs={entrada:$('ed_entrada'),proj:$('ed_proj'),files:$('ed_files'),mat:$('ed_mat'),desc:$('ed_desc'),qtd:$('ed_qtd'),um:$('ed_um'),custo:$('ed_custo'),unit:$('ed_unit'),lote:$('ed_lote'),forn:$('ed_forn'),cnpj:$('ed_cnpj'),nf:$('ed_nf'),qual:$('ed_qual')};
