/* =========================================================
   MES LION V40.5.0 — MASSAS DEFINIDAS NA OP + PERDAS POR ETAPA/EQUIPAMENTO
   Base: V40.4.9
   - Roteiro mantém estrutura de processo/equipamentos e apenas indica materiais.
   - Quantidades de materiais são definidas/calculadas na OP.
   - Slurry: massa total da OP -> sólidos + solvente -> componentes da formulação.
   - Eletrólito: massa total da OP -> componentes percentuais da formulação.
   - Deposição registra massa seca projetada após evaporação do solvente.
   - Perdas passam a guardar ordem da etapa e equipamento.
   - Exportação Excel consolida perdas por OP/etapa/equipamento.
   ========================================================= */
const APP_PATCH_V4050='V40.5.0-op-massas-formulacao-perdas-etapa-equipamento';

function v4050Pct(v, fallback=''){ const n=num(v); return (v!==''&&v!==null&&v!==undefined)?n:num(fallback); }
function v4050FormulaSolidos(f,grupo){
  if(grupo==='CATODO') return v4050Pct(f.TeorSolidosCatodo,100);
  if(grupo==='ANODO') return v4050Pct(f.TeorSolidosAnodo,100);
  return 100;
}
function v4050FormulaSolvente(f,grupo){
  let raw=grupo==='CATODO'?f.TeorSolventeCatodo:grupo==='ANODO'?f.TeorSolventeAnodo:'';
  if(raw!==''&&raw!==undefined&&raw!==null) return num(raw);
  return Math.max(0,100-v4050FormulaSolidos(f,grupo));
}
function v4050IsSolventItem(i){ return /solvent|solvente/i.test(String(i.Funcao||'')+' '+String(i.DescricaoMaterial||'')); }
function v4050MaterialCost(cod){ return num(materialUnitCost(cod)||0); }
function v4050GroupName(g){ return g==='CATODO'?'Slurry cátodo':g==='ANODO'?'Slurry ânodo':g==='ELETROLITO'?'Eletrólito':g||''; }

/* Fórmula: recoloca explicitamente % de sólidos e % de solvente no cadastro. */
const _abrirEditorFormulaV4050=abrirEditorFormula;
abrirEditorFormula=function(f){
  _abrirEditorFormulaV4050(f);
  const add=(solidId,solvId,value)=>{
    const solid=$(solidId); if(!solid||$(solvId))return;
    const lab=solid.closest('label'); if(!lab)return;
    const el=document.createElement('label');
    el.innerHTML=`<span>Teor de solvente — ${solvId.includes('cat')?'cátodo':'ânodo'} (%)</span><input id="${solvId}" type="number" min="0" max="100" step="0.001" value="${htmlEscape(value)}" oninput="v4050SyncSolidosSolvente('${solidId}','${solvId}','solvente')">`;
    lab.insertAdjacentElement('afterend',el);
    solid.setAttribute('oninput',`v4050SyncSolidosSolvente('${solidId}','${solvId}','solidos')`);
  };
  add('fm_sol_cat','fm_solv_cat',f.TeorSolventeCatodo!==undefined&&f.TeorSolventeCatodo!==''?f.TeorSolventeCatodo:Math.max(0,100-num(f.TeorSolidosCatodo||0)));
  add('fm_sol_an','fm_solv_an',f.TeorSolventeAnodo!==undefined&&f.TeorSolventeAnodo!==''?f.TeorSolventeAnodo:Math.max(0,100-num(f.TeorSolidosAnodo||0)));
  const note=document.querySelector('.formula-note');
  if(note) note.innerHTML='<b>Regra de cálculo V40.5:</b> para slurry, a OP informa a <b>massa total úmida</b>. O teor de sólidos define a massa seca e o teor de solvente define a massa temporária que acompanha o slurry até a deposição. Os percentuais dos componentes sólidos são aplicados sobre a massa de sólidos. Na deposição, o solvente é considerado evaporado. Para eletrólito, os percentuais são aplicados diretamente à massa total formulada.';
};
function v4050SyncSolidosSolvente(solidId,solvId,source){
  const s=$(solidId),v=$(solvId);if(!s||!v)return;
  if(source==='solidos') v.value=String(Math.max(0,100-num(s.value))).replace('.',',').replace(',','.');
  else s.value=String(Math.max(0,100-num(v.value))).replace('.',',').replace(',','.');
}
const _salvarFormulaV4050=salvarFormula;
salvarFormula=function(){
  const cod=$('fm_cod')?.value||'';
  const svCat=$('fm_solv_cat')?.value, svAn=$('fm_solv_an')?.value;
  const ret=_salvarFormulaV4050();
  const f=(data.formulacoes||[]).find(x=>x.CodFormula===cod);
  if(f){
    f.TeorSolventeCatodo=svCat!==undefined?svCat:String(Math.max(0,100-num(f.TeorSolidosCatodo||0)));
    f.TeorSolventeAnodo=svAn!==undefined?svAn:String(Math.max(0,100-num(f.TeorSolidosAnodo||0)));
    f.BaseCalculo='Massa total definida na OP; slurry separado em sólidos e solvente';
    saveLocal();
  }
  return ret;
};

/* Roteiro: materiais apenas indicados; quantidade passa a ser responsabilidade da OP. */
tabelaMateriaisOperacaoV382=function(rows,ordem){
  return `<table class="compact-table"><thead><tr><th>Material do cadastro</th><th>Regra de quantidade</th><th>UM</th><th>Lote</th><th>Ação</th></tr></thead><tbody>${rows.map(m=>{
    const idx=(data.roteiro_materiais||[]).indexOf(m);
    return `<tr><td><b>${safeTextV382(m.CodigoMaterial)}</b><br>${safeTextV382(m.DescricaoMaterial)}</td><td><span class="muted">Quantidade definida na OP${m.CodFormula?' / formulação':''}</span></td><td><input class="um-v382" value="${safeTextV382(m.UM||m.UMConsumo||'')}" readonly></td><td><span class="muted">Definido no apontamento</span></td><td><button class="danger mini" onclick="excluirMaterialV382(${idx})">Excluir</button></td></tr>`;
  }).join('')}</tbody></table>`;
};
const _adicionarMaterialRecursoV4050=adicionarMaterialRecursoV385;
adicionarMaterialRecursoV385=function(id,codigoMaterial){
  const before=(data.roteiro_materiais||[]).length; const ret=_adicionarMaterialRecursoV4050(id,codigoMaterial);
  if((data.roteiro_materiais||[]).length>before){const m=data.roteiro_materiais[data.roteiro_materiais.length-1];m.QtdBase='';m.QtdPlanejada='';m.RegraQuantidade='DEFINIR_NA_OP';saveLocal();}
  return ret;
};

function v4050ClearRouteQuantitiesOnOP(op){
  (data.op_materiais||[]).filter(m=>m.CodOP===op.CodOP).forEach(m=>{
    if(String(m.TipoConsumo||'').toLowerCase().includes('pi intermedi')) return;
    if(m.CodFormula||m.OrigemQuantidade==='FORMULA_OP') return;
    m.QtdPlanejada='';m.QtdBase='';m.CustoTotal='';m.RegraQuantidade='DEFINIR_NA_OP';m.OrigemQuantidade='ROTEIRO_INDICATIVO';
  });
}

/* Formulação calculada na OP, sem exigir material previamente alocado no roteiro. */
aplicarFormulaNasOPsV3813=function(ops,codFormula){
  const f=formulaByCodeV3813(codFormula); if(!f) throw new Error('Formulação não encontrada.');
  const todos=(data.formulacao_itens||[]).filter(i=>i.CodFormula===codFormula);
  ops.forEach(op=>{
    op.CodFormula=f.CodFormula;op.NomeFormula=f.Nome||'';op.VersaoFormula=f.Versao||'1';op.QuimicaFormula=f.Quimica||'';op.FormulaCongelada='Sim';op.DataFormulaOP=new Date().toLocaleString('pt-BR');
    op.SnapshotFormula=JSON.stringify({cabecalho:{...f},itens:todos.map(i=>({...i}))});
    v4050ClearRouteQuantitiesOnOP(op);
    const grupo=grupoEtapaFormulaV392(op);op.GrupoFormulaAplicado=grupo||'Não aplicável nesta OP';
    if(!grupo)return;
    v4050RecalculateFormulaOP(op.CodOP,false);
  });
  return ops;
};

function v4050RecalculateFormulaOP(codOP,persist=true){
  const op=(data.op||[]).find(o=>o.CodOP===codOP); if(!op)return;
  const f=formulaByCodeV3813(op.CodFormula)||(()=>{try{return JSON.parse(op.SnapshotFormula||'{}').cabecalho||null}catch(e){return null}})();
  if(!f)return;
  let all=(data.formulacao_itens||[]).filter(i=>i.CodFormula===op.CodFormula);
  if(!all.length){try{all=JSON.parse(op.SnapshotFormula||'{}').itens||[]}catch(e){all=[]}}
  const grupo=grupoEtapaFormulaV392(op)||op.GrupoFormulaAplicado; if(!['CATODO','ANODO','ELETROLITO'].includes(grupo))return;
  const itens=all.filter(i=>String(i.Grupo||'').toUpperCase()===grupo); if(!itens.length)return;
  const massaTotal=num(op.QtdPlanejada||0); if(!(massaTotal>0))return;
  const solidsPct=grupo==='ELETROLITO'?100:v4050FormulaSolidos(f,grupo);
  const solventPct=grupo==='ELETROLITO'?0:v4050FormulaSolvente(f,grupo);
  const massaSolidos=massaTotal*solidsPct/100;
  const massaSolvente=massaTotal*solventPct/100;
  op.MassaTotalFormulada=String(massaTotal);op.PercentualSolidos=String(solidsPct);op.PercentualSolvente=String(solventPct);op.MassaSolidos=String(massaSolidos);op.MassaSolvente=String(massaSolvente);op.MassaAposDeposicao=String(grupo==='ELETROLITO'?massaTotal:massaSolidos);
  const current=(data.op_materiais||[]).filter(m=>m.CodOP===codOP);
  const solids=itens.filter(i=>!v4050IsSolventItem(i) && String(i.Base||'')!=='Massa total');
  const solvents=itens.filter(v4050IsSolventItem);
  const additions=itens.filter(i=>!v4050IsSolventItem(i) && String(i.Base||'')==='Massa total');
  const solidSum=solids.reduce((s,i)=>s+num(i.Percentual),0)||100;
  const solventSum=solvents.reduce((s,i)=>s+num(i.Percentual),0)||solvents.length||1;
  const setItem=(i,qtd,regra)=>{
    const mat=materialObjV32(i.CodigoMaterial)||{};let row=current.find(m=>String(m.CodigoMaterial)===String(i.CodigoMaterial)&&String(m.CodFormula||op.CodFormula)===String(op.CodFormula));
    if(!row){row={CodOP:op.CodOP,CodRoteiro:op.CodRoteiro||'',Ordem:'FORM',CodigoProduto:op.CodigoProduto||op.Produto||'',CodigoPI:op.CodigoPI||'',Processo:v4050GroupName(grupo),CodigoMaterial:i.CodigoMaterial||'',DescricaoMaterial:i.DescricaoMaterial||mat.DescricaoMateriais||'',EntradaMaterial:'',Lote:'',UM:i.UM||mat.UM||op.UM||'kg',TipoConsumo:'Formulação',Observacoes:''};data.op_materiais.push(row);current.push(row);}
    const unit=v4050MaterialCost(i.CodigoMaterial)||num(row.CustoUnitario);
    row.QtdPlanejada=String(qtd);row.QtdBase=String(massaTotal);row.CustoUnitario=String(unit);row.CustoTotal=String(qtd*unit);row.PercentualFormula=String(i.Percentual||'');row.BasePercentualFormula=i.Base||'';row.CodFormula=op.CodFormula;row.VersaoFormula=op.VersaoFormula||f.Versao||'1';row.GrupoFormula=grupo;row.FuncaoFormula=i.Funcao||'';row.OrigemQuantidade='FORMULA_OP';row.RegraQuantidade=regra;row.Observacoes=`Calculado na OP ${op.CodOP} a partir de massa total ${massaTotal} ${op.UM||row.UM||''}.`;
  };
  if(grupo==='ELETROLITO'){
    const sum=itens.reduce((s,i)=>s+num(i.Percentual),0)||100; itens.forEach(i=>setItem(i,massaTotal*num(i.Percentual)/sum,'PERCENTUAL_MASSA_TOTAL_ELETROLITO'));
  }else{
    solids.forEach(i=>setItem(i,massaSolidos*num(i.Percentual)/solidSum,'PERCENTUAL_SOBRE_MASSA_SOLIDOS'));
    solvents.forEach(i=>setItem(i,massaSolvente*(solvents.length===1?1:num(i.Percentual)/solventSum),'FRACAO_SOLVENTE_SLURRY'));
    additions.forEach(i=>setItem(i,massaTotal*num(i.Percentual)/100,'ADICAO_PROCESSO_SOBRE_MASSA_TOTAL'));
  }
  if(persist)saveLocal();
}

