/* V40.5.0 — geração: roteiro fornece somente a massa/quantidade total-base de cada PA/PI;
   a OP criada pode ser alterada independentemente depois, sem alterar o roteiro. */
gerarOPsComFormulaV3813=function(r,fatorInicial,codFormula){
  if(!codFormula)return alert('Selecione a formulação que será usada nos cálculos de massa.');
  const f=formulaByCodeV3813(codFormula);if(!f||String(f.Status||'').toUpperCase()!=='ATIVA')return alert('Selecione uma formulação ativa.');
  let ops;
  try{ops=gerarTodasOPsDoRoteiroValidadoV29(r,num(fatorInicial)>0?num(fatorInicial):1);}catch(e){return alert(e.message||String(e));}
  aplicarFormulaNasOPsV3813(ops,codFormula);v4050ApplyDepositionMassInfo();
  ops.forEach(o=>{o.RoteiroValidado='Não se aplica';o.DataValidacaoRoteiro='';o.OrigemQtdPlanejada='MASSA_TOTAL_BASE_ROTEIRO_EDITAVEL_NA_OP';});
  saveLocal();alert(`OPs geradas com a formulação ${f.CodFormula} — ${f.Nome} — v${f.Versao||'1'}:\n- `+ops.map(o=>o.CodOP).join('\n- ')+'\n\nAs quantidades podem ser alteradas individualmente em cada OP; os materiais formulados serão recalculados automaticamente.');render('op');return ops;
};
