  $('crudBox').innerHTML=v4050GeneratorForm(r,false);$('v4050_gen_btn').onclick=()=>gerarOPsComFormulaV3813(r,1,$('op_formula_v3813')?.value||'');$('crudBox').scrollIntoView({behavior:'smooth',block:'start'});
