// Cria uma OP espelhando somente a estrutura do roteiro. A quantidade nasce vazia na OP.
function v10CriarOPEstrutural(r,produtoCod,codOP,opBase){
  data.op=data.op||[];data.op_etapas=data.op_etapas||[];data.op_materiais=data.op_materiais||[];
  const prod=produtoObjV32(produtoCod)||{};
  const tipo=String(prod['Tipo Produto']||'').toUpperCase()==='PI'?'PI':'PA';
  const um=prodUMV382(produtoCod)||unidadeProdutoV35(produtoCod)||'un';
  const op={CodOP:codOP,CodRoteiro:r.CodRoteiro,CodigoProduto:produtoCod,CodigoPA:r.CodigoProduto||'',CodigoPI:tipo==='PI'?produtoCod:'',Produto:produtoCod,ProdutoGerado:produtoCod,DescricaoProduto:prod['Descrição']||r.DescricaoRoteiro||'',Versao:r.Versao||'',IdCelula:r.IdCelula||prod['Célula']||'',QtdPlanejada:'',QtdProduzida:'',PerdasRegistradas:'',UM:um,Status:'Planejada',TipoOP:tipo,OP_Base:opBase,OP_Pai:tipo==='PI'?opBase:'',DataOP:new Date().toLocaleDateString('pt-BR'),DataCriacao:new Date().toLocaleString('pt-BR'),Usuario:'admin',OrigemGeracao:'ROTEIRO_ESTRUTURAL',RoteiroValidado:'Não se aplica',DataValidacaoRoteiro:'',OrigemQtdPlanejada:'DEFINIR_NA_OP',Observacoes:`OP criada a partir da estrutura do roteiro ${r.CodRoteiro}. Quantidade/massa deve ser informada na OP.`};
  data.op.unshift(op);
  const stages=v4031TargetStages(r,produtoCod);
  stages.forEach(e=>{
    const recs=v4031ResourcesForStage(r,e);
    if(recs.length){
      recs.forEach((rec,ri)=>data.op_etapas.push({CodOP:codOP,CodRoteiro:r.CodRoteiro,Ordem:e.Ordem||e.OrdemEtapa||'',CodigoProduto:produtoCod,CodigoPI:tipo==='PI'?produtoCod:'',ProdutoGerado:produtoCod,DescricaoProdutoGerado:prod['Descrição']||'',QtdPlanejadaProduto:'',UMProduto:um,Processo:e.Processo||rec.Processo||'',SubProcesso:rec.SubProcesso||e.SubProcesso||'',IdProcesso:e.IdProcesso||'',IdRecursoRoteiro:rec.IdRecursoRoteiro||'',SequenciaRecurso:ri+1,CodEquipamento:rec.CodEquipamento||'',Recurso:rec.Equipamento||'',Equipamento:rec.Equipamento||'',TempoPlanejado:rec.TempoOperacaoMin||e.TempoOperacaoMin||'',TempoOperacaoMin:rec.TempoOperacaoMin||e.TempoOperacaoMin||'',PessoasPlanejado:rec.NPessoas||e.NPessoas||'',NPessoas:rec.NPessoas||e.NPessoas||'',PotenciaEquipamento:rec.PotenciaEquipamento||'',Status:'PENDENTE',Obs:e.Obs||'',OrigemDados:'ROTEIRO_ESTRUTURA'}));
    }else{
      data.op_etapas.push({CodOP:codOP,CodRoteiro:r.CodRoteiro,Ordem:e.Ordem||'',CodigoProduto:produtoCod,CodigoPI:tipo==='PI'?produtoCod:'',ProdutoGerado:produtoCod,DescricaoProdutoGerado:prod['Descrição']||'',QtdPlanejadaProduto:'',UMProduto:um,Processo:e.Processo||'',IdProcesso:e.IdProcesso||'',IdRecursoRoteiro:'',SequenciaRecurso:1,CodEquipamento:'',Recurso:'',Equipamento:'',TempoPlanejado:e.TempoOperacaoMin||'',TempoOperacaoMin:e.TempoOperacaoMin||'',PessoasPlanejado:e.NPessoas||'',NPessoas:e.NPessoas||'',PotenciaEquipamento:'',Status:'PENDENTE',Obs:e.Obs||'',OrigemDados:'ROTEIRO_ESTRUTURA'});
    }
  });
  v4031MaterialsForTarget(r,produtoCod,stages).forEach(m=>{
    const mat=materialObjV32(m.CodigoMaterial)||{};
    const unit=num(m.CustoUnitario)||materialUnitCost(m.CodigoMaterial)||0;
    data.op_materiais.push({CodOP:codOP,CodRoteiro:r.CodRoteiro,Ordem:m.OrdemEtapa||m.Ordem||'',OrdemEtapa:m.OrdemEtapa||m.Ordem||'',CodigoProduto:produtoCod,CodigoPI:tipo==='PI'?produtoCod:'',Processo:m.Processo||'',IdRecursoRoteiro:m.IdRecursoRoteiro||'',CodEquipamento:m.CodEquipamento||'',CodigoMaterial:m.CodigoMaterial||'',DescricaoMaterial:m.DescricaoMaterial||mat.DescricaoMateriais||'',EntradaMaterial:'',Lote:'',QtdPlanejada:'',QtdBase:'',UM:m.UMConsumo||m.UM||mat.UM||'',CustoUnitario:String(unit),CustoTotal:'',TipoConsumo:m.TipoConsumo||'Consumo Direto',Observacoes:m.Obs||m.Observacoes||'',RegraQuantidade:'DEFINIR_NA_OP',OrigemQuantidade:'ROTEIRO_ESTRUTURAL',OrigemDados:'ROTEIRO_ESTRUTURA'});
  });
  return op;
}

gerarTodasOPsDoRoteiroValidadoV29=function(r){
  const base=baseOPCode(),produtos=roteiroProdutosV32(r),criadas=[];
  if(!produtos.length)throw new Error(`O roteiro ${r.CodRoteiro} não possui produtos/etapas para gerar OP.`);
  produtos.forEach((prodCod,idx)=>{
    const prod=produtoObjV32(prodCod)||{},tipo=String(prod['Tipo Produto']||'').toUpperCase()==='PI'?'PI':'PA';
    const sufixo=tipo==='PA'?'-PA':'-'+pad(idx+1,2);
    criadas.push(v10CriarOPEstrutural(r,prodCod,base+sufixo,base));
  });
  const mae=criadas.find(o=>String(o.TipoOP||'').toUpperCase()==='PA');
  if(mae){
    criadas.filter(o=>String(o.TipoOP||'').toUpperCase()==='PI').forEach(f=>data.op_materiais.push({CodOP:mae.CodOP,CodRoteiro:r.CodRoteiro,Ordem:'PI',OrdemEtapa:'PI',CodigoProduto:mae.Produto,CodigoPI:f.Produto,Processo:'Integração / genealogia',CodigoMaterial:f.Produto,DescricaoMaterial:f.DescricaoProduto||f.Produto,Lote:'',QtdPlanejada:'',QtdBase:'',UM:f.UM||'un',TipoConsumo:'PI intermediário',CustoUnitario:'0',CustoTotal:'0',OrigemQuantidade:'OP_FILHA',Observacoes:`PI produzido pela OP filha ${f.CodOP}. Quantidade será definida na OP.`}));
  }
  return criadas;
};

// Geração não solicita quantidade: cria a estrutura e o usuário informa a massa/quantidade dentro de cada OP.
gerarOPsComFormulaV3813=function(r,ignorado,codFormula){
  if(!codFormula)return alert('Selecione a formulação que será usada nos cálculos de massa.');
  const f=formulaByCodeV3813(codFormula);if(!f||String(f.Status||'').toUpperCase()!=='ATIVA')return alert('Selecione uma formulação ativa.');
  let ops;try{ops=gerarTodasOPsDoRoteiroValidadoV29(r);}catch(e){return alert(e.message||String(e));}
  aplicarFormulaNasOPsV3813(ops,codFormula);
  ops.forEach(o=>{o.QtdPlanejada='';o.OrigemQtdPlanejada='DEFINIR_NA_OP';(data.op_etapas||[]).filter(e=>e.CodOP===o.CodOP).forEach(e=>e.QtdPlanejadaProduto='');});
  v4050ApplyDepositionMassInfo();saveLocal();
  alert(`OPs geradas a partir da estrutura do roteiro ${r.CodRoteiro}.\n\nInforme a quantidade/massa planejada diretamente em cada OP. Os materiais formulados serão calculados automaticamente após o lançamento.`);
  render('op');return ops;
};

