v4050OPPlanningHTML=function(op){
  v101SyncOPUnit(op);if(op.CodFormula)v4050RecalculateFormulaOP(op.CodOP,false);
  const mats=(data.op_materiais||[]).filter(m=>m.CodOP===op.CodOP&&!String(m.TipoConsumo||'').toLowerCase().includes('pi intermedi'));
  const formulados=mats.filter(m=>m.CodFormula&&m.OrigemQuantidade==='FORMULA_OP'),manuais=mats.filter(m=>!formulados.includes(m));
  const formula=op.CodFormula?`<div class="formula-note"><b>Formulação congelada:</b> ${htmlEscape(op.CodFormula||'')} v${htmlEscape(op.VersaoFormula||'')} · grupo ${htmlEscape(op.GrupoFormulaAplicado||'')} · sólidos ${htmlEscape(op.PercentualSolidos||'—')}% · solvente ${htmlEscape(op.PercentualSolvente||'—')}%${op.QtdPlanejada?` · massa sólida após deposição ${fmtMax4V395(op.MassaAposDeposicao||0)} ${htmlEscape(op.UM||'')}`:''}.</div>`:'';
  const row=(m,i,auto)=>{const mi=mats.indexOf(m);return `<tr><td><b>${htmlEscape(m.CodigoMaterial||'')}</b><br>${htmlEscape(m.DescricaoMaterial||'')}</td><td>${auto?'Formulação da OP':htmlEscape(m.OrigemQuantidade||m.RegraQuantidade||'OP')}</td><td>${auto?(m.QtdPlanejada!==''?`<b>${fmtMax4V395(m.QtdPlanejada)}</b>`:'<span class="muted">Aguardando quantidade da OP</span>'):`<input id="v4050_mq_${mi}" type="number" step="0.000001" value="${htmlEscape(m.QtdPlanejada||'')}">`}</td><td>${htmlEscape(m.UM||'')}</td><td>${auto?htmlEscape(m.PercentualFormula||''):'—'}</td><td>${m.CustoTotal!==''?money(m.CustoTotal):'—'}</td><td>${auto?'<span class="muted">Automático</span>':`<button class="mini" onclick="v4050SetMaterialQty('${jsq(op.CodOP)}',${mi})">Salvar quantidade</button>`}</td></tr>`;};
  const label=/^kg$/i.test(op.UM||'')?'Massa total planejada desta OP':'Quantidade planejada desta OP';
  return `<div class="card"><h3>Planejamento de quantidade e materiais na OP</h3><p class="muted"><b>O roteiro não fornece massas.</b> A UM vem do PI/PA. A quantidade é definida somente nesta OP; materiais formulados são calculados automaticamente e materiais não formulados são informados manualmente.</p><div class="form-grid"><label><span>${label}</span><input id="v4050_op_qty" type="number" step="0.000001" value="${htmlEscape(op.QtdPlanejada||'')}"></label><label><span>UM da OP</span><input value="${htmlEscape(op.UM||'')}" readonly></label></div><div class="form-actions"><button onclick="v4050UpdateOPQty('${jsq(op.CodOP)}')">Atualizar quantidade e recalcular materiais</button></div>${formula}${formulados.length?`<h4>Materiais calculados pela formulação</h4><div class="table-wrap"><table><thead><tr><th>Material</th><th>Origem</th><th>Massa/quantidade calculada</th><th>UM</th><th>% fórmula</th><th>Custo estimado</th><th>Ação</th></tr></thead><tbody>${formulados.map((m,i)=>row(m,i,true)).join('')}</tbody></table></div>`:''}${manuais.length?`<h4>Materiais da etapa não formulados</h4><div class="table-wrap"><table><thead><tr><th>Material</th><th>Origem</th><th>Qtd planejada</th><th>UM</th><th>% fórmula</th><th>Custo estimado</th><th>Ação</th></tr></thead><tbody>${manuais.map((m,i)=>row(m,i,false)).join('')}</tbody></table></div>`:''}${!mats.length?'<div class="hint">Nenhum material vinculado a esta OP.</div>':''}</div>`;
};

