  const base=baseOPCode(),op=v10CriarOPEstrutural(r,cod,base+'-PI',base);op.OP_Pai='';op.OP_Base=op.CodOP;op.TipoOP='PI';op.OrigemGeracao='PI_ISOLADO';op.UM=v101ProductUM(cod,r);op.QtdPlanejada='';op.OrigemQtdPlanejada='DEFINIR_NA_OP';
  if(f)aplicarFormulaNasOPsV3813([op],f);saveLocal();render('op');setTimeout(()=>{if($('selOp')){$('selOp').value=op.CodOP;showOP();}},80);
