  const pi=$('v4033_sim_product')?.value,q=num($('v4033_pi_q')?.value),act=$('v4033_pi_origin')?.value||'PRODUZIR';if(!(q>0))return alert('A quantidade do PI deve ser maior que zero.');let d;
