  if(alvo==='Material'){
    const mats=(data.op_materiais||[]).filter(m=>String(m.CodOP)===String(op.CodOP)),idx=parseInt($('loss_item')?.value||'0',10);matRow=mats[idx]||{};itemCod=matRow.CodigoMaterial||'';itemDesc=matRow.DescricaoMaterial||'';const isPI=String(matRow.TipoConsumo||'').toLowerCase().includes('pi intermedi')||/^PI/i.test(String(itemCod));um=isPI?(v101ProductUM(itemCod)||matRow.UM||''):(matRow.UM||unidadeMaterialV36(itemCod)||'');planejado=matRow.QtdPlanejada||'';
  }else{const info=opProductInfo(op);itemCod=info.cod||op.CodigoPI||op.CodigoProduto||op.Produto||'';itemDesc=info.desc||op.DescricaoProduto||'';um=unidadeProdutoOPV36(op);}
  const rec={NOPP:nextByPrefix(data.perdas||[],'NOPP','PERD'),CodOP:op.CodOP,PerdaAlvoTipo:alvo,TipoApontamento:$('loss_tipo')?.value||'Refugo de processo',ItemPerdaCodigo:itemCod,ItemPerdaDescricao:itemDesc,CodigoMaterial:alvo==='Material'?itemCod:'',Produto:alvo==='Produto'?itemCod:(op.CodigoPI||op.CodigoProduto||op.Produto||''),DescricaoProduto:itemDesc,OrdemEtapa:etapa.Ordem||'',Processo:etapa.Processo||'',IdRecursoRoteiro:etapa.IdRecursoRoteiro||'',CodEquipamento:etapa.CodEquipamento||'',Equipamento:etapa.Recurso||etapa.Equipamento||recursoNomeV32(etapa.CodEquipamento,etapa.Processo)||'',ProdutoEtapa:etapa.ProdutoGerado||op.Produto||op.CodigoProduto||'',Unidade:um,QuantidadePerdida:String(qtd).replace('.',','),Operador:$('loss_operador')?.value||'',DataApontamento:$('loss_data')?.value||todayBR(),Motivo:$('loss_motivo')?.value||'',Observacoes:$('loss_obs')?.value||'',PlanejadoItem:planejado};
  data.perdas=data.perdas||[];data.perdas.push(rec);op.PerdasRegistradas=String(opQtdPerdas(op)).replace('.',',');if(!statusOP(op).includes('EM PRODU'))op.Status='Em Produção';op.DataUltimoApontamento=nowBR();
