/* =========================================================
   MES LION V1.0.4 — CUSTO FECHADO COMO FONTE ÚNICA DA VERDADE
   - O custo é consolidado UMA VEZ no encerramento da OP.
   - Custos Industriais apenas lê o snapshot salvo.
   - Simulações apenas multiplicam o custo unitário fechado.
   - Lotes de PI herdam exclusivamente o snapshot da OP de origem.
   - Memória auditável do fechamento é preservada no snapshot.
   - Uploads de Materiais, Fornecedores e Entradas capturam arquivos e campos antes de await.
   ========================================================= */
const APP_VERSION_V104='V1.0.4';

function v104IsClosed(op){return !!op && (/conclu|encerr/i.test(String(op.Status||'')) || !!op.DataEncerramento);}
function v104CostRows(cod){return (data.custos_op||[]).filter(x=>String(x.CodOP||x.CodOPMae||'')===String(cod||''));}
function v104SavedCost(cod){
  const rows=v104CostRows(cod);
  return rows.find(x=>x.CustoFechado==='SIM'||x.FonteCusto==='ENCERRAMENTO_OP') || rows[0] || null;
}
function v104SnapshotAudit(a){
  return {
    materiais: JSON.parse(JSON.stringify(a?.materiais||[])),
    etapas: JSON.parse(JSON.stringify(a?.etapas||[])),
    perdas: JSON.parse(JSON.stringify(a?.perdas||[])),
    regras: JSON.parse(JSON.stringify(a?.regras||[]))
  };
}
function v104FreezeCost(cod,force=false){
  const op=opPorCodigo(cod)||{};if(!op.CodOP)return null;
  const existing=v104SavedCost(cod);
  if(existing && existing.CustoFechado==='SIM' && !force)return existing;
  // ÚNICO ponto autorizado a executar o motor auditável: fechamento da OP.
  const isPI=v403IsPI(op),a=isPI?v4033AuditCostPI(cod):auditCostFamilyV4014(cod),r=a.resumo?.[0]||{};
  const q=num(op.QtdProduzida)||num(op.QtdPlanejada)||1;
  const row={
    CodOP:cod,CodOPMae:isPI?'':cod,Escopo:isPI?'PI ISOLADO':'FAMÍLIA PA',
    ProdutoPA:op.CodigoProduto||op.CodigoPI||op.Produto||'',DescricaoProduto:op.DescricaoProduto||'',
    DataCalculo:new Date().toLocaleString('pt-BR'),DataFechamentoCusto:new Date().toLocaleString('pt-BR'),
    OPsRelacionadas:r.OPsIncluidas||cod,CustoMateriais:String(num(r.CustoMateriais)),
    CustoEnergia:String(num(r.CustoEnergia)),CustoMOD:String(num(r.CustoMOD)),CustoPerdas:String(num(r.CustoPerdas)),
    CustoTotal:String(num(r.CustoTotal)),QuantidadeBaseCusto:String(q),UMBaseCusto:op.UM||'',
    CustoUnitario:String(q?num(r.CustoTotal)/q:0),EnergiaKWh:String((a.etapas||[]).reduce((s,e)=>s+num(e.EnergiaKWh),0)),
    CustoFechado:'SIM',FonteCusto:'ENCERRAMENTO_OP',StatusOPNoFechamento:op.Status||'',
    Observacoes:'Snapshot imutável do custo consolidado no encerramento da OP. Demais módulos somente leem este registro.',
    AuditoriaFechamento:v104SnapshotAudit(a)
  };
  data.custos_op=data.custos_op||[];
  const i=data.custos_op.findIndex(x=>String(x.CodOP||x.CodOPMae||'')===String(cod));
  if(i>=0)data.custos_op[i]=row;else data.custos_op.unshift(row);
  op.CustoFechadoTotal=row.CustoTotal;op.CustoFechadoUnitario=row.CustoUnitario;op.CustoFechadoEm=row.DataFechamentoCusto;
  saveLocal();return row;
}

// Ao encerrar: primeiro executa todo o fluxo validado; somente se a OP terminou fechada congela seu custo.
const _encerrarOPSelecionadaV104=encerrarOPSelecionada;
encerrarOPSelecionada=function(selectId){
  const opAntes=selectedOP(selectId),cod=opAntes?.CodOP||'';
  const ret=_encerrarOPSelecionadaV104(selectId);
  const opDepois=opPorCodigo(cod);
  if(cod && v104IsClosed(opDepois)){
    try{v104FreezeCost(cod,false);v403SyncPILots();saveLocal();}catch(e){console.error('Falha ao congelar custo da OP',e);alert('A OP foi encerrada, mas houve falha ao consolidar o custo fechado. Reabra e encerre novamente após verificar os apontamentos.');}
  }
  return ret;
};

function v104CostAuditHTML(row){
  const a=row?.AuditoriaFechamento||{};
  const q=num(row?.QuantidadeBaseCusto),u=num(row?.CustoUnitario),t=num(row?.CustoTotal);
  return `<div class="report"><h3>Memória auditável do custo fechado</h3>
    <div class="table-wrap"><table><thead><tr><th>OP-base</th><th>Quantidade produzida/base</th><th>UM</th><th>Custo total fechado</th><th>Custo unitário fechado</th><th>Regra</th></tr></thead><tbody><tr><td>${htmlEscape(row?.CodOP||'')}</td><td>${fmtMax4V395(q)}</td><td>${htmlEscape(row?.UMBaseCusto||'')}</td><td>${money(t)}</td><td>${money(u)} / ${htmlEscape(row?.UMBaseCusto||'UM')}</td><td>Custo total fechado ÷ quantidade-base = custo unitário</td></tr></tbody></table></div>
    <h3>Materiais</h3>${tableHTML(a.materiais||[],['OP','Etapa','CodigoMaterial','Material','Quantidade','UM','Lote','Entrada','Fornecedor','CustoUnitario','Cálculo aberto','Resultado'])}
    <h3>Energia e MOD</h3>${tableHTML(a.etapas||[],['OP','Ordem','Processo','Equipamento','TempoMin','Pessoas','PotenciaW','EnergiaKWh','CustoEnergia','CustoMOD'])}
    <h3>Perdas</h3>${tableHTML(a.perdas||[],['OP','Etapa','Processo','Equipamento','Tipo','Item','QuantidadePerdida','UM','CustoUnitario','Cálculo aberto','Resultado','Regra','Composicao'])}
    <h3>Regras registradas no fechamento</h3>${tableHTML(a.regras||[],Object.keys((a.regras||[])[0]||{}))}</div>`;
}

// Custos Industriais deixa de recalcular. É somente consulta da fonte fechada.
custosModule=function(){
  $('title').textContent='Custos Industriais';$('subtitle').textContent='Fonte única: custo consolidado e congelado no encerramento da OP. Esta tela não recalcula custos.';
  $('content').innerHTML=`<div class="toolbar"><label>OP / escopo<select id="c_op"><option value="">Selecione uma OP</option>${v4033CostOptions()}</select></label><button onclick="v104LoadClosedCost()">Carregar custo fechado</button><button class="secondary" onclick="v104ExportClosedCost()">Exportar Excel auditável</button></div><div id="c_result"></div><h3>Histórico de custos fechados</h3><div>${table('custos_op')}</div>`;
};
function v104LoadClosedCost(){
  const cod=$('c_op')?.value;if(!cod)return alert('Selecione uma OP.');const op=opPorCodigo(cod)||{},row=v104SavedCost(cod);
  if(!row)return alert(v104IsClosed(op)?'Esta OP está encerrada, mas não possui snapshot de custo fechado. Reabra e encerre a OP para consolidar o custo na nova regra.':'O custo definitivo é gravado ao encerrar a OP. Esta OP ainda está aberta.');
  $('c_result').innerHTML=`<div class="cards"><div class="card"><b>Escopo</b><div class="metric">${htmlEscape(row.Escopo||'')}</div></div><div class="card"><b>Custo total fechado</b><div class="metric">${money(row.CustoTotal)}</div></div><div class="card"><b>Materiais</b><div class="metric">${money(row.CustoMateriais)}</div></div><div class="card"><b>Energia</b><div class="metric">${money(row.CustoEnergia)}</div></div><div class="card"><b>Mão de obra</b><div class="metric">${money(row.CustoMOD)}</div></div><div class="card"><b>Perdas</b><div class="metric">${money(row.CustoPerdas)}</div></div></div>${v104CostAuditHTML(row)}`;
}
function v104ExportClosedCost(){
  const cod=$('c_op')?.value,row=v104SavedCost(cod);if(!cod)return alert('Selecione uma OP.');if(!row)return alert('Não há custo fechado salvo para esta OP.');const a=row.AuditoriaFechamento||{};
  downloadAuditExcelV3819(`custo_fechado_${cod}.xls`,`Custo fechado — ${cod}`,[{title:'Resumo fechado',rows:[row]},{title:'Materiais',rows:a.materiais||[]},{title:'Energia e MOD',rows:a.etapas||[]},{title:'Perdas',rows:a.perdas||[]},{title:'Regras',rows:a.regras||[]}]);
}
// Compatibilidade de botões antigos: nunca recalcular fora do fechamento.
v4033CalcCostSelected=v104LoadClosedCost;v4033ExportCostSelected=v104ExportClosedCost;

// PI/lote: custo vem EXCLUSIVAMENTE do snapshot fechado da OP de origem.
v403SourceCost=function(lot){
  const op=opPorCodigo(lot?.CodOPOrigem)||{},row=v104SavedCost(op.CodOP),q=row?num(row.QuantidadeBaseCusto):(v403Produced(op)||num(lot?.QuantidadeProduzida)||1);
  if(!row)return {q,total:0,mat:0,en:0,mod:0,loss:0,missing:true,sourceOP:op.CodOP};
  return {q,total:num(row.CustoTotal),mat:num(row.CustoMateriais),en:num(row.CustoEnergia),mod:num(row.CustoMOD),loss:num(row.CustoPerdas),unit:num(row.CustoUnitario),sourceOP:op.CodOP,row};
};
function v104ClosedCostsForProduct(cod){
  const ops=(data.op||[]).filter(o=>v104IsClosed(o)&&String(o.CodigoPI||o.CodigoProduto||o.Produto||'')===String(cod));
  return ops.map(o=>({op:o,row:v104SavedCost(o.CodOP)})).filter(x=>x.row).sort((a,b)=>String(b.op.DataEncerramento||b.row.DataFechamentoCusto||'').localeCompare(String(a.op.DataEncerramento||a.row.DataFechamentoCusto||'')));
}
function v104SimAudit(d){
  return `<div class="report"><h3>Memória auditável da simulação</h3><div class="table-wrap"><table><thead><tr><th>Produto</th><th>OP-base do custo</th><th>Qtd. base fechada</th><th>UM</th><th>Custo total fechado</th><th>Custo unitário</th><th>Qtd. simulada</th><th>Cálculo</th><th>Resultado</th></tr></thead><tbody><tr><td>${htmlEscape(d.Produto||'')}</td><td>${htmlEscape(d.OPBase||'')}</td><td>${fmtMax4V395(d.QtdBase)}</td><td>${htmlEscape(d.UM||'')}</td><td>${money(d.CustoBase)}</td><td>${money(d.CustoUnitario)}</td><td>${fmtMax4V395(d.Quantidade)}</td><td>${fmtMax4V395(d.Quantidade)} × ${money(d.CustoUnitario)}</td><td><b>${money(d.Total)}</b></td></tr></tbody></table></div><p class="muted">A simulação não recalcula formulação, materiais, energia, MOD ou perdas. Ela utiliza o custo unitário consolidado no encerramento da OP-base.</p></div>`;
}

// Simulador de PI: lote ou OP fechada de referência. Não existe mais projeção pelo roteiro/formulação.
const _v4033RenderSimulatorBodyV104Base=v4033RenderSimulatorBody;
v4033RenderSimulatorBody=function(){
  const mode=$('v4033_sim_mode')?.value||'PA',cod=$('v4033_sim_product')?.value,box=$('v4033_sim_body');if(!box)return;
  if(mode!=='PI')return _v4033RenderSimulatorBodyV104Base();
  const prod=v101Produto(cod),um=v101ProductUM(cod)||prod.UM||'',lots=v403LotesDisponiveis(cod),refs=v104ClosedCostsForProduct(cod);
  const lotOpts=lots.map(l=>`<option value="LOT:${htmlEscape(l.IdLotePI)}">Lote ${htmlEscape(l.IdLotePI)} — OP ${htmlEscape(l.CodOPOrigem||'')} — saldo ${fmtMax4V395(v403SaldoLote(l))} ${htmlEscape(l.UM||um)}</option>`).join('');
  const opOpts=refs.map(x=>`<option value="OP:${htmlEscape(x.op.CodOP)}">OP fechada ${htmlEscape(x.op.CodOP)} — ${money(x.row.CustoUnitario)}/${htmlEscape(x.row.UMBaseCusto||um)}</option>`).join('');
  box.innerHTML=`<div class="form-grid"><label><span>Quantidade a simular</span><input id="v4033_pi_q" type="number" min="0.0001" step="0.0001" value="1"></label><label><span>UM</span><input readonly value="${htmlEscape(um)}"></label><label class="wide"><span>Base de custo fechada</span><select id="v4033_pi_origin">${lotOpts}${opOpts}${(!lotOpts&&!opOpts)?'<option value="">Nenhuma OP fechada com custo disponível</option>':''}</select><small>A simulação usa somente custo consolidado de OP encerrada.</small></label></div>`;
};

v4033CalcSimulator=function(){
  const mode=$('v4033_sim_mode')?.value||'PA';if(mode==='PA')return v104CalcPASimulation();
  const pi=$('v4033_sim_product')?.value,q=num($('v4033_pi_q')?.value),act=$('v4033_pi_origin')?.value||'';if(!(q>0))return alert('A quantidade do PI deve ser maior que zero.');if(!act)return alert('Não existe uma OP fechada com custo consolidado para servir de base.');
  let row,opBase='',um=v101ProductUM(pi)||'';
  if(act.startsWith('LOT:')){const l=(data.pi_lotes||[]).find(x=>x.IdLotePI===act.slice(4));if(!l)return alert('Lote não encontrado.');if(q>v403SaldoLote(l)+1e-9)return alert(`Saldo insuficiente. Disponível: ${fmtMax4V395(v403SaldoLote(l))} ${l.UM||''}.`);row=v104SavedCost(l.CodOPOrigem);opBase=l.CodOPOrigem;um=l.UM||um;}
  else {opBase=act.slice(3);row=v104SavedCost(opBase);}
  if(!row)return alert('A OP-base selecionada não possui custo fechado consolidado.');
  const unit=num(row.CustoUnitario),factorBase=num(row.QuantidadeBaseCusto)||1,total=q*unit;
  const f=q/factorBase,d={PI:pi,Origem:act.startsWith('LOT:')?act.slice(4):opBase,Quantidade:q,UM:um,Materiais:num(row.CustoMateriais)*f,Energia:num(row.CustoEnergia)*f,MOD:num(row.CustoMOD)*f,Perdas:num(row.CustoPerdas)*f,Total:total};
  $('sim_result').innerHTML=`<div class="card"><h3>Simulação do PI ${htmlEscape(pi)}</h3>${tableHTML([d],['PI','Origem','Quantidade','UM','Materiais','Energia','MOD','Perdas','Total'])}</div>${v104SimAudit({Produto:pi,OPBase:opBase,QtdBase:factorBase,UM:row.UMBaseCusto||um,CustoBase:num(row.CustoTotal),CustoUnitario:unit,Quantidade:q,Total:total})}`;
};

// PA: para o custo total da simulação, também usa a última OP PA fechada como referência.
// O multiplicador representa quantas vezes a quantidade-base fechada será simulada.
function v104CalcPASimulation(){
  const pa=$('v4033_sim_product')?.value,mult=num($('v403_sim_mult')?.value)||1,refs=v104ClosedCostsForProduct(pa);if(!refs.length)return alert('Não existe OP fechada deste PA com custo consolidado para servir de base da simulação.');
  const {op,row}=refs[0],qBase=num(row.QuantidadeBaseCusto)||num(op.QtdProduzida)||num(op.QtdPlanejada)||1,q=qBase*mult,unit=num(row.CustoUnitario),total=q*unit,f=q/qBase;
  const d={PA:pa,OPBase:op.CodOP,Quantidade:q,UM:row.UMBaseCusto||op.UM||'',Materiais:num(row.CustoMateriais)*f,Energia:num(row.CustoEnergia)*f,MOD:num(row.CustoMOD)*f,Perdas:num(row.CustoPerdas)*f,Total:total};
  $('sim_result').innerHTML=`<div class="card"><h3>Simulação do PA ${htmlEscape(pa)}</h3>${tableHTML([d],['PA','OPBase','Quantidade','UM','Materiais','Energia','MOD','Perdas','Total'])}</div>${v104SimAudit({Produto:pa,OPBase:op.CodOP,QtdBase:qBase,UM:d.UM,CustoBase:num(row.CustoTotal),CustoUnitario:unit,Quantidade:q,Total:total})}`;
}
v403CalcSupplySimulation=v104CalcPASimulation;

// ---------- ANEXOS: captura File[] e todos os valores ANTES do primeiro await ----------
async function v104UploadFileList(files,scope,recordId){
  files=Array.from(files||[]);if(!files.length)return [];
  const out=[];for(const f of files){if(f.size>15*1024*1024)throw new Error(`O arquivo ${f.name} excede 15 MB.`);const base64=await v4047ReadFileBase64(f);const r=await fetch('/api/attachments',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scope,recordId,name:v4047FileNameSafe(f.name),mime:f.type||'application/octet-stream',dataBase64:base64})});if(!r.ok)throw new Error((await r.text())||`Falha ao salvar ${f.name}`);const a=await r.json();out.push({Nome:f.name,Tipo:f.type||'',Tamanho:f.size,Url:a.url||'',Path:a.path||'',DataUpload:new Date().toLocaleString('pt-BR')});}return out;
}
