/* =========================================================
   MES LION V1.0.8 — DASHBOARD: CONVERGÊNCIA + MONTAGEM/TESTES
   Alterações exclusivas do Dashboard:
   - Linhas Cátodo e Ânodo permanecem paralelas.
   - Ambas convergem visualmente para a seção Montagem / Testes.
   - Jelly Roll pertence à seção Montagem / Testes.
   - Processos comuns seguem horizontalmente até o PA final.
   - Uma única rolagem horizontal contempla todo o fluxo.
   - KPIs e cartões mais compactos, sem alterar cálculos/regras dos módulos.
   ========================================================= */
const APP_VERSION_V108='V1.0.8';

function v108LaneTrack(nodes,all,kind){
  const arrow='<span class="v105-arrow v108-arrow">→</span>';
  return nodes.map((n,i)=>`${i?arrow:''}${v107NodeCard(n,all,kind)}`).join('');
}
function v108LaneHTML(label,sign,kind,nodes,all){
  if(!nodes.length)return '';
  return `<div class="v108-lane v108-${kind}">
    <div class="v108-lane-label"><i>${sign}</i><b>${label}</b></div>
    <div class="v108-lane-track">${v108LaneTrack(nodes,all,kind)}</div>
  </div>`;
}
function v108AssemblyHTML(nodes,all,showJoin=true){
  if(!nodes.length)return '';
  const arrow='<span class="v105-arrow v108-arrow v108-assembly-arrow">→</span>';
  const cards=nodes.map((n,i)=>`${i?arrow:''}${v107NodeCard(n,all,'assembly')}`).join('');
  return `${showJoin?`<div class="v108-join" aria-label="Convergência de cátodo e ânodo"><span class="v108-join-cath">→</span><span class="v108-join-an">→</span></div>`:''}
    <section class="v108-assembly">
      <div class="v108-assembly-title">Montagem / Testes</div>
      <div class="v108-assembly-track">${cards}</div>
    </section>`;
}
function v108RenderWip(id){
  const root=document.getElementById(id);if(!root)return;
  const cod=root.querySelector('.v105-op-select')?.value||'',proc=root.querySelector('.v105-proc-select')?.value||'';
  const op=(data.op||[]).find(o=>String(o.CodOP||'')===String(cod));
  const meta=root.querySelector('.v105-wip-meta'),flow=root.querySelector('.v105-flow');
  if(!op){meta.innerHTML='';flow.innerHTML='<div class="v105-empty">Nenhuma OP disponível para este WIP.</div>';return;}
  meta.innerHTML=`<span><b>Química:</b> ${htmlEscape(v105Chem(op))}</span><span><b>Tipo de célula:</b> ${htmlEscape(v105Type(op))}</span><span><b>Escala:</b> ${htmlEscape(v105Scale(op))}</span><span><b>Formulação:</b> ${htmlEscape(v105Formula(op))}</span>`;
  const all=v106FamilySequence(op);
  const nodes=proc?all.filter(n=>n.process===proc):all;
  if(!nodes.length){flow.innerHTML='<div class="v105-empty">A OP selecionada não possui etapas para o processo escolhido.</div>';return;}

  if(!v105IsPA(op)){
    const pol=v107PolarityOfNode(nodes[0]);
    if(pol==='shared'){
      flow.innerHTML=`<div class="v108-flow-scroll"><div class="v108-single-assembly">${v108AssemblyHTML(nodes,all,false)}</div></div>`;
    }else{
      const kind=pol==='anode'?'anode':'cathode',label=kind==='anode'?'ÂNODO':'CÁTODO',sign=kind==='anode'?'−':'+';
      flow.innerHTML=`<div class="v108-flow-scroll"><div class="v108-single-lane">${v108LaneHTML(label,sign,kind,nodes,all)}</div></div>`;
    }
    return;
  }

  const cath=nodes.filter(n=>v107PolarityOfNode(n)==='cathode');
  const an=nodes.filter(n=>v107PolarityOfNode(n)==='anode');
  const shared=nodes.filter(n=>v107PolarityOfNode(n)==='shared');
  const haveElectrodes=cath.length||an.length;
  const electrodeHTML=`<div class="v108-electrodes">${v108LaneHTML('CÁTODO','+','cathode',cath,all)}${v108LaneHTML('ÂNODO','−','anode',an,all)}</div>`;
  const assemblyHTML=v108AssemblyHTML(shared,all,haveElectrodes&&shared.length);
  flow.innerHTML=`<div class="v108-flow-scroll"><div class="v108-flow-map ${shared.length?'has-assembly':'no-assembly'}">${electrodeHTML}${assemblyHTML}</div></div>`;
}
function v108WipOpChanged(id){
  const root=document.getElementById(id);if(!root)return;
  const op=(data.op||[]).find(o=>String(o.CodOP||'')===String(root.querySelector('.v105-op-select')?.value||''));
  const sel=root.querySelector('.v105-proc-select');
  if(sel)sel.innerHTML='<option value="">Todos os processos</option>'+(op?v106ProcessOptions(op).map(p=>`<option value="${htmlEscape(p)}">${htmlEscape(p)}</option>`).join(''):'');
  v108RenderWip(id);
}
