const APP_VERSION_V109='V1.0.9';

function v109CostHistoryTable(){
  const rows=data.custos_op||[];
  const cols=fields.custos_op&&fields.custos_op.length?fields.custos_op:Object.keys(rows[0]||{});
  const safeCols=cols.filter(c=>c!=='AuditoriaFechamento');
  if(!rows.length)return '<div class="v105-empty">Nenhum custo fechado registrado.</div>';
  return `<div class="table-wrap"><table><thead><tr><th>Ações</th>${safeCols.map(c=>`<th>${htmlEscape(c)}</th>`).join('')}</tr></thead><tbody>${rows.map((r,i)=>`<tr><td><button class="mini" onclick="v109ViewClosedCost(${i})">Visualizar</button></td>${safeCols.map(c=>`<td>${htmlEscape(r[c]??'')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}

function v109ViewClosedCost(idx){
  const row=(data.custos_op||[])[idx];
  if(!row)return alert('Custo fechado não encontrado.');
  const cod=String(row.CodOP||row.CodOPMae||'');
  const sel=$('c_op');
  if(sel && [...sel.options].some(o=>String(o.value)===cod))sel.value=cod;
  const box=$('c_result');
  if(!box)return;
  box.innerHTML=`<div class="cards"><div class="card"><b>Escopo</b><div class="metric">${htmlEscape(row.Escopo||'')}</div></div><div class="card"><b>Custo total fechado</b><div class="metric">${money(row.CustoTotal)}</div></div><div class="card"><b>Materiais</b><div class="metric">${money(row.CustoMateriais)}</div></div><div class="card"><b>Energia</b><div class="metric">${money(row.CustoEnergia)}</div></div><div class="card"><b>Mão de obra</b><div class="metric">${money(row.CustoMOD)}</div></div><div class="card"><b>Perdas</b><div class="metric">${money(row.CustoPerdas)}</div></div></div>${v104CostAuditHTML(row)}`;
  box.scrollIntoView({behavior:'smooth',block:'start'});
}

