/* =========================================================
   MES LION V1.0.10 — DASHBOARD: MATERIAIS USADOS + PERDIDOS
   Alteração exclusiva do KPI do Dashboard:
   - O KPI financeiro deixa de exibir custo total de fabricação.
   - Passa a somar apenas CustoMateriais + CustoPerdas das OPs concluídas.
   - Energia e mão de obra não entram neste indicador.
   - Usa exclusivamente os custos já fechados/salvos das OPs; não recalcula.
   ========================================================= */
const APP_VERSION_V110='V1.0.10';

function v110MaterialCostKpi(){
  const closed=new Set((data.op||[]).filter(o=>v105Closed(o)&&!v105Cancelled(o)).map(o=>String(o.CodOP||'')));
  const latest=new Map();
  (data.custos_op||[]).forEach((r,i)=>{
    const key=String(r.CodOP||r.CodOPMae||'');
    if(!key||!closed.has(key))return;
    // Mantém um único snapshot por OP. Se houver mais de um registro histórico,
    // o último registro armazenado é a fonte vigente, sem somar duplicado.
    latest.set(key,{row:r,index:i});
  });
  let used=0,lost=0;
  latest.forEach(({row})=>{
    used+=num(row.CustoMateriais);
    lost+=num(row.CustoPerdas);
  });
  return {used,lost,total:used+lost};
}

function v110Kpis(){
  const k=v106Kpis();
  const materials=v110MaterialCostKpi();
  return {...k,materialUsed:materials.used,materialLost:materials.lost,materialTotal:materials.total};
}

function v110TopHTML(){
  const k=v110Kpis();
  return `<section class="v105-kpis v106-kpis">
    <article><span class="v105-kpi-icon green">◉</span><div><small>Eletrodo produzido</small><b>${v105Format(k.electrodeKm,2)} km</b><em>acumulado</em></div></article>
    <article><span class="v105-kpi-icon blue">▣</span><div><small>Capacidade energética</small><b>${v105Format(k.capacityKWh,2)} kWh</b><em>concluída</em></div></article>
    <article><span class="v105-kpi-icon blue">▤</span><div><small>OPs concluídas</small><b>${Math.round(k.concluded)}</b><em>acumulado</em></div></article>
    <article title="Materiais usados: ${money(k.materialUsed)} | Materiais perdidos: ${money(k.materialLost)}"><span class="v105-kpi-icon blue">$</span><div><small>Materiais</small><b>${money(k.materialTotal)}</b><em>usados + perdidos</em></div></article>
    <article class="v105-cell-kpi"><span class="v105-kpi-icon green">▥</span><div><small>Células concluídas</small><b>${v105Format(k.cells,0)} un.</b><em>acumulado</em></div></article>
    <article><span class="v105-kpi-icon green">CO₂</span><div><small>Emissões acumuladas</small><b>${v105Format(k.co2,3)} kg</b><em>kg CO₂eq total</em></div></article>
  </section>`;
}

