/* =========================================================
   MES LION V1.0.11 — CADEIA PI / OP E FORMULAÇÃO RESTRITA AO SLURRY
   - Formulação selecionada na geração da família é aplicada SOMENTE às OPs de slurry.
   - PIs intermediários são consumidos pela etapa seguinte e podem ser apontados como perda.
   - Cadeia: Slurry -> Deposição -> Eletrodo depositado -> Corte -> Eletrodo cortado -> Jelly Roll -> PA.
   - PI pronto/lote pode abastecer qualquer PA compatível pelo Tipo PI; nesse caso não é criada nova OP do PI.
   - Geração mostra código + nome do PI + processo + origem + UM + quantidade, evitando OPs "no escuro".
   - Tela da OP mostra a estrutura da família/roteiro para validação das etapas e quantidades.
   ========================================================= */
const APP_VERSION_V1011='V1.0.11';

data.op_pi_consumos=data.op_pi_consumos||[];
data.pi_lotes=data.pi_lotes||[];

function v1011Norm(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
function v1011Prod(cod){return (data.estrutura||[]).find(p=>String(p['Código']||'')===String(cod||''))||{};}
function v1011ProductCode(op){return String(op?.CodigoPI||op?.ProdutoGerado||op?.Produto||op?.CodigoProduto||'');}
function v1011Role(x){
  const cod=typeof x==='string'?x:v1011ProductCode(x),p=v1011Prod(cod);
  const stages=typeof x==='object'&&x?.CodOP?(data.op_etapas||[]).filter(e=>e.CodOP===x.CodOP):[];
  const t=v1011Norm([p['Tipo PI'],p['Descrição'],typeof x==='object'?x?.DescricaoProduto:'',...stages.map(e=>e.Processo)].join(' '));
  if(/slurry/.test(t)&&/catod/.test(t))return 'SLURRY_CAT';
  if(/slurry/.test(t)&&/anod/.test(t))return 'SLURRY_AN';
  if(/deposit|coating|revest/.test(t)&&/catod/.test(t))return 'DEP_CAT';
  if(/deposit|coating|revest/.test(t)&&/anod/.test(t))return 'DEP_AN';
  if(/cortad|corte/.test(t)&&/catod/.test(t))return 'CUT_CAT';
  if(/cortad|corte/.test(t)&&/anod/.test(t))return 'CUT_AN';
  if(/jelly/.test(t))return 'JELLY';
  if(String(p['Tipo Produto']||'').toUpperCase()==='PA'||/^PA/i.test(cod))return 'PA';
  return 'OTHER';
}
function v1011IsSlurry(x){return ['SLURRY_CAT','SLURRY_AN'].includes(v1011Role(x));}
function v1011RoleLabel(role){return ({SLURRY_CAT:'Slurry Cátodo',SLURRY_AN:'Slurry Ânodo',DEP_CAT:'Eletrodo Depositado Cátodo',DEP_AN:'Eletrodo Depositado Ânodo',CUT_CAT:'Eletrodo Cortado Cátodo',CUT_AN:'Eletrodo Cortado Ânodo',JELLY:'Jelly Roll',PA:'Produto Acabado'})[role]||'PI';}
function v1011PrevRoles(role){return ({DEP_CAT:['SLURRY_CAT'],DEP_AN:['SLURRY_AN'],CUT_CAT:['DEP_CAT'],CUT_AN:['DEP_AN'],JELLY:['CUT_CAT','CUT_AN'],PA:['JELLY']})[role]||[];}
function v1011RouteOrder(r,cod){
  const es=(data.roteiro_etapas||[]).filter(e=>e.CodRoteiro===r.CodRoteiro&&String(e.ProdutoGerado||e.CodigoProduto||e.CodigoPI||'')===String(cod));
  return es.length?Math.min(...es.map(e=>num(e.Ordem)||999999)):999999;
}
function v1011RouteProcess(r,cod){
  const e=(data.roteiro_etapas||[]).filter(x=>x.CodRoteiro===r.CodRoteiro&&String(x.ProdutoGerado||x.CodigoProduto||x.CodigoPI||'')===String(cod)).sort((a,b)=>num(a.Ordem)-num(b.Ordem))[0]||{};
  return e.Processo||'';
}
function v1011RouteProducts(r){
  return roteiroProdutosV32(r).filter(Boolean).sort((a,b)=>v1011RouteOrder(r,a)-v1011RouteOrder(r,b));
}
function v1011LotsForRole(role){
  try{v403SyncPILots();}catch(e){}
  return (data.pi_lotes||[]).filter(l=>v1011Role(l.CodigoPI)===role && v403SaldoLote(l)>0.0000001);
}
function v1011LotLabel(l){
  const p=v1011Prod(l.CodigoPI),src=typeof v104SavedCost==='function'?v104SavedCost(l.CodOPOrigem):null,unit=src?num(src.CustoUnitario):0;
  return `${l.IdLotePI} — ${l.CodigoPI} ${p['Descrição']||l.DescricaoPI||''} — saldo ${fmtMax4V395(v403SaldoLote(l))} ${l.UM||''}${unit?` — ${money(unit)}/${l.UM||'UM'}`:''}`;
}
function v1011StripFormulaFromNonSlurry(op){
  if(!op||v1011IsSlurry(op))return;
  data.op_materiais=(data.op_materiais||[]).filter(m=>!(m.CodOP===op.CodOP && (m.CodFormula||String(m.OrigemQuantidade||'')==='FORMULA_OP'||String(m.TipoConsumo||'').toLowerCase()==='formulação')));
  ['CodFormula','NomeFormula','VersaoFormula','QuimicaFormula','FormulaCongelada','DataFormulaOP','SnapshotFormula','GrupoFormulaAplicado','MassaTotalFormulada','PercentualSolidos','PercentualSolvente','MassaSolidos','MassaSolvente','MassaAposDeposicao'].forEach(k=>{op[k]='';});
}
function v1011CleanOpenNonSlurryFormula(){
  (data.op||[]).filter(o=>!v403StatusClosed(o)&&!v1011IsSlurry(o)).forEach(v1011StripFormulaFromNonSlurry);
}

// Formulação só pertence ao PI slurry. Não propaga composição para coating, corte, jelly roll ou PA.
aplicarFormulaNasOPsV3813=function(ops,codFormula){
  const f=v101EnsureFormulaRatios(formulaByCodeV3813(codFormula),codFormula);if(!f)throw new Error('Formulação não encontrada.');
  const todos=v101FormulaItems(codFormula);
  (ops||[]).forEach(op=>{
    v101SyncOPUnit(op);
    if(!v1011IsSlurry(op)){v1011StripFormulaFromNonSlurry(op);return;}
    const role=v1011Role(op),grupo=role==='SLURRY_CAT'?'CATODO':'ANODO';
    op.CodFormula=f.CodFormula;op.NomeFormula=f.Nome||'';op.VersaoFormula=f.Versao||'1';op.QuimicaFormula=f.Quimica||'';op.FormulaCongelada='Sim';op.DataFormulaOP=new Date().toLocaleString('pt-BR');op.SnapshotFormula=JSON.stringify({cabecalho:{...f},itens:todos.map(i=>({...i}))});op.GrupoFormulaAplicado=grupo;
    v4050ClearRouteQuantitiesOnOP(op);v4050RecalculateFormulaOP(op.CodOP,false);
  });
  return ops;
};
const _v4050RecalcV1011=v4050RecalculateFormulaOP;
v4050RecalculateFormulaOP=function(codOP,persist=true){const op=opPorCodigo(codOP);if(!op||!v1011IsSlurry(op)){if(op)v1011StripFormulaFromNonSlurry(op);if(persist)saveLocal();return;}return _v4050RecalcV1011(codOP,persist);};
v4050RefreshCalculatedData=function(){(data.op||[]).forEach(o=>{if(o.CodFormula&&v1011IsSlurry(o))v4050RecalculateFormulaOP(o.CodOP,false);});v4050ApplyDepositionMassInfo();};

function v1011PlanningRowsHTML(r,codFormula){
  const rows=v1011RouteProducts(r);
  return `<div class="v1011-family-plan"><div class="card"><h3>Estrutura da produção — informe origem e quantidade de cada PI</h3><p class="muted">A formulação <b>${htmlEscape(codFormula||'')}</b> será aplicada somente aos slurrys. Para os demais PIs, a etapa consome o PI anterior. Se um PI pronto for selecionado, nenhuma OP será criada para fabricá-lo.</p><div class="table-wrap"><table><thead><tr><th>Seq.</th><th>PI / PA</th><th>Nome</th><th>Processo</th><th>Origem</th><th>Lote PI pronto</th><th>Quantidade / massa a produzir ou disponibilizar</th><th>UM</th></tr></thead><tbody>${rows.map((cod,i)=>{
    const p=v1011Prod(cod),role=v1011Role(cod),isPA=role==='PA',lots=isPA?[]:v1011LotsForRole(role),um=v101ProductUM(cod,r)||prodUMV382(cod)||unidadeProdutoV35(cod)||'un';
    const opts=lots.map(l=>`<option value="${htmlEscape(l.IdLotePI)}">${htmlEscape(v1011LotLabel(l))}</option>`).join('');
    return `<tr class="v1011-plan-row" data-code="${htmlEscape(cod)}" data-role="${role}"><td>${i+1}</td><td><b>${htmlEscape(cod)}</b></td><td>${htmlEscape(p['Descrição']||'')}</td><td>${htmlEscape(v1011RouteProcess(r,cod)||v1011RoleLabel(role))}</td><td>${isPA?'<b>Produzir PA</b>':`<select class="v1011-origin" onchange="v1011ToggleLot(this)"><option value="PRODUZIR">Produzir nova OP</option><option value="LOTE" ${lots.length?'':'disabled'}>Usar PI pronto / lote existente${lots.length?'':' (sem saldo)'}</option></select>`}</td><td>${isPA?'—':`<select class="v1011-lot" ${lots.length?'disabled':''}>${opts||'<option value="">Sem lote compatível</option>'}</select>`}</td><td><input class="v1011-qtd" type="number" min="0" step="0.000001" placeholder="Informe ${um}"></td><td><b>${htmlEscape(um)}</b></td></tr>`;
  }).join('')}</tbody></table></div><div class="form-actions"><button class="green" onclick="v1011ConfirmFamily('${jsq(r.CodRoteiro)}','${jsq(codFormula)}')">Gerar estrutura de OPs</button><button class="secondary" onclick="$ ('crudBox').innerHTML=''">Cancelar</button></div></div></div>`.replace("$ ('crudBox')","$('crudBox')");
}
function v1011ToggleLot(sel){const row=sel.closest('.v1011-plan-row'),lot=row?.querySelector('.v1011-lot');if(lot)lot.disabled=sel.value!=='LOTE';}
function v1011ReadPlan(){return [...document.querySelectorAll('.v1011-plan-row')].map(row=>({code:row.dataset.code,role:row.dataset.role,origin:row.querySelector('.v1011-origin')?.value||'PRODUZIR',lotId:row.querySelector('.v1011-lot')?.value||'',q:num(row.querySelector('.v1011-qtd')?.value),um:row.querySelector('td:last-child')?.textContent?.trim()||''}));}

gerarOPsComFormulaV3813=function(r,ignorado,codFormula){
  if(!r?.CodRoteiro)return alert('Selecione um roteiro salvo.');
  if(!codFormula)return alert('Selecione a formulação dos slurrys.');
  const f=formulaByCodeV3813(codFormula);if(!f||String(f.Status||'').toUpperCase()!=='ATIVA')return alert('Selecione uma formulação ativa.');
  const box=$('crudBox');if(!box)return;
  box.innerHTML=v1011PlanningRowsHTML(r,codFormula);box.scrollIntoView({behavior:'smooth',block:'start'});
};

function v1011AddPIInput(consumer,source,rootPA,r){
  if(!consumer||!source)return;
  const sourceCode=source.code||source.op?.Produto||source.lot?.CodigoPI||'',p=v1011Prod(sourceCode),role=v1011Role(sourceCode),q=num(source.q),um=source.um||source.op?.UM||source.lot?.UM||v101ProductUM(sourceCode,r)||'';
  const stage=(data.op_etapas||[]).filter(e=>e.CodOP===consumer.CodOP).sort((a,b)=>num(a.Ordem)-num(b.Ordem))[0]||{};
  const existing=(data.op_materiais||[]).find(m=>m.CodOP===consumer.CodOP&&String(m.CodigoMaterial)===String(sourceCode)&&String(m.TipoConsumo||'').toLowerCase().includes('pi intermedi'));
  let unit=0,lotId='',opOrig='';
  if(source.lot){lotId=source.lot.IdLotePI;opOrig=source.lot.CodOPOrigem;const c=typeof v104SavedCost==='function'?v104SavedCost(opOrig):null;unit=c?num(c.CustoUnitario):0;}
  else if(source.op){opOrig=source.op.CodOP;const c=typeof v104SavedCost==='function'?v104SavedCost(opOrig):null;unit=c?num(c.CustoUnitario):0;}
  const row=existing||{CodOP:consumer.CodOP,CodRoteiro:consumer.CodRoteiro||r.CodRoteiro,Ordem:stage.Ordem||'PI',OrdemEtapa:stage.Ordem||'PI',CodigoProduto:consumer.Produto||consumer.CodigoProduto||'',CodigoPI:sourceCode,Processo:stage.Processo||'',IdRecursoRoteiro:stage.IdRecursoRoteiro||'',CodEquipamento:stage.CodEquipamento||'',CodigoMaterial:sourceCode,DescricaoMaterial:p['Descrição']||sourceCode,TipoConsumo:'PI intermediário'};
  Object.assign(row,{Lote:lotId,EntradaMaterial:opOrig,OPOrigemPI:opOrig,QtdPlanejada:q>0?String(q):'',QtdBase:'',UM:um,CustoUnitario:unit?String(unit):'',CustoTotal:unit&&q>0?String(unit*q):'',OrigemQuantidade:source.lot?'LOTE_PI_EXISTENTE':'OP_PI_PRODUZIDA',RegraQuantidade:'PI_CONSUMIDO_ETAPA_SEGUINTE',OrigemDados:'CADEIA_PI_V1.0.11',Observacoes:`${v1011RoleLabel(role)} consumido na etapa ${stage.Processo||''}. Pode ser apontado como consumo e perda.`});
  if(!existing)(data.op_materiais||[]).push(row);
  if(source.lot){
    const dup=(data.op_pi_consumos||[]).find(c=>c.CodOPConsumidora===consumer.CodOP&&c.IdLotePI===source.lot.IdLotePI&&String(c.Status||'ATIVO')!=='CANCELADO');
    if(!dup)(data.op_pi_consumos||[]).push({IdConsumoPI:'CPI-'+Date.now()+'-'+Math.random().toString(36).slice(2,8),CodOPPA:rootPA.CodOP,CodOPConsumidora:consumer.CodOP,OPBase:rootPA.OP_Base||rootPA.CodOP,CodigoPA:rootPA.Produto||rootPA.CodigoProduto||'',CodigoPI:sourceCode,TipoPI:p['Tipo PI']||v1011RoleLabel(role),IdLotePI:source.lot.IdLotePI,CodOPOrigemPI:source.lot.CodOPOrigem,QuantidadeConsumida:String(q),UM:um,DataConsumo:new Date().toLocaleString('pt-BR'),Status:'ATIVO',Origem:'LOTE_PI_EXISTENTE_ETAPA'});
  }
}

function v1011ConfirmFamily(codRoteiro,codFormula){
  const r=(data.roteiro||[]).find(x=>x.CodRoteiro===codRoteiro);if(!r)return alert('Roteiro não encontrado.');
  const plan=v1011ReadPlan();if(!plan.length)return alert('Estrutura do roteiro vazia.');
  for(const x of plan){if(!(x.q>0))return alert(`Informe a quantidade/massa de ${x.code} — ${v1011Prod(x.code)['Descrição']||''}.`);if(x.origin==='LOTE'){const lot=(data.pi_lotes||[]).find(l=>l.IdLotePI===x.lotId);if(!lot)return alert(`Selecione um lote para ${x.code}.`);if(x.q>v403SaldoLote(lot)+1e-9)return alert(`Saldo insuficiente no lote ${lot.IdLotePI}. Disponível: ${fmtMax4V395(v403SaldoLote(lot))} ${lot.UM||''}.`);}}
  const base=baseOPCode(),created=[],sourcesByRole={},sourceByCode={};let seq=1,pa=null;
  // Cria somente OPs realmente necessárias. PI pronto elimina a OP correspondente.
  plan.filter(x=>x.role!=='PA').forEach(x=>{
    if(x.origin==='LOTE'){
      const lot=(data.pi_lotes||[]).find(l=>l.IdLotePI===x.lotId);const src={code:lot.CodigoPI,role:x.role,lot,q:x.q,um:lot.UM||x.um};sourcesByRole[x.role]=src;sourceByCode[x.code]=src;return;
    }
    const op=v10CriarOPEstrutural(r,x.code,base+'-'+pad(seq++,2),base);op.QtdPlanejada=String(x.q);op.UM=x.um||v101ProductUM(x.code,r)||op.UM;op.OrigemQtdPlanejada='INFORMADA_NA_ESTRUTURA_DA_OP';op.OrigemGeracao='CADEIA_PI_V1.0.11';op.OP_Base=base;op.OP_Pai=base;(data.op_etapas||[]).filter(e=>e.CodOP===op.CodOP).forEach(e=>{e.QtdPlanejadaProduto=String(x.q);e.UMProduto=op.UM;});
    if(v1011IsSlurry(op))aplicarFormulaNasOPsV3813([op],codFormula);else v1011StripFormulaFromNonSlurry(op);
    const src={code:x.code,role:x.role,op,q:x.q,um:op.UM};sourcesByRole[x.role]=src;sourceByCode[x.code]=src;created.push(op);
  });
  const pRow=plan.find(x=>x.role==='PA');if(pRow){pa=v10CriarOPEstrutural(r,pRow.code,base+'-PA',base);pa.QtdPlanejada=String(pRow.q);pa.UM=pRow.um||v101ProductUM(pRow.code,r)||pa.UM;pa.OP_Base=pa.CodOP;pa.OP_Pai='';pa.OrigemQtdPlanejada='INFORMADA_NA_ESTRUTURA_DA_OP';pa.OrigemGeracao='CADEIA_PI_V1.0.11';(data.op_etapas||[]).filter(e=>e.CodOP===pa.CodOP).forEach(e=>{e.QtdPlanejadaProduto=String(pRow.q);e.UMProduto=pa.UM;});v1011StripFormulaFromNonSlurry(pa);created.push(pa);}
  if(!pa){pa=created[created.length-1]||null;}
  // Conecta cada PI como insumo da etapa seguinte. A relação é por Tipo PI, permitindo lotes de outro PA.
  created.forEach(consumer=>{const role=v1011Role(consumer);v1011PrevRoles(role).forEach(prev=>{const src=sourcesByRole[prev];if(src)v1011AddPIInput(consumer,src,pa,r);});});
  if(pa)v1011PrevRoles('PA').forEach(prev=>{const src=sourcesByRole[prev];if(src)v1011AddPIInput(pa,src,pa,r);});
  // Para rastreabilidade, todas as OPs novas da família apontam para o PA final.
  if(pa)created.filter(o=>o.CodOP!==pa.CodOP).forEach(o=>{o.OP_Pai=pa.CodOP;o.OP_Base=pa.CodOP;});
  v1011CleanOpenNonSlurryFormula();saveLocal();
  alert(`Estrutura criada com ${created.length} OP(s). ${plan.filter(x=>x.origin==='LOTE').length} PI(s) prontos foram reutilizados sem gerar nova OP.\n\nA formulação foi aplicada somente aos slurrys.`);
  render('op');setTimeout(()=>{if($('selOp')&&pa){$('selOp').value=pa.CodOP;showOP();}},80);
}

function v1011FamilyRoot(op){if(!op)return'';return String(op.TipoOP||'').toUpperCase()==='PA'?op.CodOP:(op.OP_Pai||op.OP_Base||op.CodOP);}
function v1011FamilyStructureHTML(op){
  const root=v1011FamilyRoot(op),pa=opPorCodigo(root)||((data.op||[]).find(o=>o.CodOP===root))||op,r=(data.roteiro||[]).find(x=>x.CodRoteiro===op.CodRoteiro);
  if(!r)return'';
  const family=(data.op||[]).filter(o=>o.CodOP===root||o.OP_Pai===root||o.OP_Base===root||o.CodOP===op.CodOP),byCode={};family.forEach(o=>byCode[v1011ProductCode(o)]=o);
  const inherited=(data.op_pi_consumos||[]).filter(c=>c.CodOPPA===root&&String(c.Status||'ATIVO')!=='CANCELADO');
  const rows=v1011RouteProducts(r).map(cod=>{
    const p=v1011Prod(cod),o=byCode[cod],role=v1011Role(cod),inh=inherited.find(c=>v1011Role(c.CodigoPI)===role),lot=inh?(data.pi_lotes||[]).find(l=>l.IdLotePI===inh.IdLotePI):null;
    return {Seq:v1011RouteOrder(r,cod),Código:cod,PI_PA:p['Descrição']||'',Processo:v1011RouteProcess(r,cod)||v1011RoleLabel(role),Origem:o?'OP a produzir':lot?`PI pronto — ${lot.IdLotePI}`:'Sem origem definida',OP:o?.CodOP||'—',Quantidade:o?.QtdPlanejada||inh?.QuantidadeConsumida||'',UM:o?.UM||inh?.UM||v101ProductUM(cod,r)||'',Status:o?.Status|| (lot?'Disponível em lote':'')};
  }).sort((a,b)=>num(a.Seq)-num(b.Seq));
  return `<div class="card v1011-op-structure"><h3>Estrutura do roteiro aplicada à família de OPs</h3><p class="muted">Use esta visão para validar a sequência, identificar o nome dos PIs e conferir as quantidades. A formulação aparece somente nas OPs de slurry; os demais PIs são consumidos na etapa seguinte.</p>${tableHTML(rows,['Seq','Código','PI_PA','Processo','Origem','OP','Quantidade','UM','Status'])}</div>`;
}
const _showOPV1011=showOP;
showOP=function(){
  const cod=$('selOp')?.value||'',op=opPorCodigo(cod);if(op&&!v1011IsSlurry(op)&&op.CodFormula)v1011StripFormulaFromNonSlurry(op);
  const ret=_showOPV1011();const now=opPorCodigo($('selOp')?.value||cod),box=$('opDet');if(now&&box&&!box.querySelector('.v1011-op-structure'))box.insertAdjacentHTML('afterbegin',v1011FamilyStructureHTML(now));return ret;
};

// Planejamento da OP: fórmula somente no slurry e PI intermediário fica visível como insumo da etapa.
const _v4050PlanV1011=v4050OPPlanningHTML;
v4050OPPlanningHTML=function(op){
  if(!v1011IsSlurry(op)&&op.CodFormula)v1011StripFormulaFromNonSlurry(op);
  let html=_v4050PlanV1011(op);
  const pis=(data.op_materiais||[]).filter(m=>m.CodOP===op.CodOP&&String(m.TipoConsumo||'').toLowerCase().includes('pi intermedi'));
  if(pis.length){const rows=pis.map(m=>({PI:m.CodigoMaterial,Descrição:m.DescricaoMaterial,Origem:m.Lote?`Lote ${m.Lote}`:(m.OPOrigemPI?`OP ${m.OPOrigemPI}`:'PI anterior'),Quantidade:m.QtdPlanejada,UM:m.UM,Processo:m.Processo}));html=html.replace('</div>',`<h4>PI consumido nesta etapa</h4><p class="muted">Este PI é insumo da etapa atual e também fica disponível para apontamento de perdas.</p>${tableHTML(rows,['PI','Descrição','Origem','Quantidade','UM','Processo'])}</div>`);}
  return html;
};

// Perda de PI intermediário: usa primeiro o lote/OP de origem explicitamente vinculado à etapa.
const _v102MatLossV1011=v102MaterialLossCost;
v102MaterialLossCost=function(p,op){
  const cod=p.CodigoMaterial||p.ItemPerdaCodigo||'';
  if(/^PI/i.test(cod)){
    const m=(data.op_materiais||[]).find(x=>x.CodOP===op?.CodOP&&String(x.CodigoMaterial)===String(cod)&&String(x.TipoConsumo||'').toLowerCase().includes('pi intermedi'))||{};
    let unit=0;
    if(m.Lote){const lot=(data.pi_lotes||[]).find(l=>l.IdLotePI===m.Lote);const c=lot&&typeof v104SavedCost==='function'?v104SavedCost(lot.CodOPOrigem):null;unit=c?num(c.CustoUnitario):0;}
    if(!unit&&m.OPOrigemPI){const c=typeof v104SavedCost==='function'?v104SavedCost(m.OPOrigemPI):null;if(c)unit=num(c.CustoUnitario);if(!unit){const src=opPorCodigo(m.OPOrigemPI),a=src? v4033AuditCostPI(src.CodOP):null,r=a?.resumo?.[0]||{},q=num(src?.QtdPlanejada)||num(src?.QtdProduzida)||1;unit=q?num(r.CustoMateriais)/q:0;}}
    if(unit>0)return {unit,total:num(p.QuantidadePerdida)*unit,rule:'Perda de PI intermediário = quantidade perdida × custo unitário congelado da OP/lote de origem'};
  }
  return _v102MatLossV1011(p,op);
};

// Deposição: custo/perda usa o slurry efetivamente vinculado à OP, nunca recompõe seus componentes na OP de coating.
v102SourceSlurryOP=function(depositionOp){
  const m=(data.op_materiais||[]).find(x=>x.CodOP===depositionOp?.CodOP&&String(x.TipoConsumo||'').toLowerCase().includes('pi intermedi')&&['SLURRY_CAT','SLURRY_AN'].includes(v1011Role(x.CodigoMaterial)));
  if(m?.OPOrigemPI)return opPorCodigo(m.OPOrigemPI)||null;
  if(m?.Lote){const l=(data.pi_lotes||[]).find(x=>x.IdLotePI===m.Lote);if(l)return opPorCodigo(l.CodOPOrigem)||null;}
  return null;
};

