/* =========================================================
   MES LION V1.0.13 — FLUXO ESTRUTURAR -> GERAR + OP LIMPA
   - Seleção roteiro/formulação: primeiro estrutura, depois gera.
   - OP: remove KPIs redundantes e planejamento individual antigo.
   - Validação de filhas, etapas/recursos e materiais/lotes recolhíveis.
   - Preenchimento centralizado de quantidades da família permanece.
   ========================================================= */
const APP_VERSION_V1013='V1.0.13';

function v1013WrapHeadingSection(box,headingText,cls){
  if(!box)return null;
  const hs=[...box.querySelectorAll('h3.section-title,h3')];
  const h=hs.find(x=>(x.textContent||'').trim().toLowerCase()===headingText.toLowerCase());
  if(!h||h.closest('details'))return h?.closest('details')||null;
  const d=document.createElement('details');
  d.className=`v1012-details ${cls||''}`;
  const s=document.createElement('summary');s.textContent=(h.textContent||headingText).trim();d.appendChild(s);
  const body=document.createElement('div');body.className='v1012-details-body';d.appendChild(body);
  h.parentNode.insertBefore(d,h);
  let n=h.nextSibling;h.remove();
  while(n){
    const next=n.nextSibling;
    if(n.nodeType===1){
      const el=n;
      if(el.matches('h3.section-title')||el.classList?.contains('v1012-family-bottom')||el.matches('details.v1012-details'))break;
      body.appendChild(el);
    }else if(String(n.textContent||'').trim()) body.appendChild(n);
    n=next;
  }
  return d;
}

function v1013WrapValidation(box){
  if(!box)return;
  const h=[...box.querySelectorAll('h3.section-title,h3')].find(x=>/Validação das OPs filhas/i.test(x.textContent||''));
  if(!h||h.closest('details'))return;
  const next=h.nextElementSibling;
  const d=document.createElement('details');d.className='v1012-details v1013-child-validation';
  d.innerHTML='<summary>Validação das OPs filhas</summary><div class="v1012-details-body"></div>';
  h.parentNode.insertBefore(d,h);h.remove();if(next)d.querySelector('.v1012-details-body').appendChild(next);
}

// A tela da OP deixa de repetir planejamento/custos que já são tratados nos blocos próprios da família.
const _showOPV1013=showOP;
showOP=function(){
  const ret=_showOPV1013();
  const box=$('opDet');if(!box)return ret;
  box.querySelectorAll('.cost-kpis-v3814,.v4050-planning').forEach(x=>x.remove());
  v1013WrapValidation(box);
  v1013WrapHeadingSection(box,'Etapas e recursos vinculados ao produto','v1013-etapas');
  v1013WrapHeadingSection(box,'Materiais/lotes vinculados à OP','v1013-materiais');
  return ret;
};

// O primeiro passo somente estrutura/pré-visualiza. Nenhuma OP é criada aqui.
v4050GeneratorForm=function(r,showRouteSelect=false){
  const routeField=showRouteSelect?`<label class="wide"><span>Roteiro salvo</span><select id="op_rot_v24">${(data.roteiro||[]).filter(x=>String(x.Ativo||'TRUE').toUpperCase()!=='FALSE'&&roteiroEstaSalvoV387(x)).map(x=>`<option value="${htmlEscape(x.CodRoteiro||'')}">${htmlEscape((x.CodRoteiro||'')+' | '+(x.CodigoProduto||'')+' | '+(x.DescricaoRoteiro||''))}</option>`).join('')}</select></label>`:`<label class="wide"><span>Roteiro-base</span><input value="${htmlEscape((r?.CodRoteiro||'')+' — '+(r?.DescricaoRoteiro||r?.CodigoProduto||''))}" readonly></label>`;
  return `<div class="form v1013-generator"><h3>Preparar estrutura das OPs</h3><div class="form-grid">${routeField}<label class="wide"><span>Formulação dos slurrys</span><select id="op_formula_v3813">${formulaOptionsV3813()}</select></label></div><div class="form-actions"><button class="green" id="v4050_gen_btn">Estruturar OP</button><button class="secondary" onclick="$('crudBox').innerHTML=''">Cancelar</button></div><p class="muted">Primeiro estruture e valide a família. Nenhuma OP é criada nesta etapa. Após conferir PIs, origens, quantidades e lotes, use o botão <b>Gerar OPs</b>.</p></div>`;
};

// Pré-visualização estruturada: segundo botão é o único que efetivamente cria as OPs.
v1011PlanningRowsHTML=function(r,codFormula){
  const rows=v1011RouteProducts(r);
  return `<div class="v1011-family-plan"><div class="card"><h3>Estrutura das OPs — validar antes de gerar</h3><p class="muted">A formulação <b>${htmlEscape(codFormula||'')}</b> será aplicada somente aos slurrys. Os demais PIs são consumidos pela etapa seguinte. Um PI pronto/lote existente elimina a necessidade de uma nova OP para fabricá-lo.</p><div class="table-wrap"><table><thead><tr><th>Seq.</th><th>PI / PA</th><th>Nome</th><th>Processo</th><th>Origem</th><th>Lote PI pronto</th><th>Quantidade / massa</th><th>UM</th></tr></thead><tbody>${rows.map((cod,i)=>{
    const p=v1011Prod(cod),role=v1011Role(cod),isPA=role==='PA',lots=isPA?[]:v1011LotsForRole(role),um=v101ProductUM(cod,r)||prodUMV382(cod)||unidadeProdutoV35(cod)||'un';
    const opts=lots.map(l=>`<option value="${htmlEscape(l.IdLotePI)}">${htmlEscape(v1011LotLabel(l))}</option>`).join('');
    return `<tr class="v1011-plan-row" data-code="${htmlEscape(cod)}" data-role="${role}"><td>${i+1}</td><td><b>${htmlEscape(cod)}</b></td><td>${htmlEscape(p['Descrição']||'')}</td><td>${htmlEscape(v1011RouteProcess(r,cod)||v1011RoleLabel(role))}</td><td>${isPA?'<b>Produzir PA</b>':`<select class="v1011-origin" onchange="v1011ToggleLot(this)"><option value="PRODUZIR">Produzir nova OP</option><option value="LOTE" ${lots.length?'':'disabled'}>Usar PI pronto / lote existente${lots.length?'':' (sem saldo)'}</option></select>`}</td><td>${isPA?'—':`<select class="v1011-lot" ${lots.length?'disabled':''}>${opts||'<option value="">Sem lote compatível</option>'}</select>`}</td><td><input class="v1011-qtd" type="number" min="0" step="0.000001" placeholder="Informe ${htmlEscape(um)}"></td><td><b>${htmlEscape(um)}</b></td></tr>`;
  }).join('')}</tbody></table></div><div class="form-actions"><button class="green" onclick="v1011ConfirmFamily('${jsq(r.CodRoteiro)}','${jsq(codFormula)}')">Gerar OPs</button><button class="secondary" onclick="novaOPPorRoteiro()">Voltar</button><button class="secondary" onclick="$('crudBox').innerHTML=''">Cancelar</button></div><p class="muted">Somente <b>Gerar OPs</b> grava a família no banco.</p></div></div>`;
};

// Mantém os gatilhos existentes, mas com semântica explícita Estruturar -> Gerar.
novaOPPorRoteiro=function(){
  const ativos=(data.roteiro||[]).filter(r=>String(r.Ativo||'TRUE').toUpperCase()!=='FALSE'&&roteiroEstaSalvoV387(r));
  if(!ativos.length)return alert('Não há roteiros salvos.');if(!formulasAtivasV3813().length)return alert('Não há formulação ativa.');
  const box=$('crudBox');if(!box)return;box.innerHTML=v4050GeneratorForm(null,true);$('v4050_gen_btn').onclick=confirmarNovaOPPorRoteiro;box.scrollIntoView({behavior:'smooth',block:'start'});
};
confirmarNovaOPPorRoteiro=function(){
  const r=(data.roteiro||[]).find(x=>x.CodRoteiro===$('op_rot_v24')?.value);if(!r)return alert('Selecione um roteiro.');
  const f=$('op_formula_v3813')?.value||'';if(!f)return alert('Selecione a formulação dos slurrys.');
  return gerarOPsComFormulaV3813(r,1,f); // esta função apenas monta a estrutura; não cria OPs
};

gerarOPDoRoteiroV29=function(){
  const r=roteiroAtualV382();if(!r?.CodRoteiro)return alert('Selecione um roteiro.');if(!roteiroEstaSalvoV387(r))return alert('Salve o roteiro antes de estruturar a OP.');if(!formulasAtivasV3813().length)return alert('Não há formulação ativa.');
  const box=$('crudBox');if(!box)return;box.innerHTML=v4050GeneratorForm(r,false);$('v4050_gen_btn').onclick=()=>gerarOPsComFormulaV3813(r,1,$('op_formula_v3813')?.value||'');box.scrollIntoView({behavior:'smooth',block:'start'});
};
gerarOPDoRoteiro=function(){return gerarOPDoRoteiroV29();};

try{
  data.meta=data.meta||{};data.meta.versao=APP_VERSION_V1013;data.meta.baseOperacional='Regras validadas consolidadas — Estruturar antes de gerar OP';
  saveLocal();document.title='MES LION V1.0.13';
}catch(e){console.warn('MES LION V1.0.13',e);}
